window.RECETTES=[{"id":"19376","nom":"Accras de morue et salade à la mangue, radis bleu et coriandre","image":"images/19376.webp","ingredients":[["carotte (100g)","1x"],["accras de morue creole","180 g"],["mangue","0.5"],["radis bleu","0.5"],["échalote","0.5"],["salade","50 g"],["coriandre (botte)","0.5"],["huile de sésame toasté","20 ml"]],"cuisine":["1 càs huile de cuisson","1 càs vinaigre de votre choix","sel","poivre"],"etapes":[{"titre":"Les accras","items":["Dans une poêle, faites chauffer un filet d'huile de cuisson à feu vif.","Faites dorer les accras de morue 6 à 8 min environ. Remuez régulièrement."]},{"titre":"La salade","items":["Ciselez (dés) l'échalote.","Épluchez et râpez la carotte.","Coupez la mangue en dés.","Épluchez le radis bleu et coupez-le en quart de rondelles.","Ciselez la coriandre (en entier les tiges se consomment).","Dans un saladier, versez l'huile de cuisson, l'huile de sésame et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette. Ajoutez l'échalote, la mangue, la carotte, le radis, la salade et la coriandre.","Mélangez bien, goûtez et rectifiez l'assaisonnement si nécessaire.","Dégustez la salade avec les accras."]}]},{"id":"15908","nom":"Accras de morue façon rougail mauricien et épinards poêlées","image":"images/15908.webp","ingredients":[["accras de morue créole","180 g"],["gousse d'ail (5g)","1x"],["pulpe de tomates","400 g"],["huile pimentée","10 ml"],["riz basmati","150 g"],["oignon jaune (110g)","1x"],["paprika (sachet)","0.25"],["gingembre","1 à 3 cm"],["pousses d'épinards","200 g"]],"cuisine":["sel","poivre","huile de cuisson","200 ml eau"],"etapes":[{"titre":"La sauce rougail","items":["Émincez l’oignon.","Pelez et hachez l'ail le gingembre.","Dans une cocotte, faites chauffer un filet d’huile de cuisson à feu moyen à vif.","Faites revenir l'oignon, la moitié de l'ail et le gingembre 10 min environ.","Au bout des 10 min, ajoutez la pulpe de tomates, le paprika et l'eau. Couvrez et poursuivez la cuisson 10 min. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les accras."]},{"titre":"Les accras","items":["Dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites dorer les accras de morue 6 à 8 min. Remuez régulièrement.","Pendant ce temps, faites cuire les épinards et le riz."]},{"titre":"Les pousses d'épinards et le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","En parallèle, dans une seconde poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir les pousses d'épinards et le reste d'ail 5 min environ.","Au moment de servir, nappez vos accras de sauce rougail et d'huile pimentée.","Suggestion : attention l'huile pimentée est forte, arrosez votre plat avec une petite quantité pour commencer et ajuster selon votre goût."]}]},{"id":"19373","nom":"Aiguillettes de poulet à la crème de piment chipotle et spaghetti","image":"images/19373.webp","ingredients":[["crème","100 g"],["citron jaune","0.5"],["gousse d'ail","0.5"],["aiguillette de poulet La Nouvelle Agriculture","250 g"],["spaghettis blanc","200 g"],["piment Chipotle (pincée) (0.8g)","2x"],["persil plat","qq brins"],["échalote (25g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La crème de piment chipotle","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Ciselez (dés) l’échalote.","Pressez ou hachez l'ail.","A l’aide d’une râpe, prélevez les zestes de citron (uniquement l’écorce de couleur).","Dans une petite casserole, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'échalote, l'ail et le piment chipotle 2 min.","Ajoutez la crème et les zestes de citron. Mélangez et faites chauffer 5 min environ à feu moyen à couvert.","Astuce : le piment chipotle est fort, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût.","Goûtez et rectifiez l’assaisonnement si nécessaire.","Pendant que la crème chauffe, faites cuire le poulet."]},{"titre":"Les aiguillettes de poulet","items":["Portez à ébullition une casserole d'eau salée pour faire cuire les pâtes.","Épongez la viande à l'aide d'un essuie-tout. Salez, poivrez.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les aiguillettes de poulet 5 min. Salez, poivrez.","Au bout des 5 min, ajoutez la crème de piment chipotle et mélangez 2 min à feu doux jusqu'à ce que le poulet soit cuit à coeur (la chair n'est plus rose).","En parallèle, faites cuire les spaghettis."]},{"titre":"Les spaghettis","items":["Faites cuire les pâtes selon les indications du paquet.","En parallèle, effeuillez et ciselez le persil.","Au moment de passer à table, parsemez vos spaghettis avec le persil."]}]},{"id":"19486","nom":"Asian pasta aux shimejis et sauce pimentée au curry rouge","image":"images/19486.webp","ingredients":[["gousse d'ail (6g)","1x"],["sauce curry rouge","100 g"],["carotte (100g)","1x"],["nouilles asiatiques","120 g"],["citronnelle (10g)","1x"],["échalote (25g)","1x"],["champignon shimeji","150 g"],["chou pak choy (135g)","1x"]],"cuisine":["huile de cuisson","sel","poivre","50 ml eau"],"etapes":[{"titre":"Les légumes","items":["Emincez l'échalote.","Retirez la partie racine de la citronnelle (5 cm environ). Emincez finement le reste.","Pressez ou hachez l'ail.","Epluchez et coupez la carotte en fins bâtonnets.","Coupez la base et émincez le chou pak choy.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'échalote, la citronnelle et l'ail 2 à 3 min.","Ajoutez le chou pak choy, la carotte et les shimejis. Poursuivez la cuisson 15 min environ. Salez, poivrez."]},{"titre":"La sauce curry","items":["Au bout des 15 min de cuisson des légumes, ajoutez la sauce curry rouge et l'eau. Salez légèrement.","Faites cuire à couvert 5 à 7 min.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, faites cuire les nouilles."]},{"titre":"Les nouilles asiatiques","items":["Portez à ébullition une casserole d’eau salée. Faites cuire les nouilles asiatiques selon les indications du paquet.","Conservez 1 louche d'eau de cuisson pour 2 personnes.","Une fois le tout cuit, ajoutez les nouilles et l'eau de cuisson à la sauteuse des légumes au curry rouge.","Poursuivez la cuisson 1 min pour réchauffer le tout.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"18656","nom":"Bagel à la poire rôtie, gorgonzola et noisettes","image":"images/18656.webp","ingredients":[["pain bagel (160g)","2x"],["noisettes décortiquées","25 g"],["gorgonzola","75 g"],["carotte (100g)","1x"],["poire (110g)","1x"],["pousses d'épinards","50 g"]],"cuisine":["sel","poivre","2 càs huile d'olive","beurre","1 càs vinaigre de votre choix"],"etapes":[{"titre":"La poire rôtie","items":["Coupez la poire en fins quartiers.","Dans une poêle, faites chauffer une noix de beurre à feu moyen.","Faites revenir la poire 5 min environ sur chaque face.","En parallèle, préparez les bagels et la salade."]},{"titre":"Les bagels","items":["Coupez le gorgonzola en morceaux.","Hachez les noisettes.","Coupez les pains bagel en deux et faites-les dorer quelques minutes au grille-pain.","Sur la base de chaque pain, déposez le gorgonzola, la poire rôtie, quelques pousses d'épinards et parsemez de noisettes.","Refermez les pains bagel."]},{"titre":"La salade","items":["A l'aide d'un économe, épluchez et réalisez des tagliatelles de carotte.","Dans un saladier, mélangez l'huile d'olive et le vinaigre pour obtenir une vinaigrette. Salez, poivrez.","Ajoutez le reste des pousses d'épinards, le reste des noisettes et la carotte."]}]},{"id":"21874","nom":"Bagel à la poitrine fumée, poire et pousses d'épinards","image":"images/21874.webp","ingredients":[["pain bagel (160g)","2x"],["poitrine fumée (90g)","90 g"],["fromage blanc (50g)","50 g"],["oignons frits (sachet) (4g)","0.5"],["huile d'olive infusée à l'ail (9g)","10 ml"],["ciboulette (5g)","qq brins"],["oignon rouge (20g)","0.25"],["poire (55g)","0.5"],["pousses d'épinards (50g)","50 g"]],"cuisine":["sel","poivre","2 oeuf","1 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"La poitrine fumée","items":["Faites chauffer une sans matière grasse à feu vif.","Faites dorer la poitrine fumée 5 min environ jusqu'à ce qu'elle soit bien colorée. Remuez régulièrement.","Lorsque la poitrine fumée est cuite, réservez-la sur une assiette et gardez la poêle pour les oeufs au plat.","Pendant la cuisson de la poitrine fumée, réalisez la sauce."]},{"titre":"La sauce","items":["Ciselez la ciboulette.","Dans un bol, mélangez le fromage blanc et la ciboulette. Salez, poivrez."]},{"titre":"Les oeufs au plat","items":["Dans la poêle de la poitrine fumée, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites cuire les œufs au plat 3 min environ. Salez, poivrez."]},{"titre":"Les bagels","items":["Coupez les pains bagels en deux. Faites-les dorer au grille-pain.","Coupez l'oignon en rondelles.","Coupez la poire en fines lamelles.","Sur chaque base de pain, déposez de la sauce, de la poitrine fumée, de l'oignon, quelques pousses d'épinards et des lamelles de poires, un œuf au plat.","Parsemez d'oignons frits et refermez les bagels.","Dans un saladier, versez l'huile d'olive infusée à l'ail, l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez pour obtenir une vinaigrette.","Ajoutez le reste de pousses d'épinards et le reste de poires."]}]},{"id":"19030","nom":"Bagel au Portobello, oignon confit, sauce au fromage blanc à la ciboulette","image":"images/19030.webp","ingredients":[["pain bagel (160g)","2x"],["sirop d'érable","10 ml"],["fromage blanc","50 g"],["ciboulette rondelle","2 pincée"],["pousses d'épinards","50 g"],["échalote","0.5"],["oignon rouge (110g)","1x"],["champignon Portobello","180 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","1 càc moutarde"],"etapes":[{"titre":"L'oignon confit","items":["Émincez l'oignon.","Dans une petite casserole, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et le sirop d'érable 10 à 12 min jusqu’à ce qu’il soit confit. Salez, poivrez. Remuez régulièrement.","En parallèle, faites cuire les champignons."]},{"titre":"Les champignons","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les champignons Portobello en entier 5 à 7 min. Retournez-les régulièrement. Salez, poivrez.","Pendant ce temps, préparez la sauce."]},{"titre":"La sauce","items":["Ciselez (dés) l'échalote.","Dans un bol, mélangez l'échalote, la moutarde, le fromage blanc et la ciboulette. Salez, poivrez. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les bagels","items":["Coupez les pains bagel en 2. Faites-les dorer au grille-pain.","Sur la base de chaque pain bagel, répartissez la sauce, les Portobellos, l'oignon confit et quelques feuilles de pousses d'épinards.","Refermez les bagels.","Assaisonnez le reste des pousses d'épinards d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"21120","nom":"Bagel aux rillettes de thon et crudités","image":"images/21120.webp","ingredients":[["fromage blanc (50g)","50 g"],["pain bagel (160g)","2x"],["roquette (50g)","50 g"],["oignon rouge (27.5g)","0.25"],["pomme de terre (440g)","2x"],["ciboulette (5g)","qq brins"],["thon entier au naturel (g égoutté) (93g)","93 g"],["tomate (100g)","1x"],["concombre noa (250g)","1x"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","0.5 càc moutarde"],"etapes":[{"titre":"Les pommes de terre sautées","items":["Épluchez et coupez les pommes de terre en dés.","Dans une sauteuse, faites chauffer un filet d’huile d’olive à feu vif.","Faites revenir les dés de pommes de terre 5 min pour les colorer légèrement.","Baissez sur feu moyen, couvrez et poursuivez la cuisson 15 min, en remuant régulièrement, jusqu’à ce qu’elles soient tendres. Salez, poivrez.","Pendant ce temps, préparez les rillettes de thon et les bagels."]},{"titre":"Les rillettes de thon","items":["Ciselez (dés) l'oignon.","Egouttez le thon.","Ciselez la ciboulette.","Dans un bol, mélangez le thon, l'oignon, le fromage blanc, la ciboulette et la moutarde. Salez, poivrez.","Mélangez bien.","Goûtez et ajoutez une pincée de sel ou un filet d'huile d'olive si nécessaire."]},{"titre":"Les bagels","items":["Coupez les pains bagel en deux et faites les dorer au grille-pain.","Pendant ce temps, épluchez le concombre.","Coupez la tomate et le concombre en fines rondelles.","Sur la base de chaque pain bagel, déposez des rillettes de thon, quelques rondelles de tomate et de concombre et quelques feuilles de roquette. Refermez les bagels.","Mélangez le reste de tomate, de concombre et de roquette. Assaisonnez-les d'un filet d'huile d'olive et de vinaigre. Salez, poivrez."]}]},{"id":"17287","nom":"Bagel mortadelle et tzatzíki de concombre","image":"images/17287.webp","ingredients":[["pain bagel (160g)","2x"],["fromage blanc","100 g"],["mortadelle aux pistaches","90 g"],["sucrine (170g)","1x"],["échalote","0.5"],["concombre bio (250g)","1x"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"Le tzatzíki","items":["Dans un bol, déposez les ingrédients suivants :","Epluchez et râpez la moitié du concombre (pressez-le pour retirer un maximum d'eau). Gardez l'autre moitié pour la salade.","Ajoutez le fromage blanc, un filet d'huile d'olive, salez et poivrez. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les bagels","items":["Ouvrez les pains bagel et faites-les dorer au grille-pain.","Coupez l'échalote en rondelles.","Coupez la base de la sucrine et gardez 1 à 2 feuilles par personne. Emincez le reste.","Déchirez la mortadelle.","Sur la base de chaque pain bagel, étalez le tzatzíki. Répartissez dessus un peu d'échalote, la mortadelle et les feuilles de sucrine. Refermez les bagel."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Versez l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Coupez le reste de concombre en fines demi-rondelles.","Ajoutez la sucrine émincée."]}]},{"id":"21675","nom":"Bò tái chanh (carpaccio de boeuf à la coriandre et citron)","image":"images/21675.webp","ingredients":[["carpaccio tranche ronde (200g)","200 g"],["oignons frits (sachet) (8g)","1x"],["nuoc mam (sauce poisson) (18g)","15 ml"],["cacahuètes grillées sans sel (25g)","25 g"],["cébette (8g)","0.5"],["citron vert (45g)","0.5"],["coriandre (10g)","0.5"],["échalote (25g)","1x"],["riz concassé du Pendjab (150g)","150 g"]],"cuisine":["sel","poivre","1 càs huile de cuisson","2 càs eau","2 càc sucre"],"etapes":[{"titre":"La marinade","items":["Dans un bol, mélangez l'eau, le sucre, le nuoc mam et l'huile de cuisson jusqu'à ce que le sucre soit dissous. Salez, poivrez.","Ajoutez le carpaccio et mélangez bien.","Réservez au frais le temps de préparer le reste des ingrédients."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","En parallèle, préparez le reste des ingrédients."]},{"titre":"Le bò tái chanh","items":["Emincez l'échalote.","Ciselez grossièrement la coriandre (en entier, les tiges se consomment).","Retirez la base de la cébette et émincez-la.","Hachez les cacahuètes.","Coupez le citron en quartiers.","Dans des bols ou des assiettes creuses, répartissez le riz et déposez dessus le carpaccio arrosé de la marinade et d'un filet de citron. Parsemez le tout d'échalote, de cacahuètes, de coriandre, de cébette et d'oignons frits.","Astuce : si vous souhaitez garder le contraste riz chaud / bœuf froid, servez le carpaccio à part et ajoutez-le sur le riz juste avant de manger."]}]},{"id":"18355","nom":"Bouillon chinois d'hiver aux carottes et shiitakés","image":"images/18355.webp","ingredients":[["sauce soja salée","20 ml"],["vinaigre de riz","20 ml"],["champignon shiitaké","200 g"],["carotte (200g)","2x"],["gingembre","1 à 3 cm"],["coriandre","qq brins"],["pomme de terre","500 g"],["cacahuètes grillées","25 g"]],"cuisine":["600 ml eau","sel","poivre","huile de cuisson"],"etapes":[{"titre":"La préparation","items":["Épluchez et coupez les pommes de terre en morceaux.","Épluchez et râpez les carottes.","Coupez les champignons en fines tranches.","Épluchez et hachez finement le gingembre."]},{"titre":"Le bouillon","items":["Dans une casserole, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir les carottes, le gingembre et les champignons 3 min environ.","Ajoutez la sauce soja, l'eau, les pommes de terre et portez à ébullition.","Baissez le feu et faites cuire 12 à 15 min à petite ébullition jusqu'à ce que les pommes de terre soient fondantes mais pas réduites en purée. Salez légèrement, poivrez.","Hachez grossièrement les cacahuètes.","Ciselez la coriandre (en entier, les tiges se consomment).","Au moment de servir, ajoutez le vinaigre de riz et parsemez de cacahuètes et de coriandre.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"13935","nom":"Bouillon pappardelle, courgette et bolognaise de porc","image":"images/13935.webp","ingredients":[["feuilles de lasagne (250g)","250 g"],["purée de tomates (80g)","80 g"],["oignon jaune (55g)","0.5"],["courgette (200g)","1x"],["basilic (5g)","qq brins"],["chair à saucisse (240g) Bleu Blanc Coeur","240 g"]],"cuisine":["sel","poivre","0.5 cube bouillon de légumes","400 ml eau","huile d'olive"],"etapes":[{"titre":"Le bouillon","items":["Coupez la courgette en rondelles.","Ciselez (dés) l'oignon.","Dans une casserole, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir la chair à saucisse émiettée 5 min environ. Puis, réservez-la sur une assiette.","Dans la même casserole, faites revenir l'oignon et la courgette 5 min jusqu'à ce qu'ils commencent à dorer.","Au bout des 5 min, ajoutez la purée de tomates, le bouillon de légumes émietté, l'eau et la chair à saucisse.","Laissez mijoter 15 min à feu doux à couvert.","En parallèle, faites cuire les pâtes à lasagne."]},{"titre":"Les pâtes à lasagne","items":["Portez à ébullition une grande casserole d’eau salée.","Coupez les feuilles à lasagne en 5 dans la longueur.","Astuce : utilisez des ciseaux pour aller plus vite !","Faites cuire les bandes de pâte 3 min. Mélangez régulièrement.","Une fois cuites, égouttez-les et ajoutez un filet d'huile d'olive pour éviter qu'elles collent.","Ajoutez-les à la casserole de la soupe en fin de cuisson et mélangez le tout.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Effeuillez et ciselez le basilic.","Parsemez le bouillon de basilic au moment de servir."]}]},{"id":"8585","nom":"Boulgour au chèvre frais et duo de champignons","image":"images/8585.webp","ingredients":[["oignon jaune (130g)","1x"],["champignons de Paris blancs","250 g"],["champignon Portobello","90 g"],["persil plat","qq brins"],["gousse d'ail","0.5"],["fromage de chèvre frais aux herbes et baies rouges","70 g"],["boulgour","150 g"]],"cuisine":["sel","poivre","300 ml eau","huile d'olive","0.5 bouillon de légumes (cube)"],"etapes":[{"titre":"La préparation","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Coupez les champignons de Paris et le Portobello en tranches."]},{"titre":"La cuisson","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, les champignons de Paris, le Portobello et l'ail 5 min environ. Salez, poivrez.","Au bout des 5 min, ajoutez le boulgour, l'eau et le bouillon de légumes.","Couvrez et poursuivez la cuisson 10 min environ en remuant régulièrement.","Pendant ce temps, effeuillez et ciselez le persil.","En fin de cuisson, ajoutez le chèvre frais et le persil et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"8998","nom":"Boulgour sauté à l'orange, crevettes et curcuma frais","image":"images/8998.webp","ingredients":[["crevettes cuites nature","125 g"],["orange (150g)","1x"],["sauce soja salée","20 ml"],["gousse d'ail","0.5"],["curcuma frais (racine)","1 à 3 cm"],["pousses d'épinards","50 g"],["poireau (300g)","1x"],["boulgour","150 g"]],"cuisine":["beurre","huile de cuisson (mélange 4 huiles par exemple)","sel","poivre"],"etapes":[{"titre":"Le boulgour","items":["Portez à ébullition une casserole d'eau salée.","Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Faites cuire le boulgour et le poireau selon les indications du paquet de boulgour.","Pendant ce temps, préparez la garniture."]},{"titre":"La garniture aux crevettes","items":["Pelez et hachez finement le curcuma.","Pressez ou hachez l'ail.","Posez l’orange à plat. Coupez les extrémités. Avec un couteau tranchant en épousant la forme du fruit, retirez la peau et les membranes blanches autour de l’agrume. Tenez ensuite l’orange dans le creux de la main et passez votre couteau entre chaque membrane pour détacher les tranches (segments). Coupez les segments en 2. Une fois les tranches retirées, pressez le reste pour récupérer le jus.","Dans une sauteuse, faites chauffer une noix de beurre à feu moyen à vif.","Faites cuire les crevettes avec l'ail et les pousses épinards 2 à 3 min puis réservez-les sur une assiette. Salez, poivrez."]},{"titre":"A table !","items":["Une fois le tout cuit, dans la sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir le boulgour et le poireau avec la sauce soja, le curcuma et le jus d'orange 2 à 3 min.","Hors du feu, ajoutez les crevettes et les segments d'orange à la sauteuse.","Mélangez bien, goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"19067","nom":"Bowl avocat, mangue, radis et vinaigrette piment/coco","image":"images/19067.webp","ingredients":[["sauce soja salée","20 ml"],["vinaigre de riz","10 ml"],["riz rond blanc","150 g"],["noix de coco râpée","10 g"],["sésame doré","10 g"],["citron vert (90g)","1x"],["avocat (180g)","1x"],["mangue","0.5"],["oignon rouge","0.25"],["piment oiseau (2g)","1x"],["radis bleu","0.5"]],"cuisine":["2 càs huile d'olive","sel","poivre"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz rond selon les indications du paquet.","Pendant ce temps, préparez la vinaigrette et le reste des ingrédients."]},{"titre":"La vinaigrette piment coco","items":["Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Ciselez (dés) l'oignon rouge.","Pressez la moitié du citron.","Dans un bol, versez l'huile d'olive, la sauce soja et la noix de coco. Poivrez et mélangez bien pour obtenir une vinaigrette. Ne salez pas, la sauce soja apporte déjà du sel.","Ajoutez le piment, l'oignon et le jus de citron vert et mélangez bien."]},{"titre":"Le riz vinaigré","items":["Une fois le riz cuit, égouttez-le. Ajoutez le vinaigre de riz et le sésame doré. Salez, poivrez et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Laissez refroidir à température ambiante le temps de la recette."]},{"titre":"Les bowls","items":["Coupez l'avocat en fines lamelles.","Épluchez et coupez la mangue en morceaux.","Épluchez et coupez le radis bleu en quarts de rondelles.","Dans des bols ou des assiettes creuses, déposez le riz vinaigré légèrement tiédi.","Répartissez par-dessus l'avocat, la mangue et le radis.","Nappez le tout avec la vinaigrette piment coco.","Coupez le reste du citron en quartiers et arrosez votre bowl d'un filet de jus de citron au moment de servir."]}]},{"id":"16982","nom":"Bowl de poulet, concombre au gingembre et nectarine","image":"images/16982.webp","ingredients":[["sauce soja salée (46g)","40 ml"],["oignons frits (sachet) (4g)","0.5"],["mayonnaise (20g)","20 ml"],["nectarine (130g)","1x"],["concombre lisse (275g)","1x"],["aiguillette de poulet La Nouvelle Agriculture (250g)","250 g"],["gingembre (20g)","1 à 3 cm"],["riz concassé du Pendjab (150g)","150 g"]],"cuisine":["1 càs huile de cuisson","sel","poivre","0.5 cube bouillon de poule","farine"],"etapes":[{"titre":"Le riz","items":["Pelez et hachez le gingembre.","Portez à ébullition une casserole d'eau avec le bouillon de poule et la moitié du gingembre.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez le poulet."]},{"titre":"Le poulet","items":["Déposez un peu de farine dans une assiette.","Enrobez les aiguillettes de farine.","Dans une sauteuse, faites chauffer un bon filet d'huile de cuisson à feu vif.","Faites revenir le poulet 5 min environ jusqu'à ce qu'il soit doré et cuit à coeur (la chair n'est plus rose). Salez légèrement, poivrez et retounez à mi-cuisson.","Ajoutez la moitié de la sauce soja et mélangez 1 min environ en remuant bien pour enrober le poulet.","Réservez la sauteuse hors du feu."]},{"titre":"Les bowls","items":["Coupez la nectarine en fins quartiers.","Épluchez et râpez le concombre.","Pressez légèrement le concombre râpé entre vos mains pour retirer l'excédent d'eau.","Dans un bol, mélangez le concombre, l'huile de cuisson et le reste du gingembre. Salez, poivrez.","Dans un second bol, déposez le reste de sauce soja et la mayonnaise. Mélangez bien.","Dans des bols, répartissez le riz. Déposez par-dessus le poulet, la nectarine et le condiment au concombre.","Arrosez le tout de mayonnaise au soja et parsemez d'oignons frits."]}]},{"id":"11525","nom":"Bowl mexicain d'effiloché de bœuf, avocat au piment et cheddar","image":"images/11525.webp","ingredients":[["effiloché de boeuf","200 g"],["avocat (180g)","1x"],["tomate (200g)","2x"],["cheddar râpé","60 g"],["oignon rouge","0.25"],["riz basmati","150 g"],["gousse d'ail","0.5"],["piment oiseau (2g)","1x"]],"cuisine":["sel","poivre","huile d'olive","2 càs huile d'olive"],"etapes":[{"titre":"Le riz basmati","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Une fois cuit, égouttez-le et passez-le sous l'eau froide pour le refroidir. Salez, poivrez.","En parallèle, faites cuire le boeuf effiloché."]},{"titre":"Le boeuf effiloché","items":["Pressez ou hachez l'ail.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'effiloché de boeuf et l'ail 5 min. Salez, poivrez.","Pendant ce temps, préparez le pico de gallo et l'avocat."]},{"titre":"Le pico de gallo et l'avocat","items":["Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Dans un bol, écrasez l'avocat. Ajoutez un filet d'huile d'olive et le piment. Salez, poivrez. Mélangez bien.","Dans un second bol, déposez les ingrédients suivants :","Coupez les tomates en petits dés.","Ciselez (dés) finement l'oignon rouge.","Ajoutez l'huile d'olive. Salez, poivrez. Mélangez bien.","Goûtez les préparations et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les bowls","items":["Dans des bols ou assiettes creuses, déposez au fond le riz.","Répartissez dessus en compartiments le boeuf, l'avocat et le pico de gallo. Parsemez le cheddar râpé sur les bowls."]}]},{"id":"15057","nom":"Brie farci aux fruits secs rôti et mouillettes de pain aux épices","image":"images/15057.webp","ingredients":[["brie pasteurisé","200 g"],["fromage blanc","50 g"],["mélange de fruits secs vatel (cacahuètes, noix de cajou, amandes, noix de pécan, graines de courge)","25 g"],["oignon jaune (125g)","1x"],["petits pains aux épices (160g)","2x"],["multifeuille","50 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","2 càc sucre"],"etapes":[{"titre":"Le brie farci aux fruits secs rôti","items":["Préchauffez votre four à 180°C en chaleur tournante !","Pendant ce temps, hachez le mélange de fruits secs.","Dans un bol, mélangez le fromage blanc et les fruits secs. Salez, poivrez.","Coupez le brie en deux dans l'épaisseur. Creusez légèrement le fromage et déposez le mélange de fruits secs et fromage blanc dans le creux.","Déposez les demi-bries farcis sur une plaque allant au four munie de papier cuisson."]},{"titre":"Les mouillettes","items":["Coupez les petits pains en mouillettes.","Placez-les à côté du brie, versez un filet d'huile d'olive, salez et poivrez-les.","Enfournez le tout 12 à 15 min jusqu'à ce que les mouillettes soient dorées et le fromage coulant.","En parallèle, préparez l'oignon confit."]},{"titre":"L'oignon confit","items":["Emincez l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et le sucre 12 à 15 min. Remuez régulièrement. Salez, poivrez."]},{"titre":"A table !","items":["Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre.","Une fois cuit, déposez l'oignon confit sur le brie."]},{"titre":"","items":["Servez sans attendre votre brie farci aux fruits secs rôti accompagné des mouillettes de pain aux épices et de la salade !"]}]},{"id":"16686","nom":"Brochettes de poulet teriyaki et nouilles sautées au chou pak choy","image":"images/16686.webp","ingredients":[["sauce soja salée","20 ml"],["chou pak choy (270g)","2x"],["oignon jaune","0.5"],["gingembre","1 à 3 cm"],["nouilles asiatiques","120 g"],["vinaigre de riz","10 ml"],["filet de poulet La Nouvelle Agriculture (300g)","2x"]],"cuisine":["sel","poivre","1 càs sucre","huile de cuisson","2 càs eau"],"etapes":[{"titre":"Les choux pak choy","items":["Émincez l'oignon.","Retirez la base des choux pak choy et émincez-les.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon et les choux pak choy 10 min environ. Salez, poivrez.","A mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson.","Pendant ce temps, préparez les brochettes."]},{"titre":"Les brochettes","items":["Dans un saladier, déposez les ingrédients suivants :","Coupez le poulet en morceaux.","Épluchez et hachez finement le gingembre.","Ajoutez le sucre, l'eau, la sauce soja et le vinaigre de riz.","Mélangez bien.","Placez les morceaux de poulet sur des piques à brochettes de manière à obtenir 2 brochettes par personne. Réservez la marinade."]},{"titre":"La cuisson des brochettes","items":["Dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir les brochettes 5 min en les retournant régulièrement.","Au bout des 5 min de cuisson, ajoutez la marinade et poursuivez la cuisson 5 min supplémentaires.","Penchez la poêle et nappez les brochettes avec la marinade pour bien les enrober.","En parallèle, faites cuire les nouilles."]},{"titre":"Les nouilles sautées","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les nouilles asiatiques selon les indications du paquet. Égouttez-les.","Une fois cuites, ajoutez-les dans la sauteuse des légumes et faites chauffer le tout 2 à 3 min. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"9323","nom":"Brochettes de poulet, nectarine et courgette au citron","image":"images/9323.webp","ingredients":[["citron jaune","0.5"],["courgette","0.5"],["menthe","qq brins"],["filet de poulet La Nouvelle Agriculture (300g)","2x"],["graines de couscous","150 g"],["nectarine (130g)","1x"]],"cuisine":["sel","poivre","200 ml eau","huile d'olive","beurre"],"etapes":[{"titre":"Les brochettes","items":["Dans un saladier, déposez les ingrédients suivants :","Coupez le poulet et la nectarine en morceaux.","Coupez la courgette en demi-rondelles.","Pressez le citron jaune.","Versez un filet d'huile d'olive. Salez, poivrez et mélangez bien.","Sur des piques à brochette, alternez les morceaux de poulet, de nectarine et de courgette.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les brochettes 7 à 10 min jusqu'à ce que le poulet soit cuit à coeur (la chair n'est plus rose).","En parallèle, faites cuire les graines de couscous."]},{"titre":"Les graines de couscous","items":["Portez à ébullition l'eau et déposez les graines de couscous dans un récipient. Versez l'eau sur les graines de couscous.","Couvrez et laissez gonfler 5 min. Une fois cuites, ajoutez-y une noix de beurre ou un filet d'huile d'olive. Salez, poivrez et égrainez (séparer les grains) avec une fourchette.","Effeuillez et ciselez la menthe.","Au moment de servir, parsemez la menthe sur l'ensemble de la recette."]}]},{"id":"17891","nom":"Bruschette façon regina (mozzarella, champignons, et jambon de Paris)","image":"images/17891.webp","ingredients":[["pain de campagne (tranche) (100g)","4x"],["mozzarella râpée","30 g"],["jambon de Paris (tranche) (110g)","2x"],["gousse d'ail (4g)","1x"],["double concentré de tomates","40 g"],["champignons de Paris blancs","250 g"],["mélange de salade","50 g"]],"cuisine":["sel","poivre","2 càc huile d'olive (sauce tomate)","2 càs huile d'olive (salade)","1 càs vinaigre de votre choix"],"etapes":[{"titre":"La préparation","items":["Préchauffez votre four à 250°C en mode grill !","Pendant ce temps, pressez ou hachez l'ail.","Dans un bol, mélangez le concentré de tomates, l'ail et l'huile d'olive. Salez, poivrez.","Astuce : Pour réduire l'acidité du concentré de tomates, ajoutez une pincée de sucre.","Coupez les champignons en tranches.","Astuce<em> :</em> Pour des champignons moins humides sur les tartines, vous pouvez les poêler 2 à 3 min à feu vif sans matière grasse avant de les ajouter.","Coupez le jambon en morceaux."]},{"titre":"Les bruschettas","items":["Déposez les tranches de pain sur une plaque allant au four.","Etalez dessus la sauce à la tomate.","Répartissez le jambon et quelques champignons sans qu'ils ne se superposent (réservez le reste pour la salade).","Parsemez de mozzarella râpée.","Enfournez 5 min pour faire fondre le fromage."]},{"titre":"A table !","items":["Dans un saladier, mélangez l'huile d'olive et le vinaigre pour obtenir une vinaigrette. Salez, poivrez.","Ajoutez le reste de champignons et la salade."]}]},{"id":"17799","nom":"Burger au steak végétal, sauce fraîche à la menthe et salade d'épinards","image":"images/17799.webp","ingredients":[["pain à burger (200g)","2x"],["fromage blanc","100 g"],["burger nature végétal (200g)","2x"],["pousses d'épinards","50 g"],["oignon rouge","0.25"],["menthe","qq brins"]],"cuisine":["sel","poivre","vinaigre de votre choix","huile d'olive"],"etapes":[{"titre":"Les steaks végétaux","items":["Dans un poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les steaks végétaux 4 min de chaque côté. Salez, poivrez.","En parallèle, préparez la sauce."]},{"titre":"La sauce à la menthe","items":["Dans un bol, mélangez les ingrédients suivants :","Effeuillez et ciselez la menthe.","Ajoutez le fromage blanc et un filet d'huile d'olive. Salez, poivrez."]},{"titre":"Les burgers","items":["Coupez les pains à burger en 2 et faites-les dorer au grille-pain.","Émincez l'oignon rouge.","Sur la base de chaque pain à burger, étalez la sauce fraîche à la menthe.","Déposez un steak végétal, un peu d'oignon rouge et quelques feuilles de pousses d'épinards. Refermez les burgers.","Assaisonnez le reste des pousses d'épinards d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"18836","nom":"Burger de boeuf à la raclette et oignon confit","image":"images/18836.webp","ingredients":[["pain à burger (200g)","2x"],["raclette au lait cru de vache","60 g"],["steak haché façon bouchère (250g)","2x"],["pousses d'épinards","50 g"],["oignon rouge (220g)","2x"]],"cuisine":["sel","poivre","huile d'olive","1 càc sucre","1 càs moutarde","vinaigre de votre choix"],"etapes":[{"titre":"Les oignons","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Émincez les oignons.","Dans une petite casserole, faites chauffer un filet d’huile d'olive à feu moyen.","Faites revenir les oignons et le sucre 12 à 15 min jusqu’à ce qu’il soit légèrement confit. Salez, poivrez.","Pendant ce temps, faites cuire les steaks."]},{"titre":"La garniture","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les steaks hachés de boeuf 5 min environ. Salez, poivrez.","En parallèle, coupez et ouvrez les pains à burger en deux.","Faites-les dorer quelques minutes au grille-pain.","Coupez la raclette en fines tranches.","En fin de cuisson des steaks, déposez la raclette dessus et couvrez pour faire fondre le fromage."]},{"titre":"Les burgers","items":["Sur chaque pain à burger, étalez un peu de moutarde.","Déposez par-dessus un steak de boeuf à la raclette et un peu d’oignon confit. Refermez les burgers.","Assaisonnez les pousses d'épinards d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"22024","nom":"Burger de boeuf au fromage blanc à la truffe et noix","image":"images/22024.webp","ingredients":[["pain à burger (200g)","2x"],["fromage blanc (100g)","100 g"],["assaisonnement à la truffe d'été (sachet) (1g)","0.5"],["noix sèche (40g)","40 g"],["oignon rouge (20g)","0.25"],["salade (50g)","50 g"],["haché de bœuf (250g)","250 g"]],"cuisine":["huile d'olive","vinaigre de votre choix","sel","poivre"],"etapes":[{"titre":"Les steaks hachés","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Salez et poivrez les steaks hachés.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu vif.","Faites cuire les steaks 2 à 4 min de chaque côté selon la cuisson désirée.","En parallèle, préparez la sauce."]},{"titre":"La sauce","items":["Ouvrez et hachez les noix.","Dans un bol, mélangez le fromage blanc, les noix et l'assaisonnement à la truffe. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les burgers","items":["Ouvrez les pains à burger en 2 et faites-les dorer au grille-pain.","Coupez l'oignon en fines rondelles.","Sur la base de chaque pain à burger, étalez la sauce. Répartissez dessus un steak, de l'oignon rouge et quelques feuilles de salade. Refermez les burgers.","Assaisonnez le reste de salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"18071","nom":"Camembert rôti aux herbes de Provence et au miel","image":"images/18071.webp","ingredients":[["camembert (250g)","1x"],["miel","20 ml"],["baguette tradition","265 g"],["herbes de Provence (sachet)","0.25"],["salade","50 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix"],"etapes":[{"titre":"Le camembert rôti","items":["Préchauffez votre four à 200°C en chaleur tournante !","Pendant ce temps, déposez le camembert sur une plaque allant au four.","Réalisez une incision en croix sur le dessus du fromage (en surface pour qu'il ne coule pas trop à la cuisson).","Parsemez dessus les herbes de Provence et nappez de miel. Poivrez."]},{"titre":"Les mouillettes","items":["Coupez la baguette en deux dans l’épaisseur puis réalisez des mouillettes de 2 cm de long environ.","Placez-les à côté du camembert. Versez un filet d'huile d'olive, salez et poivrez-les.","Enfournez le tout 12 à 15 min jusqu'à ce que les mouillettes soient dorées et le fromage coulant.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"15391","nom":"Chili à l'émincé végétal tex-mex","image":"images/15391.webp","ingredients":[["émincés tex-mex 100% végétal","160 g"],["purée de tomates","250 g"],["mélange tex-mex (sachet)","0.5"],["haricots rouges conserve (g égouttés) (125g)","125x"],["riz basmati","150 g"],["gousse d'ail (4g)","1x"],["citron jaune","0.5"],["oignon rouge (130g)","1x"]],"cuisine":["sel","poivre","huile d'olive","0.25 bouillon de légumes (cube)"],"etapes":[{"titre":"Le chili","items":["Ciselez (dés) l'oignon.","Dans une sauteuse, faites chauffer un filet d’huile d’olive à feu moyen à vif.","Faites revenir l'oignon et les émincés végétaux 5 min.","Pendant ce temps, pressez ou hachez l'ail.","Égouttez et rincez les haricots rouges.","Au bout des 5 min, ajoutez la purée de tomates, les haricots rouges, le mélange tex mex, l'ail, le bouillon de légumes et versez de l'eau à mi-hauteur de la garniture. Salez, poivrez.","Couvrez et faites mijoter à feu doux 10 à 15 min.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Coupez le citron en quartiers."]},{"titre":"","items":["Servez sans attendre votre chili à l'émincé végétal tex-mex accompagné du riz ! Arrosez le tout d'un filet de jus de citron."]}]},{"id":"21865","nom":"Chili con carne","image":"images/21865.webp","ingredients":[["oignon jaune (55g)","0.5"],["carotte (120g)","1x"],["mélange tex mex (sachet) (3g)","0.5"],["purée de tomates (200g)","200 g"],["haricots rouges conserve (120g)","120 g égoutté"],["riz concassé du Pendjab (150g)","150 g"],["haché de bœuf (250g)","250 g"]],"cuisine":["sel","poivre","huile d'olive","0.25 bouillon de bœuf (cube)"],"etapes":[{"titre":"Le chili","items":["Émincez l'oignon.","Épluchez et coupez la carotte en dés.","Dans une sauteuse, faites chauffer un filet d’huile d’olive à feu moyen.","Faites revenir les steaks hachés émiettés, l'oignon, la carotte et le mélange tex-mex 10 min.","Au bout des 10 min, ajoutez la purée de tomates, les haricots égouttés, le bouillon de boeuf émietté et versez de l’eau à mi-hauteur de la garniture. Salez, poivrez.","Couvrez et faites mijoter à feu moyen 15 min environ jusqu'à ce que la carotte soit tendre.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet."]}]},{"id":"21962","nom":"Cobb salad végétarienne (fourme d'Ambert AOP, avocat et champignons)","image":"images/21962.webp","ingredients":[["pois chiches conserve (265g)","265 g égoutté"],["fourme d'Ambert (lait pasteurisé) (60g)","60 g"],["champignons de Paris blancs (250g)","250 g"],["oignon rouge (20g)","0.25"],["avocat (180g)","1x"],["salade (50g)","50 g"],["paprika fumé (1.6g)","2 càc"]],"cuisine":["sel","poivre","2 càs huile d'olive (vinaigrette)","1 càs vinaigre de votre choix","2 oeuf","2 càs huile d'olive (pois chiches)"],"etapes":[{"titre":"Les oeufs durs","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les œufs 9 min.","Une fois cuits, plongez-les dans un bol d'eau froide pour stopper la cuisson.","Pendant ce temps, préparez les pois chiches."]},{"titre":"Les pois chiches au paprika","items":["Égouttez et rincez les pois chiches.","Dans un bol, mélangez les pois chiches, le paprika fumé (plus ou moins selon votre goût) et l'huile d'olive. Salez, poivrez.","Faites chauffer une sauteuse sans matière grasse à feu moyen.","Faites revenir les pois chiches 5 min environ.","En parallèle, préparez le reste des ingrédients."]},{"titre":"La vinaigrette","items":["Ciselez (dés) l'oignon.","Dans un bol, mélangez l'oignon, l'huile d'olive et le vinaigre pour obtenir une vinaigrette. Salez, poivrez."]},{"titre":"La cobb salade","items":["Coupez la fourme d'Ambert en morceaux.","Coupez l'avocat en deux, retirez-en le noyau et prélevez sa chair avec une cuillère, puis coupez-la en tranches.","Coupez les champignons de Paris en tranches.","Écalez les oeufs et coupez-les en 2.","Dans des bols ou des assiettes creuses, déposez la salade. Répartissez dessus en compartiments ou en lignes les oeufs, l'avocat, la fourme d'Ambert, les champignons et les pois chiches.","Versez dessus la vinaigrette."]}]},{"id":"19126","nom":"Cobb salade végétarienne (fourme d'Ambert, avocat et endive)","image":"images/19126.webp","ingredients":[["fourme d'Ambert AOP (lait pasteurisé)","60 g"],["pois chiches conserve (g égoutté) (132.5g)","130x"],["paprika (sachet)","0.5"],["endive (110g)","1x"],["échalote","0.5"],["avocat (180g)","1x"],["salade","50 g"]],"cuisine":["sel","poivre","2 càs huile d'olive (vinaigrette)","1 càs vinaigre de votre choix","2 oeuf","2 càs huile d'olive (pois chiches)"],"etapes":[{"titre":"Les oeufs","items":["Portez à ébullition une casserole d'eau.","Faites cuire les œufs 9 min pour qu'ils soient durs.","Une fois cuits, passez-les sous l'eau froide pour stopper la cuisson.","Ecalez-les et coupez-les en 4.","Pendant la cuisson des œufs, préparez les pois chiches."]},{"titre":"Les pois chiches au paprika","items":["Égouttez et rincez les pois chiches.","Dans un saladier, mélangez les pois chiches avec le paprika et l’huile d’olive. Salez, poivrez.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les pois chiches avec la marinade 5 min.","En parallèle, préparez la salade."]},{"titre":"La cobb salade","items":["Ciselez (dés) l'échalote.","Retirez la base de l'endive. Coupez-la en 2 et retirez la partie centrale dure. Emincez-la.","Coupez la fourme d'Ambert en morceaux.","Coupez l'avocat en tranches.","Dans un saladier, versez l'huile d'olive et le vinaigre et ajoutez l'échalote. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ajoutez l'endive, l'avocat, la fourme d'Ambert, les œufs, la salade et les pois chiches. Mélangez le tout."]}]},{"id":"17986","nom":"Cocotte de paupiette de dinde aux endives caramélisées","image":"images/17986.webp","ingredients":[["paupiette de dinde (250g)","2x"],["riz basmati","150 g"],["noisettes décortiquées","25 g"],["oignon jaune (110g)","1x"],["endive (220g)","2x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","1 càs sucre","huile de cuisson","200 ml eau","0.25 cube bouillon de poule"],"etapes":[{"titre":"La cocotte","items":["Émincez l'oignon.","Retirez la base des endives. Coupez-les en 2 et retirez la partie centrale dure. Émincez-les.","Dans une cocotte, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites dorer les paupiettes 2 min sur chaque face. Une fois les paupiettes dorées, réservez-les sur une assiette.","Dans la même cocotte, faites chauffer de nouveau un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon, les endives et le sucre 5 min environ. Salez, poivrez.","Au bout de 5 min, ajoutez les paupiettes, l'eau et le bouillon de poule.","Couvrez et poursuivez la cuisson 20 à 25 min jusqu'à ce que les paupiettes soient cuites (leur chair n'est plus rose). Remuez régulièrement.","Astuce : s'il reste trop d'eau en fin de cuisson, faites chauffer à feu vif quelques minutes à découvert.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","En parallèle, concassez les noisettes.","Effeuillez et ciselez le persil.","Au moment de servir, parsemez votre assiette de noisettes et de persil."]}]},{"id":"17146","nom":"Coquillettes à la poitrine fumée, chèvre frais, courgette et origan","image":"images/17146.webp","ingredients":[["bûche de chèvre frais","80 g"],["origan séché (sachet)","0.25"],["gousse d'ail (4g)","1x"],["coquillettes demi-complètes","200 g"],["poitrine fumée","90 g"],["courgette (200g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les coquillettes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Une fois cuites, conservez un bol d'eau de cuisson pour la suite de la recette et égouttez-les.","Pendant ce temps, faites cuire le reste des ingrédients."]},{"titre":"La courgette et la poitrine fumée","items":["Pressez ou hachez l'ail.","Coupez la poitrine fumée en morceaux.","Coupez la courgette en petits dés.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'ail, la courgette, l'origan et la poitrine fumée 10 min environ.","Coupez le chèvre en morceaux.","Une fois le tout cuit, ajoutez le chèvre, les pâtes, une cuillère à soupe d'eau de cuisson par personne. Salez, poivrez.","Mélangez 1 à 2 min à feu moyen jusqu'à ce que la sauce soit homogène.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"18063","nom":"Coquillettes al ragù de porc, champignons et parmesan","image":"images/18063.webp","ingredients":[["gousse d'ail","0.5"],["champignons de Paris blancs","250 g"],["parmigiano reggiano râpé","20 g"],["chair à saucisse Bleu Blanc Coeur","240 g"],["coquillettes demi-complètes","200 g"],["cerfeuil-persil","qq brins"],["oignon jaune (110g)","1x"],["purée de tomates","200 g"]],"cuisine":["huile d'olive","sel","poivre"],"etapes":[{"titre":"Le ragù","items":["Emincez l'oignon.","Pressez ou hachez l'ail.","Coupez les champignons de Paris en fines tranches.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites dorer l'oignon 5 min.","Au bout des 5 min, ajoutez les champignons, l'ail et la chair à saucisse. Faites revenir le tout 5 à 6 min supplémentaires jusqu'à ce que les champignons soient dorés.","Ajoutez la purée de tomates et poursuivez la cuisson 5 à 7 min. Poivrez et salez légèrement (la chair à saucisse et le parmesan apportent déjà du sel).","Astuce : pour réduire l'acidité de la sauce tomate, ajoutez une cuillère à café de sucre.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant que le ragù cuit, faites cuire les coquillettes."]},{"titre":"Les coquillettes","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les coquillettes selon les indications du paquet.","Effeuillez et ciselez le persil et le cerfeuil.","Servez les coquillettes dans des assiettes chaudes, nappez de sauce, parsemez d’herbes fraîches et de parmesan."]}]},{"id":"17828","nom":"Coquillettes au saumon fumé, courgette et crème à l'ail","image":"images/17828.webp","ingredients":[["crème","100 g"],["saumon fumé","100 g"],["gousse d'ail (6g)","1x"],["citron jaune","0.5"],["coquillettes demi-complètes","200 g"],["oignon jaune (125g)","1x"],["courgette (400g)","2x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La préparation","items":["Émincez l'oignon.","Coupez la courgette en demi-rondelles.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et la courgette 10 min environ. Poivrez.","Suggestion : ne salez pas, le saumon fumé apporte déjà du sel.","En parallèle, coupez le saumon fumé en morceaux.","Pendant ce temps, faites cuire les coquillettes."]},{"titre":"Les coquillettes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les coquillettes selon les indications du paquet.","En parallèle, réalisez la crème à l'ail."]},{"titre":"La crème à l'ail","items":["Pressez ou hachez l'ail.","Pressez le citron.","Lorsque les légumes sont tendres, ajoutez l'ail et la crème à la sauteuse.","Laissez frémir 3 à 5 min.","Ajoutez les coquillettes, le saumon fumé et un filet de jus de citron dans la sauteuse. Mélangez bien et faites chauffer 1 à 2 min à feu doux pour que la sauce enrobe le tout.","Goûtez et rectifiez l’assaisonnement si nécessaire."]}]},{"id":"19251","nom":"Coquillettes crémeuses au jambon sec et champignons","image":"images/19251.webp","ingredients":[["jambon sec tranché","100 g"],["champignons de Paris blancs","250 g"],["crème","80 g"],["origan séché (sachet)","0.25"],["coquillettes demi-complètes","200 g"],["gousse d'ail (6g)","1x"]],"cuisine":["sel","poivre","huile d'olive","beurre"],"etapes":[{"titre":"Les champignons","items":["Portez à ébullition une casserole d'eau salée.","Pendant ce temps, coupez les champignons de Paris en tranches.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer une noix de beurre et un filet d'huile d'olive à feu vif.","Faites dorer les champignons, l'origan et l'ail 10 min environ jusqu'à ce qu'ils soient colorés. Salez, poivrez.","Astuce : les champignons sont prêts quand ils ont rendu leur eau et commencent à accrocher légèrement, avec une belle couleur brun-noisette."]},{"titre":"Les coquillettes","items":["Lorsque l'eau bout, faites cuire les pâtes selon les indications du paquet.","Astuce : lorsque les pâtes sont cuites, égouttez-les et réservez un peu d'eau de cuisson pour la sauce.","En parallèle, réalisez la sauce."]},{"titre":"A table !","items":["Coupez le jambon sec en lanières.","Dans la sauteuse des champignons, ajoutez la crème et le jambon sec. Laissez réduire 2 à 3 min ou jusqu'à ce que la sauce soit légèrement épaisse.","Ajoutez ensuite les pâtes et un peu d'eau de cuisson à la sauce et faites revenir le tout 2 à 3 min jusqu'à ce que les pâtes soient bien enrobées de sauce.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"16201","nom":"Coquillotto à la poitrine fumée, champignons et burrata","image":"images/16201.webp","ingredients":[["crème","100 g"],["poitrine fumée","90 g"],["burrata (120g)","1x"],["champignons de Paris blancs","250 g"],["gousse d'ail","0.5"],["coquillettes demi-complètes","200 g"],["oignon jaune (130g)","1x"]],"cuisine":["sel","poivre","huile d'olive","500 ml eau","0.5 cube bouillon de légumes"],"etapes":[{"titre":"La préparation","items":["Portez à ébullition l'eau et le bouillon de légumes.","Pendant ce temps, émincez l'oignon.","Coupez les champignons de Paris en tranches.","Pressez ou hachez l'ail."]},{"titre":"Le coquillotto","items":["Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et les champignons 3 min. Salez, poivrez.","Ajoutez les coquillettes et faites-les revenir 1 min pour bien les nacrer (les enrober d'huile).","Ajoutez le bouillon et l'ail.","Couvrez et faites cuire 12 à 15 min jusqu’à ce que les coquillettes soient cuites et le liquide absorbé. Remuez régulièrement.","Une fois le tout cuit, ajoutez la crème. Poursuivez la cuisson 1 à 2 min pour que tout soit chaud.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire la poitrine fumée."]},{"titre":"La poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Faites chauffer une poêle sans matière grasse à feu moyen à vif.","Faites dorer la poitrine fumée 5 min environ.","Une fois cuite, déposez-la sur une assiette munie d'un papier absorbant.","Coupez la burrata en morceaux.","Servez votre coquillotto parsemé de poitrine fumée et de burrata."]}]},{"id":"20972","nom":"Coquillotto à la poitrine fumée, courgette et burrata","image":"images/20972.webp","ingredients":[["crème (100g)","100 g"],["poitrine fumée (90g)","90 g"],["burrata (100g)","1x"],["gousse d'ail (3g)","0.5"],["coquillettes demi-complètes (200g)","200 g"],["oignon jaune (110g)","1x"],["courgette (200g)","1x"],["basilic (5g)","qq brins"]],"cuisine":["sel","poivre","huile d'olive","500 ml eau","0.5 cube bouillon de légumes"],"etapes":[{"titre":"La préparation","items":["Dans une casserole, portez à ébullition l'eau et le bouillon de légumes émietté.","Pendant ce temps, émincez l'oignon.","Coupez la courgette en dés.","Pressez ou hachez l'ail."]},{"titre":"Les pâtes","items":["Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, l'ail et la courgette 5 min. Salez, poivrez.","Ajoutez les coquillettes et faites-les revenir 1 min pour bien les nacrer (les enrober d'huile).","Versez le bouillon chaud.","Couvrez et faites cuire 12 à 15 min jusqu’à ce que les coquillettes soient cuites et le liquide absorbé. Remuez régulièrement.","En parallèle, faites cuire la poitrine fumée."]},{"titre":"La poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Faites chauffer une poêle sans matière grasse à feu vif.","Faites dorer la poitrine fumée 5 min environ. Remuez régulièrement.","Une fois dorée, déposez-la sur une assiette munie d'un papier absorbant."]},{"titre":"Le coquillotto","items":["Lorsque les coquillettes sont cuites, ajoutez la crème. Poursuivez la cuisson 1 à 2 min pour que tout soit chaud.","Goûtez et ajoutez une pincée de sel si nécessaire.","Coupez la burrata en morceaux.","Effeuillez et ciselez le basilic.","Servez le coquillotto parsemé de poitrine fumée, de burrata et de basilic."]}]},{"id":"19280","nom":"Coquillotto au cheddar, poitrine fumée et chapelure panko au piment chipotle","image":"images/19280.webp","ingredients":[["cheddar râpé","90 g"],["poitrine fumée","90 g"],["sauce soja salée","20 ml"],["piment chipotle (pincée) (0.8g)","2x"],["gousse d'ail","0.5"],["ciboulette rondelle (sachet)","0.25"],["chapelure panko","25 g"],["coquillettes demi-complètes","200 g"],["concentré de tomates","30 g"],["échalote (25g)","1x"]],"cuisine":["sel","poivre","huile d'olive","500 ml eau","0.5 bouillon de poule (cube)"],"etapes":[{"titre":"La poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Faites chauffer une sauteuse sans matière grasse à feu vif.","Faites dorer la poitrine fumée 5 min. Réservez-la sur une assiette et conservez la sauteuse avec la matière grasse."]},{"titre":"Le coquillotto","items":["Ciselez (dés) l'échalote.","Dans une casserole, portez à ébullition l'eau et le bouillon de poule.","Dans la même sauteuse que la poitrine fumée, faites revenir l'échalote et les coquillettes 2 min pour les nacrer (les enrober de matière grasse).","Ajoutez le concentré de tomates, la sauce soja, la ciboulette et mélangez bien. Salez légèrement, poivrez. La sauce soja et le bouillon apportent déjà du sel.","Versez le bouillon, couvrez et faites cuire 12 à 15 min jusqu’à ce que le liquide soit absorbé et les coquillettes cuites. Remuez régulièrement.","Astuce : ajoutez de l'eau en cours de cuisson si nécessaire.","Pendant ce temps, préparez la chapelure."]},{"titre":"La chapelure panko au piment chipotle","items":["Pressez ou hachez l'ail.","Dans une petite poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'ail, la chapelure panko et le piment chipotle 2 à 3 min. Remuez régulièrement.","Astuce : le piment chipotle est fort, ajoutez-en une petite quantité pour commencer et ajustez selon votre goût."]},{"titre":"A table !","items":["Une fois le coquillotto cuit, ajoutez le cheddar et la poitrine fumée aux coquillettes. Mélangez bien et poursuivez la cuisson 2 min jusqu'à ce que le fromage soit fondu.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez le coquillotto de chapelure panko au piment chipotle."]}]},{"id":"18371","nom":"Coquillotto au chorizo doux, poireau, gorgonzola et noix","image":"images/18371.webp","ingredients":[["chorizo","80 g"],["crème","80 g"],["gorgonzola","75 g"],["vin blanc du Vaucluse","50 ml"],["poireau bio (180g)","1x"],["coquillettes demi-complètes","200 g"],["noix sèche","40 g"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile d'olive","500 ml eau","0.5 cube bouillon de boeuf"],"etapes":[{"titre":"La préparation","items":["Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Coupez les tranches de chorizo en morceaux.","Ciselez (dés) l'oignon."]},{"titre":"Le coquillotto","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, le poireau et le chorizo 5 min. Salez, poivrez.","Déglacez (versez) avec le vin blanc et faites-le réduire jusqu'à évaporation complète.","Ajoutez l'eau, le bouillon de boeuf émietté et les coquillettes, portez à ébullition puis baissez à feu moyen et faites cuire 10 min environ en remuant régulièrement.","En fin de cuisson, le liquide doit être presque complètement absorbé et les coquillettes fondantes.","Ajoutez un fond d’eau chaude si nécessaire en cours de cuisson."]},{"titre":"A table !","items":["Coupez le gorgonzola en morceaux.","Une fois les coquillettes cuites, ajoutez le gorgonzola et la crème. Mélangez bien.","Poursuivez la cuisson 2 à 3 min jusqu'à ce que le fromage soit fondu et la sauce soit nappante.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Ouvrez et hachez les noix.","Au moment de servir, parsemez les noix sur votre coquillotto."]}]},{"id":"22014","nom":"Coquillotto au chorizo, poireau et gouda","image":"images/22014.webp","ingredients":[["chorizo à griller (240g) Bleu Blanc Coeur","240 g"],["crème (80g)","80 g"],["gouda au lait de vache pasteurisé (60g)","60 g"],["coquillettes demi-complètes (200g)","200 g"],["poireau (130g)","1x"]],"cuisine":["sel","poivre","huile d'olive","500 ml eau","0.5 bouillon de légumes (cube)"],"etapes":[{"titre":"La préparation","items":["Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Coupez le chorizo en morceaux."]},{"titre":"Le coquillotto","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poireau et le chorizo 5 min. Salez légèrement, poivrez.","Ajoutez l'eau, le bouillon de légumes émietté et les coquillettes.","Faites cuire 12 à 15 min à couvert en remuant régulièrement. En fin de cuisson, le liquide doit être presque complètement absorbé et les coquillettes fondantes.","Ajoutez un peu d’eau chaude en cours de cuisson si nécessaire.","Pendant la cuisson des coquillettes, râpez le gouda ou coupez-le en petits dés."]},{"titre":"A table !","items":["Une fois les coquillettes cuites, ajoutez la moitié du gouda et la crème dans la sauteuse. Mélangez bien.","Poursuivez la cuisson 1 à 2 min jusqu'à ce que le fromage soit fondu.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Astuce : pour une version encore plus onctueuse, ajoutez une noisette de beurre juste avant de servir.","Au moment de servir, parsemez le reste de gouda sur le coquillotto."]}]},{"id":"15982","nom":"Côte de porc à la forestière (sauce aux champignons de Paris)","image":"images/15982.webp","ingredients":[["côte de porc échine sans os (250g) Bleu Blanc Coeur","2x"],["crème","100 g"],["champignons de Paris blancs","200 g"],["gousse d'ail (6g)","1x"],["riz basmati","150 g"],["oignon jaune (130g)","1x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","1 càs moutarde"],"etapes":[{"titre":"La sauce forestière","items":["Émincez l'oignon.","Coupez les champignons de Paris en fines tranches.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, l'ail et les champignons 10 min environ. Salez, poivrez.","Au bout des 10 min, ajoutez la moutarde et la crème. Laissez mijoter à feu doux 3 min environ.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant la cuisson du riz, préparez les côtes de porc."]},{"titre":"Les côtes de porc","items":["Salez et poivrez les côtes de porc.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu vif.","Saisissez les côtes de porc 1 min de chaque côté pour les dorer.","Baissez sur feu moyen et poursuivez la cuisson 2 à 3 min de chaque côté jusqu’à ce qu’elles soient cuites à coeur (leur chair n'est plus rose).","En parallèle, effeuillez et ciselez le persil puis parsemez-le sur votre assiette."]}]},{"id":"16824","nom":"Côte de porc et taboulé au fenugrec, concombre et pêche","image":"images/16824.webp","ingredients":[["côte de porc échine sans os (250g) Bleu Blanc Coeur","2x"],["graines de couscous (150g)","150 g"],["fenugrec (sachet) (2g)","0.5"],["persil-menthe (botte) (10g)","0.5"],["concombre noa (250g)","1x"],["tomate (100g)","1x"],["échalote (12.5g)","0.5"],["pêche (115g)","1x"]],"cuisine":["sel","poivre","4 càs huile d'olive","2 càs vinaigre de votre choix"],"etapes":[{"titre":"Les graines de couscous","items":["Portez à ébullition l'eau et dans un récipient déposez les graines de couscous.","Versez l'eau sur les graines de couscous. Couvrez et laissez gonfler 5 min.","Ajoutez-y un filet d'huile d'olive. Salez, poivrez et à l'aide d'une fourchette, égrainez-les (séparez les grains).","Laissez refroidir à température ambiante.","Pendant ce temps, faites cuire les côtes de porc."]},{"titre":"Les côtes de porc","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu vif.","Saisissez les côtes de porc 1 min de chaque côté pour les dorer.","Baissez sur feu moyen et poursuivez la cuisson 2 à 3 min de chaque côté jusqu’à ce qu’elles soient cuites à coeur (leur chair n'est plus rose)."]},{"titre":"Le taboulé","items":["Ciselez (dés) l'échalote.","Épluchez le concombre.","Coupez le concombre et la tomate en petits dés (0,5 cm environ).","Effeuillez et ciselez le persil et la menthe.","Coupez la pêche en petits dés.","Dans un saladier, mélangez le fenugrec, l'huile d'olive et le vinaigre pour obtenir une vinaigrette. Salez, poivrez.","Ajoutez l'échalote, le concombre, la tomate, les herbes, la pêche et les graines de couscous refroidies. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17825","nom":"Côte de porc, crème à la moutarde et purée de céleri","image":"images/17825.webp","ingredients":[["crème","80 g"],["côte de porc (filet) (250g) Bleu Blanc Coeur","2x"],["échalote","0.5"],["céleri-rave","250 g"],["poireau (215g)","1x"],["pomme de terre (400g)","2x"],["gousse d'ail (6g)","1x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","1 càs moutarde","beurre","lait"],"etapes":[{"titre":"La purée","items":["Épluchez et coupez les pommes de terre et le céleri-rave en morceaux.","Déposez-les dans une casserole et recouvrez-les très largement d'eau. Salez.","Faites-les cuire 15 à 20 min. Égouttez et réduisez le tout en purée. Salez, poivrez.","Ajoutez une noix de beurre et un filet de lait pour une purée plus onctueuse.","Pendant ce temps, faites cuire le poireau."]},{"titre":"Le poireau","items":["Émincez l'échalote.","Pressez ou hachez l'ail.","Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'échalote, l'ail et le poireau 15 min environ.","A mi-cuisson, ajoutez un peu d'eau et couvrez pour accélérer la cuisson. Salez, poivrez.","Une fois cuit, ajoutez une noix de beurre.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Réservez dans une assiette."]},{"titre":"Les côtes de porc et la sauce","items":["Dans la même poêle, ajoutez un filet d’huile d’olive et une noix de beurre.","Salez et poivrez les côtes de porc, puis faites-les dorer 1 min de chaque côté à feu vif.","Baissez à feu moyen et poursuivez la cuisson 2 à 3 min de chaque côté jusqu’à ce qu’elles soient cuites à coeur (la chair n'est plus rose).","Astuce : inclinez légèrement la poêle et « arrosez » la viande à la cuillère régulièrement. Cette technique rehausse le goût ainsi que la coloration et vous évitera une viande trop sèche !","Retirez-les et réservez-les au chaud sous aluminium.","Dans la même poêle, ajoutez la crème et la moutarde. Mélangez et laissez réduire 1 à 2 min pour obtenir une sauce onctueuse.","Goûtez et rectifiez l’assaisonnement si nécessaire.","Effeuillez et ciselez le persil.","Servez votre côte de porc nappée de sauce accompagnée de la purée et la fondue de poireau. Parsemez le tout de persil."]}]},{"id":"18963","nom":"Crevettes à la marinière et spaghettis au poireau","image":"images/18963.webp","ingredients":[["crevettes cuites nature","125 g"],["vin blanc du Vaucluse","100 ml"],["échalote","0.5"],["poireau (215g)","1x"],["persil plat","qq brins"],["spaghetti blancs","200 g"]],"cuisine":["sel","poivre","20 g beurre","huile d'olive"],"etapes":[{"titre":"Le poireau","items":["Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. <strong>É</strong>mincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir le poireau 20 min environ. Salez, poivrez.","A mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson.","Pendant ce temps, faites cuire les spaghettis."]},{"titre":"Les spaghettis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les spaghettis selon les indications du paquet.","En parallèle, préparez les crevettes à la marinière."]},{"titre":"Les crevettes à la marinière","items":["Ciselez (dés) l'échalote.","Effeuillez et ciselez le persil.","Dans une casserole, faites fondre le beurre à feu doux.","Faites revenir l'échalote 5 min. Salez, poivrez.","Au bout des 5 min, déglacez (versez) avec le vin blanc et portez à ébullition 1 min.","Baissez sur feu doux et ajoutez les crevettes et le persil.","Faites chauffer 2 à 3 min pour que le tout soit chaud. Mélangez bien.","Une fois les spaghettis et le poireau cuits, ajoutez les spaghettis dans la sauteuse du poireau. Salez, poivrez. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Déposez dans vos assiettes des pâtes au poireau, puis, par-dessus, des crevettes marinières."]}]},{"id":"15478","nom":"Crevettes caramélisées et épinards à la crème","image":"images/15478.webp","ingredients":[["crevettes cuites nature (150g)","150 g"],["échalote (25g)","1x"],["crème (100g)","100 g"],["pousses d'épinards (100g)","100 g"],["riz concassé du Pendjab (150g)","150 g"],["citron jaune (50g)","0.5"]],"cuisine":["sel","poivre","huile de cuisson","2 càs sucre","2 càs eau"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","En parallèle, préparez les épinards."]},{"titre":"La crème","items":["Émincez l'échalote.","Dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'échalote 5 min jusqu'à ce qu'elle soit translucide.","Au bout des 5 min, ajoutez au fur et à mesure les pousses d'épinards et poursuivez la cuisson 2 à 3 min. Salez, poivrez.","Une fois les épinards tombés, versez la crème et laissez mijoter à couvert à feu moyen le temps de préparer les crevettes."]},{"titre":"Les crevettes","items":["Dans une petite casserole, versez le sucre et l'eau.","Faites chauffer à feu doux jusqu'à ce que le sucre brunisse, sans remuer. Surveillez bien et ne mélangez pas (ou sinon à la spatule en bois). Attention, le caramel ne doit pas être brûlé.","Une fois le caramel prêt, ajoutez les crevettes et mélangez. Réchauffez-les 1 à 2 minutes pour qu'elles restent tendres.","Coupez le citron en quartiers.","Dans des assiettes, déposez le riz. Versez à côté la crème aux épinards et déposez les crevettes par-dessus. Arrosez le tout d'un filet de jus de citron."]}]},{"id":"17192","nom":"Croque-madame au saumon fumé et salade de sucrine à la pomme","image":"images/17192.webp","ingredients":[["fromage blanc","100 g"],["citron jaune","0.5"],["pain de campagne (tranche) (100g)","4x"],["saumon fumé","100 g"],["sucrine (200g)","1x"],["pomme (112g)","1x"],["aneth","qq brins"],["échalote","0.5"]],"cuisine":["2 oeuf","2 càs huile d'olive","1 càs vinaigre de votre choix","sel","poivre"],"etapes":[{"titre":"La sauce","items":["Dans un bol, déposez les ingrédients suivants :","Effeuillez et ciselez l'aneth.","A l’aide d’une râpe, prélevez des zestes de citron (uniquement l’écorce de couleur) et pressez-le.","Ajoutez le fromage blanc et un filet d'huile d'olive. Salez, poivrez. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les croques-madame","items":["Coupez le saumon fumé en morceaux.","Faites dorer les tranches de pain de campagne au grille-pain.","Sur la moitié des tranches de pain, étalez la sauce au fromage blanc et répartissez dessus le saumon.","Refermez avec le reste des tranches de pain.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites cuire les œufs au plat 3 min. Salez, poivrez.","Une fois cuits, déposez les œufs sur les croques pour former des croques-madame.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dès) l'échalote.","Versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Coupez la pomme en quartiers.","Retirez la base de la sucrine et émincez-la. Mélangez bien."]}]},{"id":"22133","nom":"Croque-Monsieur au jambon végétal et gouda","image":"images/22133.webp","ingredients":[["pain de mie tranché (200g)","8x"],["crème (60g)","60 g"],["gouda au lait de vache pasteurisé (90g)","90 g"],["salade (50g)","50 g"],["jambon fumé végétal (tranche) (90g)","3x"]],"cuisine":["sel","poivre","beurre","huile d'olive","vinaigre de votre choix","1 càc moutarde"],"etapes":[{"titre":"Les croques","items":["Préchauffez le four à 220°C en chaleur tournante !","Pendant ce temps, coupez les tranches de jambon en 4.","Râpez le gouda.","Dans un bol, mélangez le gouda, la moutarde et la crème. Salez et poivrez.","Sur la moitié des tranches de pain de mie, tartinez un peu de beurre.","Répartissez dessus le jambon et la moitié du mélange crème-gouda.","Refermez les croques et répartissez le reste du mélange crème-gouda dessus.","Déposez-les sur une plaque allant au four munie d'un papier cuisson et enfournez 7 à 10 min, jusqu'à ce que le pain soit bien doré et le fromage gratiné.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"16262","nom":"Crostinis de crème de féta à la pistache et fenouil croquant","image":"images/16262.webp","ingredients":[["féta","100 g"],["pistache","50 g"],["gousse d'ail","0.5"],["bulbe de fenouil (200g)","1x"],["citron jaune","0.5"],["petits pains (160g)","2x"],["mâche","50 g"]],"cuisine":["sel","poivre","2 eau (càs)","1 huile d'olive (càs)","vinaigre de votre choix"],"etapes":[{"titre":"Le fenouil mariné","items":["Dans un saladier, déposez les ingrédients suivants :","Pressez ou hachez l'ail.","Pressez le citron.","Coupez la base et les tiges à ras du bulbe de fenouil. Retirez la partie dure au centre et émincez le reste.","Versez un filet d'huile d'olive, salez, poivrez.","Mélangez bien pour bien enrober le fenouil.","Laissez-le reposer au frais jusqu'au montage des crostinis."]},{"titre":"La crème de féta aux pistaches","items":["Faites chauffer une poêle sans matière grasse à feu vif.","Torréfiez les pistaches 5 min jusqu'à ce qu'elles soient dorées. Réservez-en quelques-unes pour le dressage.","Transvasez-les dans le bol d'un mixeur et mixez-les jusqu'à obtenir une poudre homogène.","Ajoutez la féta, l'huile d'olive, l'eau et poivrez.","Mixez de nouveau jusqu'à obtenir une crème lisse.","Astuce : ajoutez de l'eau supplémentaire pour une crème plus fluide.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les crostinis","items":["Coupez les petits pains en deux.","Faites-les dorer au grille-pain.","Hachez le reste de pistaches.","Sur chaque tartine, déposez un peu de crème de féta, du fenouil croquant et parsemez du reste de pistaches.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"15482","nom":"Cuisse de canard rôtie, sauce bigarade caramélisée, écume d'orange et potimarron rôti","image":"images/15482.webp","ingredients":[["cuisse de canard (360g)","2x"],["orange (150g)","1x"],["crème","80 g"],["gousse d'ail (4g)","1x"],["pomme de terre (440g)","2x"],["potimarron","350 g"]],"cuisine":["sel","poivre","beurre","huile de cuisson","20 g beurre","0.5 bouillon de poule (cube)","300 ml eau (sauce)","20 g sucre","0.5 bouillon de bœuf (cube)","200 ml eau (cuisse de canard)","huile d'olive"],"etapes":[{"titre":"Les cuisses de canard","items":["Préchauffez votre four à 190°C en chaleur tournante !","Pendant ce temps, dans une sauteuse, faites fondre le beurre et un filet d'huile de cuisson à feu vif.","Saisissez les cuisses de canard 2 à 3 min de chaque côté pour les dorer.","Diluez le bouillon de poule dans l'eau.","Pelez la gousse d'ail.","Une fois les cuisses de canard dorées, déposez-les dans un plat allant au four. Réservez la sauteuse.","Ajoutez la gousse d'ail, l'eau et le bouillon de poule.","Couvrez le plat avec du papier aluminium et enfournez 1h.","En parallèle, préparez le potimarron."]},{"titre":"Le potimarron rôti","items":["Coupez prudemment le potimarron en 2 (il n'est pas nécessaire de l'éplucher, la peau, une fois cuite, devient tendre).","Retirez les graines à l'aide d'une cuillère.","Coupez-le en tranches.","Sur une plaque allant au four, munie de papier cuisson, déposez les tranches de potimarron.","Versez un filet d'huile d'olive. Salez, poivrez et mélangez bien pour tout enrober.","Enfournez avec le canard 30 min environ.","Pendant ce temps, préparez la crème et les pommes de terre."]},{"titre":"La crème infusée à l'orange","items":["A l'aide d'une râpe, prélevez les zestes d'orange (uniquement l'écorce de couleur).","Dans un bol mélangez la crème et les zestes d'orange.","Laissez infuser au frais, le temps de la recette."]},{"titre":"Les pommes de terre","items":["Coupez les pommes de terre en dés.","Dans la sauteuse des cuisses de canard, faites chauffer de nouveau un filet d'huile de cuisson à feu vif.","Faites revenir les pommes de terre 5 min à feu vif.","Baissez sur feu moyen et poursuivez la cuisson 15 min à couvert. Remuez régulièrement pendant la cuisson. Salez, poivrez."]},{"titre":"La sauce bigarade","items":["Pressez le jus d'orange.","Dans une casserole, portez à ébullition l'eau, le bouillon de boeuf et faites réduire de moitié.","Dans une seconde casserole, déposez le sucre et réalisez un caramel. Faites chauffer à feu doux jusqu'à ce que le sucre brunisse, sans remuer. Attention le caramel ne doit pas être brûlé.","Déglacez (versez) avec le jus d'orange.","Ajoutez le bouillon de boeuf réduit et mélangez bien. Faites réduire la sauce jusqu'à obtenir une consistance sirupeuse.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Juste avant de servir, à l'aide d'un mixeur plongeant mixez la crème infusée à l'orange pour réaliser une écume."]},{"titre":"","items":["Dégustez sans attendre votre cuisse de canard rôtie accompagnée des pommes de terre et du potimarron rôti ! Nappez le tout de sauce bigarade et d'écume d'ornage."]}]},{"id":"18006","nom":"Curry de pois chiches à la mangue et au piment","image":"images/18006.webp","ingredients":[["lait de coco","100 ml"],["riz basmati","150 g"],["pois chiches conserve (g égoutté) (100g)","100x"],["gingembre","1 à 3 cm"],["mangue","0.5"],["piment oiseau (2g)","1x"],["oignon jaune (110g)","1x"],["curry (sachet)","0.5"]],"cuisine":["sel","poivre","0.25 bouillon de légumes (cube)","huile de cuisson (mélange 4 huiles par exemple)","100 ml eau"],"etapes":[{"titre":"La préparation","items":["Émincez l'oignon.","Pelez et hachez le gingembre.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Épluchez et coupez la mangue en morceaux.","Égouttez et rincez les pois chiches."]},{"titre":"Le curry","items":["Dans une cocotte, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon, le gingembre et le curry 5 min environ. Remuez régulièrement.","Au bout des 5 min de cuisson, ajoutez la mangue, le piment (adaptez la quantité selon votre goût), le lait de coco, l'eau et le bouillon de légumes. Salez, poivrez.","Faites cuire à couvert 10 min environ.","Au bout des 10 min, ajoutez les pois chiches et prolongez la cuisson 5 min à découvert.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Astuce : la sauce doit napper la cuillère tout en restant fluide , si elle vous paraît trop épaisse, ajoutez 2 à 3 càs d’eau chaude.","Pendant la cuisson du curry, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Servez le riz nappé par le curry aux pois chiches."]}]},{"id":"21663","nom":"Curry de pois chiches et raïta de courgette","image":"images/21663.webp","ingredients":[["lait de coco (150g)","150 ml"],["gousse d'ail (6g)","1x"],["curry jaune doux (3g)","2 càc"],["pulpe de tomates (210g)","210 g"],["fromage blanc (100g)","100 g"],["riz concassé du Pendjab (150g)","150 g"],["pois chiches conserve (g égoutté) (225.25g)","225 g"],["coriandre (botte) (10g)","0.5"],["gingembre (20g)","1 à 3 cm"],["oignon rouge (65g)","0.5"],["courgette (100g)","0.5"]],"cuisine":["sel","poivre","huile d'olive","150 ml eau"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","En parallèle, réalisez le curry."]},{"titre":"Le curry","items":["Émincez l'oignon.","Pelez et hachez l'ail et le gingembre.","Dans une seconde casserole, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, la moitié de l'ail, le gingembre et le curry 5 min.","En parallèle, égouttez les pois chiches.","Au bout des 5 min, ajoutez la pulpe de tomates, le lait de coco, l'eau et les pois chiches. Salez, poivrez.","Couvrez et poursuivez la cuisson 10 min environ à feu doux, jusqu'à ce que la sauce ait légèrement épaissi et que les pois chiches soient bien chauds.","Astuce : si la sauce est trop liquide, laissez mijoter quelques minutes de plus.","Pendant ce temps, préparez le raïta."]},{"titre":"Le raïta","items":["Râpez la courgette.","Pressez-la légèrement entre vos mains ou dans une passoire afin d'éliminer l'excès d'eau.","Ciselez la coriandre (en entier, les tiges se consomment).","Dans un bol, mélangez le fromage blanc, la moitié de la coriandre, le reste d'ail, la courgette et un filet d'huile d'olive. Salez, poivrez.","Goûtez et ajoutez une pincée de sel si nécessaire.","Servez le curry accompagné du riz, d'une cuillère de raïta et parsemez avec le reste de la coriandre."]}]},{"id":"21294","nom":"Curry de saumon fumé au lait de coco, courgette et gingembre","image":"images/21294.webp","ingredients":[["lait de coco (200g)","200 ml"],["curry jaune doux (3g)","1 càc"],["courgette (200g)","1x"],["gingembre (20g)","1 à 3 cm"],["gousse d'ail (6g)","1x"],["saumon fumé (100g)","100 g"],["riz concassé du Pendjab (150g)","150 g"]],"cuisine":["poivre","huile de cuisson","sel"],"etapes":[{"titre":"La courgette","items":["Coupez la courgette en dés.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir la courgette 10 min jusqu'à ce qu'elle soit tendre et légèrement dorée. Poivrez mais ne salez pas (le saumon fumé apporte déjà du sel).","Pendant la cuisson de la courgette, pelez et hachez l'ail et le gingembre.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet."]},{"titre":"A table !","items":["Au bout des 10 min de cuisson de la courgette, ajoutez l'ail, le gingembre, le curry et le lait de coco dans la sauteuse. Mélangez bien.","Laissez mijoter 5 min environ.","Coupez le saumon fumé en lanières.","Au moment de servir, ajoutez les lanières de saumon à la sauteuse et mélangez délicatement.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Servez le curry de saumon fumé accompagné du riz."]}]},{"id":"19446","nom":"Curry pimenté de champignons à la coriandre","image":"images/19446.webp","ingredients":[["lait de coco","200 ml"],["gousse d'ail","0.5"],["champignon shiitaké","100 g"],["champignons de Paris blancs","250 g"],["curry jaune doux (sachet)","0.5"],["riz concassé du Pendjab","150 g"],["citron jaune","0.5"],["oignon jaune (110g)","1x"],["coriandre","qq brins"],["piment oiseau (2g)","1x"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Le curry de champignons","items":["Coupez les shiitakés et champignons de Paris en tranches.","Émincez l'oignon.","Pressez ou hachez l'ail.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez l'ail, les champignons de Paris et les shiitakés. Poursuivez la cuisson 10 min jusqu'à ce qu'ils soient colorés.","Au bout des 10 min, ajoutez le lait de coco, le curry et le piment et laissez mijoter 5 min. Salez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","En parallèle, ciselez la coriandre (en entier, les tiges se consomment).","Coupez le citron en quartiers.","Au moment de servir, parsemez le curry de coriandre, arrosez d'un filet de jus de citron et accompagnez de riz."]}]},{"id":"19146","nom":"Curry relevé de gnocchis à la purée de cacahuètes et chou pack choy","image":"images/19146.webp","ingredients":[["gnocchi de pommes de terre fraîches","400 g"],["carotte (100g)","1x"],["lait de coco","150 ml"],["purée de cacahuètes","30 g"],["citron vert","0.5"],["chou pak choy (135g)","1x"],["curry jaune fort (sachet)","0.5"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","300 ml eau","0.5 bouillon de légumes (cube)","huile de cuisson"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon.","Épluchez et coupez la carotte en fines demi-rondelles.","Coupez la base du chou pak choy et émincez-le.","Dans une cocotte, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir les légumes avec le curry 5 min. Salez légèrement, poivrez. Remuez régulièrement.","Au bout des 5 min, ajoutez l'eau, le bouillon de légumes émietté et la purée de cacahuètes.","Portez à ébullition puis couvrez et laissez mijoter 10 min.","Pendant la cuisson des légumes, préparez les gnocchis."]},{"titre":"Les gnocchis","items":["Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir les gnocchis 10 min jusqu'à ce qu'ils soient dorés et moelleux. Salez, poivrez. Remuez régulièrement."]},{"titre":"Le curry de gnocchis","items":["Une fois les légumes cuits, ajoutez les gnocchis et le lait de coco à la cocotte. Mélangez bien et servez immédiatement pour que les gnocchis ne ramollissent pas.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez le citron vert en quartiers et versez un filet de jus sur le tout."]}]},{"id":"18037","nom":"Curry relevé de gnocchis et épinards au lait de coco","image":"images/18037.webp","ingredients":[["gnocchis de pommes de terre fraîches","400 g"],["curry Madras (sachet)","0.5"],["lait de coco","200 ml"],["pousses d'épinards","125 g"],["coriandre","qq brins"],["cacahuètes grillées","25 g"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Le curry de gnocchis","items":["Émincez l'oignon.","Dans une grande sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir les gnocchis 5 min. Remuez régulièrement puis réservez-les dans une assiette ou un plat.","Astuce : si vous avez plus de 800g de gnocchis, faites-les revenir en deux fois pour une cuisson plus homogène.","Dans la même sauteuse, faites de nouveau chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l’oignon 5 min pour qu’il soit tendre et légèrement doré. Salez, poivrez.","Au bout des 5 min, ajoutez le lait de coco, le curry, les pousses d'épinards et poursuivez la cuisson 5 min jusqu'à ce que les épinards soient tombés (réduits).","Astuce : le curry est fort, n'en mettez qu'une petite quantité pour commencer.","En parallèle de la cuisson du plat, préparez le reste des ingrédients."]},{"titre":"A table !","items":["Ciselez la coriandre (en entier, les tiges se consomment).","Hachez les cacahuètes.","Une fois le tout cuit, ajoutez les gnocchis dans la sauteuse et mélangez bien.","Poursuivez la cuisson 5 min pour que les gnocchis soient tendres.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez le tout de coriandre et de cacahuètes."]}]},{"id":"14873","nom":"Curry rouge pimenté de lapin à la poire","image":"images/14873.webp","ingredients":[["oignon jaune (125g)","1x"],["sauce curry rouge","100 g"],["crème","80 g"],["riz basmati","150 g"],["émincé de lapin","220 g"],["gousse d'ail","0.5"],["cacahuètes grillées sans sel","25 g"],["poire (125g)","1x"]],"cuisine":["huile de cuisson","sel"],"etapes":[{"titre":"Le curry","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Épluchez et coupez la poire en fins quartiers.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon et le lapin 5 min.","Au bout des 5 min, ajoutez la sauce curry, l'ail, la poire et la crème et laissez mijoter à feu doux et à couvert 15 min. Salez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Hachez les cacahuètes et parsemez-les au moment de servir."]}]},{"id":"15542","nom":"Dahl de lentilles corail, poulet, pomme aux épices Cachemire et noix de cajou","image":"images/15542.webp","ingredients":[["haut de cuisse de poulet","225 g"],["fromage blanc","100 g"],["épices Cachemire (sachet)","0.5"],["noix de cajou grillées","25 g"],["concentré de tomates","30 g"],["gousse d'ail","0.5"],["lentilles corail","150 g"],["oignon jaune (125g)","1x"],["carotte orange (100g)","1x"],["gingembre","1 à 3 cm"],["coriandre (botte)","0.5"],["citron vert","0.5"],["pomme (125g)","1x"]],"cuisine":["sel","poivre","200 ml eau","0.25 bouillon de poule (cube)","huile d'olive"],"etapes":[{"titre":"La préparation","items":["Ciselez (dés) l'oignon.","Pelez et hachez l'ail et le gingembre.","Épluchez et coupez la carotte et la pomme en petits dés.","Coupez les hauts de cuisse de poulet en morceaux."]},{"titre":"Le dahl","items":["Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, le poulet, l'ail, la carotte, le gingembre et les épices Cachemire 2 min.","Au bout des 2 min, ajoutez les lentilles corail, le concentré de tomates, l'eau et le bouillon de poule. Ne salez pas, le sel durcit les lentilles","Portez à ébullition. Baissez sur feu doux et laissez mijoter 10 min.","En fin de cuisson, ajoutez la pomme et poursuivez la cuisson 2 min jusqu'à ce que le poulet soit cuit à coeur (la chair n'est plus rose). Salez, poivrez.","En parallèle, préparez la sauce."]},{"titre":"La sauce au fromage blanc","items":["Ciselez la coriandre (en entier, les tiges se consomment). Réservez-en pour le dressage.","A l’aide d’une râpe, prélevez des zestes de citron vert (uniquement l’écorce de couleur).","Dans le bol d'un mixeur, mixez le fromage blanc, les zestes de citron et la coriandre. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez le citron en quartiers. Concassez les noix de cajou."]},{"titre":"","items":["Dégustez sans attendre votre dahl de lentilles corail, poulet, pomme aux épices Cachemire accompagné de la sauce à la coriandre ! Parsemez du reste de coriandre, de noix de cajou et arrosez d'un filet de jus de citron !"]}]},{"id":"16827","nom":"Dinde caramélisée au miel et sriracha pimentée, concombre au sésame","image":"images/16827.webp","ingredients":[["escalope de dinde (240g)","2x"],["sauce sriracha","5 ml"],["sauce soja salée","20 ml"],["gousse d'ail (6g)","1x"],["riz basmati","150 g"],["miel","10 ml"],["concombre noa (250g)","1x"],["sésame doré","10 g"],["ciboulette","qq brins"]],"cuisine":["sel","poivre","1 maïzena (càs)","120 eau (ml)","1 sucre (càc)","vinaigre de votre choix","huile de tournesol"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"La dinde caramélisée","items":["Pressez ou hachez l'ail.","Dans un bol, délayez la maïzena avec la sauce soja. Ensuite, ajoutez l'ail, la sauce sriracha, le miel, le sucre et l'eau en mélangeant bien.","Astuce : la sauce sriracha est forte, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût. <!-- notionvc: e23de382-08ff-4c18-bcaf-65257b92189d -->","Coupez la dinde en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile de tournesol à feu moyen à vif.","Faites revenir la dinde 5 min environ. Salez légèrement, poivrez.","Au bout des 5 min, baissez le feu puis versez la sauce. Prolongez la cuisson 5 min environ jusqu'à ce que la dinde soit cuite à coeur (la chair n'est plus rose) et caramélisée. Remuez régulièrement.","En parallèle, préparez le reste des ingrédients."]},{"titre":"A table !","items":["Épluchez et coupez le concombre en demi-rondelles.","Dans un saladier, mélangez le concombre, le sésame, un filet d'huile de tournesol et de vinaigre. Salez, poivrez.","Ciselez la ciboulette.","Déposez la dinde caramélisée sur le riz, parsemez de ciboulette et accompagnez du concombre."]}]},{"id":"17246","nom":"Donburi aux algues, sauce soja, courgette et carotte rôties","image":"images/17246.webp","ingredients":[["salade d'algues au sésame et au gingembre","75 g"],["sauce soja salée","20 ml"],["riz rond blanc","150 g"],["courgette (200g)","1x"],["carotte (200g)","2x"],["cacahuètes grillées sans sel","25 g"],["cébette (30g)","1x"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Les légumes","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, épluchez et coupez les carottes en fins bâtonnets.","Coupez la courgette en fines rondelles.","Sur une plaque allant au four, déposez les légumes. Versez un filet d'huile de cuisson. Salez, poivrez. Mélangez bien pour tout enrober.","Enfournez 20 min environ.","Pendant ce temps, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","En parallèle, préparez les toppings."]},{"titre":"Le donburi","items":["Retirez la base de la cébette et émincez-la.","Hachez les cacahuètes.","Astuce : Pour révéler pleinement leurs arômes, faites torréfier les épices (ou les oléagineux) à sec dans une poêle chaude pendant quelques minutes, en remuant régulièrement. Elles dégageront une odeur plus intense et apporteront plus de profondeur aux saveurs de votre plat.","Dans des bols ou des assiettes creuses, déposez dans le fond le riz. Répartissez par-dessus la salade d'algues et les légumes. Parsemez de cébette, de cacahuètes et arrosez de sauce soja."]}]},{"id":"18547","nom":"Echine de porc sautée à la purée de sésame","image":"images/18547.webp","ingredients":[["purée de sésame","30 g"],["riz basmati","150 g"],["gousse d'ail (4g)","1x"],["sauce soja sucrée","20 ml"],["citron jaune","0.5"],["oignon jaune (110g)","1x"],["côte de porc échine sans os (250g) Bleu Blanc Coeur","2x"],["cébette","0.5"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"La préparation","items":["Ciselez (dés) l'oignon.","Coupez les côtes de porc en morceaux.","Pressez ou hachez l'ail.","Pressez le citron.","Dans un bol, mélangez l'ail, le jus de citron, la sauce soja sucrée et la purée de sésame."]},{"titre":"Le porc sauté","items":["Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez le porc et poursuivez 3 à 5 min jusqu'à ce qu'il soit cuit à coeur (la chair n'est plus rose). Salez légèrement, poivrez.","En fin de cuisson, baissez le feu, versez la sauce dans la sauteuse. Mélangez 1 à 2 min pour que la sauce soit nappante et enrobe le porc.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Retirez la base de la cébette et émincez-la. Parsemez-la sur la recette au moment de servir."]}]},{"id":"17072","nom":"Emincés de porc au thym citron, quinoa sauté à la courgette menthe et raisins secs","image":"images/17072.webp","ingredients":[["emincés de porc thym citron","240 g"],["quinoa blanc","150 g"],["courgette (200g)","1x"],["échalote (25g)","1x"],["citron jaune","0.5"],["fromage blanc","100 g"],["raisin sec sultanine","25 g"],["menthe","qq brins"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Le quinoa","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le quinoa selon les indications du paquet.","Une fois cuits, égouttez-le bien.","Pendant ce temps, faites cuire la courgette."]},{"titre":"La poêlée","items":["Emincez l'échalote.","Coupez la courgette en petits dés.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'échalote et la courgette 10 min environ.","Au bout des 10 min, ajoutez le quinoa égouttée et les raisins secs. Salez, poivrez.","Mélangez bien et poursuivez 5 min environ à feu moyen.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, préparez le porc et la sauce."]},{"titre":"Les émincés de porc","items":["Dans une seconde sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faire revenir les émincés de porc 5 à 7 min jusqu'à ce qu'ils soient cuits à coeur (la chair n'est plus rose)."]},{"titre":"A table !","items":["Effeuillez et ciselez la menthe.","Pressez le citron.","Mélangez le fromage blanc, la menthe et le citron. Salez, poivrez.","Accompagnez les émincés de porc de la poêlée de quinoa et nappez le tout de sauce."]}]},{"id":"17315","nom":"Escalope de dinde à la moutarde, origan et haricots verts","image":"images/17315.webp","ingredients":[["origan (sachet)","0.25"],["crème","100 g"],["escalope de dinde (240g)","2x"],["gousse d'ail","0.5"],["macaroni demi-complets","200 g"],["haricots verts","200 g"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile d'olive","1 càs moutarde"],"etapes":[{"titre":"Les macaronis et les haricots verts","items":["Portez à ébullition une grande casserole d’eau salée.","Pendant ce temps, équeutez les haricots verts et coupez-les en deux.","Faites cuire les haricots verts 5 min.","Au bout des 5 min, ajoutez les macaronis et poursuivez la cuisson selon les indications du paquet.","En parallèle, préparez les escalopes de dinde."]},{"titre":"Les escalopes de dinde à la moutarde et origan","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Coupez les escalopes de dinde en lanières.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 5 min.","Ajoutez les escalopes de dinde et poursuivez la cuisson 5 min. Salez, poivrez.","Au bout des 5 min, ajoutez la crème, l'ail, la moutarde et l'origan.","Faites chauffer le tout 2 min jusqu'à ce que la dinde soit cuite à coeur (la chair n'est plus rose). Remuez régulièrement.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"15896","nom":"Farfallines aux champignons de Paris et crème de féta à l'ail des ours","image":"images/15896.webp","ingredients":[["farfallines","200 g"],["champignons de Paris blancs","250 g"],["gousse d'ail","0.5"],["crème de féta","90 g"],["poireau (300g)","1x"],["noisettes décortiquées","25 g"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Le poireau et les champignons","items":["Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Coupez les champignons de Paris en tranches.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poireau et l'ail 10 min environ. Salez, poivrez.","Au bout des 10 min, ajoutez les champignons et prolongez la cuisson 5 à 7 min jusqu'à ce que les légumes soient cuits.","Pendant ce temps, faites cuire les pâtes."]},{"titre":"Les farfallines","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les farfallines selon les indications du paquet."]},{"titre":"A table !","items":["Hachez les noisettes.","Effeuillez et ciselez le persil.","Lorsque tout est cuit, mélangez les farfallines, les légumes et la crème de féta.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez de noisettes et de persil."]}]},{"id":"17956","nom":"Filet d'églefin sauce aigre-douce au poivron","image":"images/17956.webp","ingredients":[["double concentré de tomates","20 g"],["sauce soja salée","20 ml"],["riz basmati","150 g"],["gousse d'ail","0.5"],["filet d'églefin","240 g"],["oignon jaune","0.5"],["poivron rouge (125g)","1x"]],"cuisine":["0.5 càs maïzena (sauce)","1 càc vinaigre (blanc ou de cidre)","1 càs sucre","300 ml eau","1 oeuf","huile de cuisson","sel","poivre","maïzena (panure)"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"La sauce","items":["Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Coupez le poivron en petits dés (0,5 cm environ).","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon, l'ail et le poivron 5 min.","Pendant ce temps, mélangez dans un bol : l’eau, la maïzena, le concentré de tomates, la sauce soja, le vinaigre et le sucre.","Versez la préparation dans la sauteuse en remuant. Laissez mijoter 5 min à feu moyen jusqu’à obtenir une sauce nappante.","Astuce : pour vérifier la consistance, trempez une cuillère et passez le doigt dessus : si la trace reste nette, la sauce est prête.","Versez la sauce dans un bol et gardez la sauteuse pour le poisson.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson. Salez et poivrez-le.","Dans 2 assiettes creuses, déposez l'oeuf battu et un peu de maïzena.","Trempez le poisson dans l'oeuf puis dans la maïzena. Puis de nouveau dans l'oeuf et la maïzena.","Dans la sauteuse encore chaude, ajoutez un filet d’huile de cuisson. Faites cuire le poisson 2 à 3 min de chaque côté, jusqu’à ce qu’il soit doré et cuit à cœur.","Nappez le poisson de sauce aigre-douce et servez aussitôt avec le riz."]}]},{"id":"18467","nom":"Filet d'églefin, sauce chimichurri pimentée et kiwi","image":"images/18467.webp","ingredients":[["gousse d'ail","0.5"],["citron jaune","0.5"],["oignon rouge","0.5"],["piment oiseau (2g)","1x"],["kiwi vert (73g)","1x"],["riz basmati","150 g"],["mélange chimichurri (sachet)","0.5"],["filet d'églefin","240 g"]],"cuisine":["sel","poivre","2 càs huile d'olive"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez la sauce chimichurri et faites cuire le poisson."]},{"titre":"La sauce chimichurri","items":["Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Epluchez et coupez le kiwi en petits dés.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","A l’aide d’une râpe, prélevez les zestes de citron (uniquement l’écorce de couleur) et pressez-le.","Dans un bol, déposez l'oignon, l'ail, le piment, les zestes et jus de citron, l'huile d'olive et les épices chimichurri (attention le chimichurri est fort, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût). Salez et mélangez bien."]},{"titre":"Le poisson","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Rincez et essuyez le poisson. Salez et poivrez-le.","Faites revenir le poisson 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur.","Dégustez votre poisson arrosé de sauce chimichurri et accompagné du riz."]}]},{"id":"18614","nom":"Filet de cabillaud, sauce chimichurri pimentée au kiwi et citron","image":"images/18614.webp","ingredients":[["gousse d'ail","0.5"],["citron jaune","0.5"],["mélange chimichurri (sachet)","0.5"],["riz rond blanc","150 g"],["filet de cabillaud","240 g"],["kiwi vert (73g)","1x"],["oignon rouge","0.25"],["piment oiseau (2g)","1x"]],"cuisine":["sel","poivre","2 càs huile d'olive"],"etapes":[{"titre":"Le poisson noble","items":["Poisson noble : en priorité daurade, bar ou cabillaud. En cas d'indisponibilité selon les conditions de pêche, il pourra exceptionnellement être remplacé par un autre poisson de même qualité."]},{"titre":"Le riz rond","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant la cuisson du riz, préparez la sauce chimichurri et faites cuire le poisson."]},{"titre":"La sauce chimichurri","items":["Ciselez (dés) l'oignon rouge.","Pressez ou hachez l'ail.","Epluchez et coupez le kiwi en petits dés.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","A l’aide d’une râpe, prélevez les zestes de citron (uniquement l’écorce de couleur).","Dans un saladier, pressez le citron. Ajoutez l'oignon, l'ail, le kiwi, le piment, les zestes de citron, l'huile d'olive et les épices chimichurri. Salez et mélangez bien."]},{"titre":"Le poisson","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu vif.","Rincez et essuyez le poisson. Salez et poivrez-le.","Faites revenir le poisson 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur.","Astuce : pour vérifier la cuisson du poisson, piquez-le avec une fourchette. Si la chair se détache facilement, il est cuit. Sinon, couvrez-le et laissez cuire 1 à 2 minutes de plus.","Servez votre poisson nappé de sauce chimichurri."]}]},{"id":"18210","nom":"Filet de canard à la marocaine et semoule aux herbes","image":"images/18210.webp","ingredients":[["filet de canard (240g)","2x"],["citron jaune","0.5"],["gousse d'ail","0.5"],["carotte (100g)","1x"],["graines de couscous","150 g"],["sésame doré","10 g"],["ras el-hanout (sachet)","0.5"],["oignon rouge","0.25"],["persil-menthe (botte)","0.5"]],"cuisine":["2 càs huile d'olive","sel","poivre","150 ml eau"],"etapes":[{"titre":"L'huile à l'ail","items":["Pressez ou hachez l'ail.","Dans une petite casserole, faites chauffer l'huile d'olive et l'ail à feu doux 2 à 3 min. Mélangez bien.","Hors du feu, couvrez et laissez infuser le temps de faire cuire la semoule."]},{"titre":"La semoule","items":["Portez à ébullition l'eau et dans un récipient déposez les graines de couscous.","Versez l'eau sur les graines de couscous. Couvrez et laissez gonfler 5 min.","Pendant ce temps, épluchez et râpez la carotte.","Ciselez (dés) l'oignon rouge.","Effeuillez et ciselez la menthe et le persil.","Une fois les graines de couscous gonflées, ajoutez l'huile à l'ail. Salez, poivrez et à l'aide d'une fourchette, égrainez-les (séparez les grains).","Ajoutez le sésame, la carotte, la moitié des herbes et l'oignon rouge. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, préparez le canard."]},{"titre":"Le canard","items":["Quadrillez la peau des filets de canard à l'aide d'un couteau, sans inciser la chair. Lors de la cuisson, cela permettra à la chaleur de bien pénétrer dans les filets !","Faites chauffer une sauteuse sans matière grasse à feu moyen à vif.","Salez, poivrez les filets de canard et saupoudrez dessus le ras-el-hanout.","Une fois la sauteuse chaude, déposez-y les filets côté peau en-dessous. Faites cuire 3 à 5 min jusqu'à ce que la peau soit bien dorée.","Retournez les filets et poursuivez la cuisson 4 à 8 min selon la cuisson souhaitée (rosée ou à point).","Réservez le canard dans une feuille de papier aluminium et laissez reposer 5 min afin que la viande se détende et s’attendrisse.","Pressez le citron.","Dégraissez légèrement la sauteuse. Versez un petit fond d’eau et un filet de jus de citron dans la sauteuse. Grattez les sucs et portez à ébullition 1 min pour obtenir un jus de cuisson.","Nappez le canard du jus de cuisson et parsemez dessus le reste d'herbes."]}]},{"id":"11279","nom":"Filet de canard au gingembre, soja et salade thaï","image":"images/11279.webp","ingredients":[["sauce soja salée","20 ml"],["gingembre","1 à 3 cm"],["gousse d'ail","0.5"],["huile de sésame toasté","20 ml"],["carotte (100g)","1x"],["sucrine (200g)","1x"],["menthe (botte)","0.5"],["sauce soja spicy","10 ml"],["filet de canard (240g)","2x"],["endive (110g)","1x"]],"cuisine":["sel","poivre","huile de cuisson (mélange 4 huiles par exemple)","2 càs huile de tournesol","1 càs vinaigre de votre choix"],"etapes":[{"titre":"Le canard mariné","items":["Dans un bol, déposez les ingrédients suivants :","Pelez et hachez finement le gingembre et l'ail.","Ajoutez la sauce soja salée et l'huile de sésame toasté. Mélangez bien.","Quadrillez la peau du canard à l'aide d'un couteau, sans inciser la chair. La marinade va mieux s'imprégner et lors de la cuisson cela permettra à la chaleur de bien pénétrer dans les filets !","Déposez le canard dans un plat et arrosez-le avec la marinade.","Laissez mariner 10 min au réfrigérateur pendant la préparation de la salade."]},{"titre":"La salade thaï","items":["Dans un saladier, déposez les ingrédients suivants :","Versez la sauce soja spicy, l'huile de tournesol et le vinaigre. Poivrez et mélangez bien pour obtenir une vinaigrette.","Retirez la base de la sucrine et émincez-la.","Épluchez et râpez la carotte.","Retirez la base de l'endive. Coupez-la en 2 et retirez la partie centrale dure. Émincez-la.","Effeuillez et ciselez la menthe. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"La cuisson","items":["Au bout des 10 min de marinade, dans une poêle, faites chauffer un filet d'huile de cuisson à feu vif.","Une fois la poêle chaude, essuyez légèrement la peau des filets avec du papier absorbant, puis déposez-les dans la poêle côté peau. Faites cuire 3 à 5 min jusqu'à ce que la peau soit bien dorée.","Ensuite, retournez-les et poursuivez la cuisson 4 à 8 min selon la cuisson souhaitée (rosée ou à point).","3 min avant la fin de la cuisson, ajoutez la marinade et arrosez régulièrement le canard.","Réservez le canard dans une feuille de papier aluminium et laissez reposer 5 min afin que la viande se détende et s’attendrisse.","Au moment de servir, coupez le canard en tranches et arrosez-le de sauce."]}]},{"id":"16088","nom":"Filet de lapin à la crème de parmesan, poireau et coquillettes","image":"images/16088.webp","ingredients":[["crème","100 g"],["filet de lapin (250g)","2x"],["parmigiano reggiano râpé","20 g"],["poireau (300g)","1x"],["coquillettes demi-complètes","200 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Le poireau","items":["Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poireau 20 min environ. À mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson. Salez, poivrez.","Pendant ce temps, faites cuire les coquillettes."]},{"titre":"Les coquillettes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les coquillettes selon les indications du paquet.","En parallèle, faites cuire le lapin."]},{"titre":"Le lapin","items":["Salez et poivrez les filets de lapin.","Dans une seconde sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites cuire les filets de lapin 10 min environ. Retournez à mi-cuisson.","Au bout des 10 min, ajoutez la crème et le parmesan.","Mélangez bien et poursuivez la cuisson 2 min jusqu'à ce que la sauce soit nappante.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"13140","nom":"Filet de lieu noir à la sauce satay","image":"images/13140.webp","ingredients":[["lait de coco","200 ml"],["oignon jaune (110g)","1x"],["gousse d'ail (6g)","1x"],["purée de cacahuètes","50 g"],["riz basmati","150 g"],["lieu noir","240 g"],["gingembre","1 à 3 cm"],["cébette (16g)","1x"]],"cuisine":["sel","poivre","huile de cuisson (mélange 4 huiles par exemple)"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez le poisson et la sauce."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson. Coupez-le en morceaux. Salez, poivrez.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites dorer le poisson 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur puis réservez-le.","Astuce : Pour vérifier que le poisson est cuit, remuez une fourchette dans la chair du poisson. Si celle-ci se détache toute seule, alors il est cuit. Si vous le trouvez encore trop rosé, couvrez-le et laissez cuire 1 à 2 minutes de plus."]},{"titre":"La sauce satay","items":["Émincez l'oignon.","Pelez et hachez l'ail et le gingembre.","Retirez la base de la cébette et émincez-la.","Dans la même sauteuse que le poisson, faites chauffer de nouveau un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon, l'ail, le gingembre et la moitié de la cébette 5 min.","Au bout des 5 min, ajoutez la purée de cacahuètes et le lait de coco.","Mélangez bien et poursuivez la cuisson 5 min environ."]},{"titre":"Le poisson sauce satay","items":["Une fois la sauce homogène, replacez le poisson dans la sauteuse et prolongez la cuisson 1 à 2 min pour que tout soit chaud.","Goûtez et rectifiez l’assaisonnement si nécessaire.","Pour une sauce plus liquide, ajoutez de l'eau selon votre goût.","Au moment de servir, parsemez votre assiette du reste de cébette."]}]},{"id":"17513","nom":"Filet de lieu noir sauce kiwi, lamelles de coco et riz au gingembre","image":"images/17513.webp","ingredients":[["crème","100 g"],["lamelles de coco","25 g"],["riz concassé du Pendjab","150 g"],["lieu noir","240 g"],["carotte (220g)","2x"],["oignon jaune (110g)","1x"],["kiwi vert (73g)","1x"],["échalote","0.5"],["gingembre","1 à 3 cm"]],"cuisine":["sel","poivre","huile d'olive","0.5 cube bouillon de poule"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon.","Épluchez et coupez les carottes en fines demi-rondelles.","Pelez et hachez le gingembre.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, les carottes et le gingembre 15 min. Remuez régulièrement.","A mi-cuisson, versez un fond d'eau et émiettez le bouillon de poule. Mélangez bien.","Pendant la cuisson des légumes, préparez le reste des ingrédients."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Au bout des 15 min de cuisson des légumes, ajoutez le riz à la sauteuse et mélangez bien.","Goûtez et rectifiez l’assaisonnement si nécessaire."]},{"titre":"La sauce","items":["Émincez l'échalote.","Pelez et coupez le kiwi en morceaux.","Dans une casserole, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'échalote et le kiwi 5 min environ.","Au bout des 5 min, hors du feu, versez la crème et mélangez bien. Salez, poivrez."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson blanc. Salez et poivrez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir le poisson blanc 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur.","Une fois cuit, versez la sauce dans la sauteuse et mélangez bien.","Astuce : pour vérifier la cuisson du poisson, piquez-le avec une fourchette. Si la chair se détache facilement, il est cuit. Sinon, couvrez-le et laissez cuire 1 à 2 minutes de plus.","Goûtez et rectifiez l’assaisonnement si nécessaire.","Au moment de servir, parsemez votre assiette de lamelles de coco."]}]},{"id":"21154","nom":"Filet de lieu noir tomaté au citron","image":"images/21154.webp","ingredients":[["citron jaune (50g)","0.5"],["tomate (100g)","1x"],["poivron vert (160g)","1x"],["oignon jaune (110g)","1x"],["courgette (200g)","1x"],["lieu noir (240g)","240 g"]],"cuisine":["sel","poivre","0.5 càs huile d'olive","25 g beurre","100 ml eau","0.25 bouillon de légumes (cube)"],"etapes":[{"titre":"La poêlée de légumes","items":["Émincez l'oignon.","Coupez le poivron en fines lanières.","Coupez la courgette en fines demi-rondelles.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les légumes 15 min environ.","À mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson. Salez, poivrez.","En parallèle, faites cuire le poisson."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson. Salez et poivrez-le.","Dans une seconde sauteuse, faites chauffer le beurre et l'huile d'olive à feu vif.","Faites revenir le poisson 2 à 3 min de chaque côté.","Astuce : pour vérifier la cuisson du poisson, piquez-le avec une fourchette. Si la chair se détache facilement, il est cuit. Sinon, couvrez-le et laissez cuire 1 à 2 minutes de plus.","Réservez-le sur une assiette et conservez la sauteuse pour la sauce."]},{"titre":"La sauce","items":["Coupez la tomate en petits dés.","Dans la même sauteuse que le poisson, faites revenir la tomate 5 min environ à feu moyen. Salez, poivrez.","Pressez le citron.","Au bout des 5 min, ajoutez l'eau, le bouillon de légumes émietté et le jus de citron et poursuivez la cuisson 3 à 5 min jusqu'à ce que la sauce soit nappante.","Astuce : la sauce est nappante quand vous pouvez tracer une ligne avec le doigt sur le dos d’une cuillère.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En fin de cuisson, ajoutez le poisson et enrobez-le de sauce."]}]},{"id":"19558","nom":"Filet de lieu noir, sauce aux épinards, pommes de terre et salade d'endive","image":"images/19558.webp","ingredients":[["pomme de terre (440g)","2x"],["échalote (50g)","2x"],["pousses d'épinards","75 g"],["endive (110g)","1x"],["lieu noir","240 g"]],"cuisine":["0.5 bouillon de légumes (cube)","30 g beurre","20 ml lait","huile d'olive","vinaigre de votre choix","sel","poivre"],"etapes":[{"titre":"Les pommes de terre","items":["Épluchez et coupez les pommes de terre en dés.","Déposez-les dans une casserole et recouvrez-les très largement d'eau. Salez.","Faites-les cuire 12 min environ jusqu'à ce qu'elles soient tendres mais pas réduites en purée.","En parallèle, préparez la sauce."]},{"titre":"La sauce","items":["Ciselez (dés) les échalotes.","Dans une seconde casserole, faites fondre le beurre à feu moyen.","Faites revenir les échalotes 5 min.","Ajoutez les pousses d'épinards et faites-les cuire 3 min.","Ajoutez le lait et le bouillon de légumes émietté. Laissez cuire 10 min à petits bouillons. Salez légèrement, poivrez.","Au bout des 10 min, mixez pour obtenir une sauce homogène.","Goûtez et rectifiez l’assaisonnement si nécessaire.","En attendant, préparez le poisson et l'endive."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson. Salez et poivrez-le.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir le poisson 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur.","Astuce : pour vérifier la cuisson du poisson, piquez-le avec une fourchette. Si la chair se détache facilement, il est cuit. Sinon, couvrez-le et laissez cuire 1 à 2 minutes de plus."]},{"titre":"La salade d'endive","items":["Retirez la base de l'endive. Coupez-la en 2 et retirez la partie centrale dure. Émincez-la.","Assaisonnez l'endive d'un filet d'huile d'olive et de vinaigre.","Servez votre poisson nappé de sauce aux épinards et accompagné des pommes de terre et de la salade d'endive."]}]},{"id":"17174","nom":"Filet de limande meunière à la crème de basilic, boulgour et courgettes","image":"images/17174.webp","ingredients":[["crème","100 g"],["boulgour","150 g"],["filet de limande meunière (200g)","2x"],["basilic","qq brins"],["échalote (25g)","1x"],["courgette bio (400g)","2x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes","items":["Émincez l'échalote.","Coupez les courgettes en fines demi-rondelles.","Dans une sauteuse, faites chauffer un filet d’huile d’olive à feu moyen à vif.","Faites revenir l'échalote et les courgettes 15 min. Remuez régulièrement. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire le boulgour."]},{"titre":"Le boulgour","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le boulgour selon les indications du paquet.","Pendant ce temps, préparez la crème de basilic et le poisson."]},{"titre":"La crème de basilic","items":["Dans une petite casserole, faites chauffer la crème 2 à 3 min.","En parallèle, effeuillez le basilic (réservez quelques feuilles pour le dressage).","Lorsque la crème est chaude, hors du feu, ajoutez le basilic et mixez jusqu'à obtenir une texture homogène. Salez, poivrez."]},{"titre":"Le poisson","items":["Faites chauffer une poêle sans matière grasse à feu moyen.","Faites cuire le poisson 3 à 4 min de chaque côté.","Ciselez le reste de basilic et parsemez-le au moment de servir."]}]},{"id":"16124","nom":"Filet de merlan, navets rôtis et crème fumée","image":"images/16124.webp","ingredients":[["gousse d'ail","0.5"],["pomme de terre (440g)","2x"],["crème","100 g"],["paprika fumé (sachet)","0.25"],["herbes de Provence (sachet)","0.25"],["Filet de Merlan","240 g"],["oignon jaune (130g)","1x"],["navet rond (200g)","2x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les navets et les pommes de terre","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, épluchez et coupez les pommes de terre et les navets en dés.","Déposez-les sur une plaque allant au four.","Versez un filet d'huile d'olive. Salez, poivrez et mélangez bien pour tout enrober.","Enfournez 20 à 25 min. Remuez à mi-cuisson.","En parallèle, préparez la sauce."]},{"titre":"La sauce","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Dans une petite casserole, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 10 min environ jusqu'à ce qu'il soit doré.","Ajoutez le paprika fumé, l'ail et la crème. Salez, poivrez.","Mélangez bien et prolongez la cuisson 2 à 3 min jusqu'à ce que la sauce soit nappante.","Astuce : Pour vérifier la consistance de la sauce, trempez une cuillère à soupe dedans et passez votre doigt dessus. La sauce est prête quand il laisse une trace nette."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson.","Déposez-le dans un plat allant au four.","Salez, poivrez, parsemez d'herbes de Provence et versez un filet d'huile d'olive sur le poisson.","Enfournez 10 min environ.","Astuce : Pour vérifier que le poisson est cuit, remuez une fourchette dans la chair du poisson. Si celle-ci se détache toute seule, alors il est cuit. Si vous le trouvez encore trop rosé, couvrez-le et laissez cuire 1 à 2 minutes de plus.","Servez le poisson nappé de sauce."]}]},{"id":"16252","nom":"Filet de poulet et pommes de terre rissolées à la crème de féta au piment","image":"images/16252.webp","ingredients":[["filet de poulet (300g)","2x"],["crème de féta au piment","100 g"],["pomme de terre (440g)","2x"],["salade douceur","50g"],["oignon jaune","0.5"]],"cuisine":["huile d'olive","vinaigre de votre choix","sel","poivre"],"etapes":[{"titre":"Les pommes de terre rissolées","items":["Émincez l'oignon.","Épluchez et coupez les pommes de terre en dés.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les pommes de terre et l'oignon 5 min.","Baissez sur feu moyen et poursuivez la cuisson 15 min à couvert. Remuez régulièrement pendant la cuisson. Salez, poivrez.","Pendant ce temps, préparez les filets de poulet."]},{"titre":"Les filets de poulet","items":["Dans une deuxième sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les filets de poulet 5 à 8 min sur chaque face jusqu'à ce qu'ils soient cuits à coeur (la chair n'est plus rose). Salez, poivrez."]},{"titre":"A table !","items":["Dans une assiette, étalez la crème de féta et ajoutez les pommes de terre rissolées, l'oignon et le filet de poulet.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"22046","nom":"Filet mignon de porc et pesto aux amandes","image":"images/22046.webp","ingredients":[["filet mignon de porc (240g)","2x"],["gousse d'ail (3g)","0.5"],["parmigiano reggiano râpé (20g)","20 g"],["tagliatelles fraîches (250g)","250 g"],["amandes crues (25g)","25 g"],["persil plat (botte) (10g)","0.5"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs eau","beurre"],"etapes":[{"titre":"Les filets mignons","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Épongez la viande à l'aide d'un essuie-tout. Salez, poivrez.","Dans une poêle, faites fondre une noix de beurre à feu moyen.","Faites dorer les filets 5 à 8 min par face jusqu'à ce qu'ils soient cuits à cœur (la chair n'est plus rose).","Pendant la cuisson des filets, faites cuire les tagliatelles."]},{"titre":"Les tagliatelles","items":["Portez à ébullition une casserole d’eau salée","Faites cuire les tagliatelles selon les indications du paquet.","En parallèle de la cuisson des tagliatelles, réalisez le pesto."]},{"titre":"Le pesto","items":["Pressez ou hachez l'ail.","Effeuillez le persil.","Dans le bol d'un mixeur, ajoutez la moitié des amandes, l'huile d'olive, l'eau, le parmesan, l'ail et le persil.","Salez, poivrez et mixez le tout jusqu'à obtenir une texture homogène.","Astuce : vous pouvez ajouter de l'eau pour un pesto plus fluide.","Goûtez et ajoutez une pincée de sel si nécessaire.","Hachez le reste des amandes.","Servez les filets mignons nappés de pesto et parsemez-les avec le reste des amandes."]}]},{"id":"19695","nom":"Fusillis all’arrabbiata pimentées et olives","image":"images/19695.webp","ingredients":[["olives vertes","60 g"],["gousse d'ail (6g)","1x"],["huile pimentée","5 ml"],["purée de tomates","200 g"],["basilic séché (sachet)","0.25"],["fusilli demi-complètes","200 g"],["oignon jaune (110g)","1x"],["pousses d'épinards","200 g"],["Grana Padano râpé","20 g"]],"cuisine":["sel","huile d'olive","poivre"],"etapes":[{"titre":"Les fusillis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les fusillis selon les indications du paquet.","Une fois cuites, égouttez-les et mettez de côté un bol d'eau de cuisson des pâtes.","Pendant la cuisson des pâtes, préparez la sauce."]},{"titre":"La sauce arrabbiata","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Coupez les olives en rondelles.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez la purée de tomates, l'ail, les olives, le basilic séché et les épinards (en plusieurs fois jusqu'à ce qu'ils soient tombés).","Poursuivez la cuisson 5 min environ. Salez, poivrez.","Astuce : pour réduire l'acidité de la sauce tomate, ajoutez une cuillère à café de sucre.","Une fois les fusillis cuites, ajoutez-les à la sauteuse avec un peu d'eau de cuisson des pâtes. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, arrosez d'un filet d'huile pimentée (l'huile est forte, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût) et parsemez de grana padano."]}]},{"id":"18596","nom":"Fusillis au lieu noir, poireau et crème au curry","image":"images/18596.webp","ingredients":[["curry jaune doux (sachet)","0.5"],["crème","100 g"],["gousse d'ail (6g)","1x"],["oignon jaune (110g)","1x"],["poireau (215g)","1x"],["gingembre","1 à 3 cm"],["fusillis demi-complètes","200 g"],["lieu noir","240 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Le poireau","items":["Émincez l'oignon.","Pelez et hachez l'ail et le gingembre.","Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir le poireau, l'oignon, l'ail et le gingembre 15 min. Salez, poivrez.","A mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson.","En parallèle, faites cuire les fusillis."]},{"titre":"Les fusillis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les fusillis selon les indications du paquet.","Pendant ce temps, préparez le poisson."]},{"titre":"Le poisson et la crème au curry","items":["Rincez et essuyez le poisson. Salez et poivrez-le. Coupez-le en morceaux.","Au bout des 15 min de cuisson du poireau, ajoutez le poisson et poursuivez la cuisson à couvert 5 min.","Ajoutez la crème, le curry et faites cuire 5 min supplémentaires en remuant régulièrement.","Une fois le tout cuit, ajoutez les fusillis dans la sauteuse et mélangez délicatement.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"18566","nom":"Fusillis aux champignons, sel à la truffe et burrata","image":"images/18566.webp","ingredients":[["parmigiano reggiano râpé","20 g"],["burrata (100g)","1x"],["fusilli demi-complètes","200 g"],["champignons de Paris blancs","250 g"],["sel à la truffe","2 pincée"],["persil plat","qq brins"]],"cuisine":["sel","poivre","beurre"],"etapes":[{"titre":"Les fusillis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet. Avant d’égoutter, prélevez un peu d’eau de cuisson.","Pendant la cuisson des pâtes, faites cuire les champignons."]},{"titre":"Les champignons","items":["Coupez les champignons de Paris en tranches.","Dans une sauteuse, faites chauffer une noix de beurre à feu moyen à vif.","Faites revenir les champignons 10 à 15 min. Salez, poivrez."]},{"titre":"A table !","items":["Effeuillez et ciselez le persil.","Ajoutez les pâtes dans la sauteuse avec un peu d’eau de cuisson (1 càs par personne).","Incorporez le parmesan, le sel à la truffe et le persil ciselé. Mélangez bien pour lier le tout.","Goûtez et rectifiez l’assaisonnement si nécessaire.","Déchirez la burrata et déposez les morceaux sur votre assiette."]}]},{"id":"21082","nom":"Galette de sarrasin au jambon fumé végétal, mozzarella et oeuf","image":"images/21082.webp","ingredients":[["galette de blé noir (100g)","2x"],["mozzarella de vache (125g)","1x"],["tomate (100g)","1x"],["jambon fumé végétal (tranche) (60g)","2x"],["salade (50g)","50 g"]],"cuisine":["2 oeuf","2 càs huile d'olive","1 càs vinaigre de votre choix","beurre","sel","poivre"],"etapes":[{"titre":"Les galettes","items":["Coupez le jambon en morceaux.","Coupez la mozzarella en dés.","Dans une poêle, faites chauffer une noix de beurre à feu moyen.","Faites chauffer une galette de sarrasin 1 min. Cassez un œuf au centre et faites chauffer jusqu'à ce que les bords de la galette soient grillés et que le blanc d'œuf soit presque entièrement cuit.","Ajoutez ensuite du jambon et de la mozzarella autour du jaune d'œuf. Salez, poivrez.","Refermez les bords de la galette pour former un carré et laissez cuire 2 à 3 min jusqu'à ce que le fromage fonde.","Réservez la galette sur une assiette et renouvelez l’opération avec le reste des ingrédients.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Coupez la tomate en fins quartiers.","Dans un saladier, ajoutez l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Ajoutez la tomate et la salade. Mélangez.","Goûtez et ajoutez une pincée de sel si nécessaire."]}]},{"id":"18136","nom":"Galette de sarrasin épinards, citron, fromage frais et noisettes","image":"images/18136.webp","ingredients":[["galette de blé noir (100g)","2x"],["citron jaune","0.5"],["noisettes décortiquées","15 g"],["endive (220g)","2x"],["fromage à tartiner double crème nature","60 g"],["oignon jaune (110g)","1x"],["pousses d'épinards","200 g"]],"cuisine":["2 càs huile d'olive","1 càs vinaigre de votre choix","beurre","sel","poivre","2 oeuf"],"etapes":[{"titre":"Les épinards","items":["Émincez l'oignon.","À l'aide d’une râpe, prélevez des zestes de citron (uniquement l’écorce de couleur) et pressez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les épinards et l'oignon 10 min environ jusqu'à ce qu'il n'y ait plus d'eau de végétation et que l'oignon soit tendre. Salez, poivrez.","Au bout des 10 min, ajoutez les zestes, le jus de citron et le fromage à tartiner. Mélangez bien.","Poursuivez la cuisson 1 à 2 min à feu doux. Salez, poivrez. Remuez régulièrement.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Retirez la base des endives. Coupez-les en 2 et retirez la partie centrale dure. Émincez-les.","Dans un saladier, versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ajoutez les endives."]},{"titre":"Les galettes","items":["Faite chauffer une poêle sans matière grasse à feu moyen.","Faites torréfier (dorer) les noisettes.","Réservez-les dans une assiette.","Dans la même poêle que celle des noisettes, faites chauffer une noix de beurre à feu moyen.","Déposez une galette de sarrasin et cassez un œuf dedans. Faites cuire quelques minutes jusqu'à ce que le blanc soit pris.","Répartissez autour du jaune d'oeuf un peu d'épinards au citron et quelques noisettes torréfiées.","Laissez cuire 2 à 3 min.","Rabattez les bords de la galette de manière à former un carré et réservez-la.","Renouvelez l'opération avec le reste des ingrédients.","Astuce : s'il vous reste des noisettes, ajoutez-les à votre salade d'endives pour ajouter du croquant."]}]},{"id":"21313","nom":"Girasolis alla pizzaiola crémeux au poireau et épinards","image":"images/21313.webp","ingredients":[["crème (100g)","100 g"],["gousse d'ail (6g)","1x"],["girasolis alla pizzaiola (250g)","250 g"],["poireau (180g)","1x"],["pousses d'épinards (100g)","100 g"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes","items":["Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Émincez l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, l'ail et le poireau 5 min. Salez, poivrez.","Ajoutez un fond d'eau, couvrez et poursuivez la cuisson 15 min jusqu'à ce que le poireau soit tendre.","Au bout de 15 min, ajoutez les pousses d'épinards à la sauteuse et poursuivez la cuisson de 2 à 3 min, jusqu'à ce que les épinards soient tombés (réduits).","Pendant la cuisson des légumes, faites cuire les girasolis."]},{"titre":"Les girasolis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les girasolis selon les indications du paquet.","Réservez un peu d'eau de cuisson pour lier la sauce, puis égouttez-les."]},{"titre":"A table !","items":["Une fois les légumes cuits et les girasolis cuits et égouttés, ajoutez ces derniers, la crème et un peu d'eau de cuisson des pâtes à la sauteuse des légumes.","Astuce : ajoutez un peu d’eau de cuisson des pâtes pour lier la sauce grâce à l’amidon.","Mélangez bien et poursuivez la cuisson 1 min à feu doux jusqu'à obtenir une sauce onctueuse qui enrobe bien les pâtes.","Goûtez et ajoutez une pincée de sel et de poivre si nécessaire."]}]},{"id":"18471","nom":"Gnocchis à la crème de butternut et noisettes","image":"images/18471.webp","ingredients":[["courge butternut","175 g"],["gousse d'ail (6g)","1x"],["crème","100 g"],["noisettes décortiquées","25 g"],["gnocchis de pommes de terre fraîches","400 g"],["oignon jaune (110g)","1x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","0.5 cube bouillon de légumes"],"etapes":[{"titre":"La crème de butternut","items":["Astuce : pour qu'elle soit plus facile à découper, passez la courge 5 min au micro-ondes à pleine puissance. Ensuite, manipulez-la avec un torchon pour ne pas vous brûler.","Épluchez le butternut et retirez les graines à l'aide d'une cuillère. Coupez-le en tranches puis taillez celles-ci en dés.","Pressez ou hachez l'ail.","Déposez le butternut dans une casserole avec la moitié de l'ail et le bouillon de légumes. Recouvrez-le très largement d'eau. Faites cuire le tout 15 à 20 min jusqu'à ce que le butternut soit cuit. Salez, poivrez.","Une fois cuit, égouttez le butternut en réservant l'eau de cuisson.","Mixez le butternut avec la crème jusqu'à obtenir une texture homogène.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Astuce : ajoutez de l'eau de cuisson petit à petit pour ajuster la texture de la sauce selon votre goût.","En parallèle, faites cuire les gnocchis."]},{"titre":"Les gnocchis","items":["Émincez l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon avec le reste de l'ail 10 min. Salez, poivrez.","Au bout des 10 min, ajoutez les gnocchis et poursuivez la cuisson 10 min jusqu'à ce qu'ils soient dorés et moelleux.","Couvrez à mi-cuisson. Salez, poivrez. Remuez régulièrement.","Effeuillez et ciselez le persil.","Hachez grossièrement les noisettes.","Au moment de servir, nappez les gnocchis avec la crème de butternut.","Parsemez le tout de noisettes et persil."]}]},{"id":"14469","nom":"Gnocchis à la crème de chorizo et tomates grillées","image":"images/14469.webp","ingredients":[["oignon jaune (125g)","1x"],["crème épaisse","80 g"],["gousse d'ail","0.5"],["Gnocchi de pommes de terre fraiches","400 g"],["tomate (200g)","2x"],["chorizo à griller (240g) Bleu Blanc Coeur","4x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La crème de chorizo","items":["Coupez les chorizos à griller en dés.","Émincez l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et le chorizo 10 min environ. Salez légèrement, poivrez.","Au bout des 10 min de cuisson, ajoutez l'ail et la crème et prolongez la cuisson 5 min environ.","Au bout des 5 min, mixez la moitié de la préparation et remettez la crème de chorizo dans la sauteuse.","En parallèle, faites cuire les gnocchis et les tomates grillées."]},{"titre":"Les gnocchis et les tomates grillées","items":["Coupez les tomates en morceaux.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les gnocchis 5 min environ jusqu'à ce qu'ils soient moelleux et dorés. Salez, poivrez. Remuez régulièrement.","Une fois cuits, réservez-les.","Dans la même poêle, faites chauffer de nouveau un filet d'huile d'olive à feu vif.","Faites griller les tomates 3 min jusqu'à ce qu'elles noircissent légèrement."]},{"titre":"A table !","items":["Une fois le tout cuit, ajoutez les gnocchis et les tomates grillées à la sauteuse de la garniture. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17262","nom":"Gnocchis à la crème de morbier et champignons","image":"images/17262.webp","ingredients":[["crème","100 g"],["gousse d'ail","0.5"],["morbier au lait cru de vache","60 g"],["champignons de Paris blancs","250 g"],["gnocchis de pommes de terre fraiches","400 g"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les gnocchis","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les gnocchis 5 min environ jusqu'à ce qu'ils soient moelleux et dorés. Salez, poivrez. Remuez régulièrement.","Une fois dorés, débarrassez-les et conservez la sauteuse."]},{"titre":"Les champignons","items":["Coupez les champignons en tranches.","Pressez ou hachez l'ail.","Émincez l'oignon.","Dans la sauteuse, faites chauffer un nouveau filet d'huile d'olive à feu moyen à vif.","Faites revenir les champignons, l'oignon et l'ail 10 min environ. Salez, poivrez."]},{"titre":"A table !","items":["Coupez le morbier en dés.","Au bout des 10 min, ajoutez la crème et le morbier. Mélangez bien.","Poursuivez la cuisson 2 à 3 min à feu doux jusqu'à ce que le morbier fonde.","Ajoutez les gnocchis et mélangez bien pour les enrober de sauce.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"19485","nom":"Gnocchis à la poitrine fumée et sauce persillée","image":"images/19485.webp","ingredients":[["poitrine fumée","90 g"],["gousse d'ail","0.5"],["gnocchi de pommes de terre fraîches","400 g"],["fromage blanc","100 g"],["pousses d'épinards","200 g"],["persil plat","qq brins"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes, les gnocchis et la poitrine fumée","items":["Émincez l'oignon.","Coupez la poitrine fumée en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et la poitrine fumée 10 min.","Au bout des 8 min, ajoutez les gnocchis et faites-les revenir 5 min.","Ajoutez les pousses d'épinards et laissez cuire 5 min supplémentaires jusqu'à ce qu'ils soient fondants.","En parallèle, réalisez la sauce persillée."]},{"titre":"La sauce persillée","items":["Pressez ou hachez l'ail.","Effeuillez et ciselez le persil.","Dans un bol, mélangez le fromage blanc, l'ail et le persil. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Nappez les gnocchis de sauce persillée."]}]},{"id":"15965","nom":"Gnocchis à la poitrine fumée, champignons et fromage ail et fines herbes","image":"images/15965.webp","ingredients":[["poitrine fumée","90 g"],["gnocchis de pommes de terre fraîches","400 g"],["gousse d'ail","0.5"],["champignons de Paris blancs","250 g"],["fromage à tartiner ail et fines herbes","60 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les champignons et la poitrine fumée","items":["Pressez ou hachez l'ail.","Coupez les champignons de Paris en 2 ou 4 s'ils sont un peu gros.","Coupez la poitrine fumée en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les champignons, l'ail et la poitrine fumée 5 min. Ensuite, baissez à feu moyen et poursuivez 10 min environ.","En parallèle, préparez les gnocchis."]},{"titre":"Les gnocchis","items":["Dans une seconde sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les gnocchis 5 min environ jusqu'à ce qu'ils soient dorés.","Au bout des 5 min, couvrez et faites cuire 5 min à feu doux. Salez, poivrez. Remuez régulièrement."]},{"titre":"A table !","items":["Une fois le tout cuit, versez les gnocchis dans la sauteuse des champignons.","Hors du feu, ajoutez le fromage ail et fines herbes et mélangez bien jusqu'à ce qu'il enrobe le tout.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"18080","nom":"Gnocchis aux épinards, ricotta, citron et parmesan","image":"images/18080.webp","ingredients":[["crème","100 g"],["ricotta","150 g"],["gousse d'ail (6g)","1x"],["parmigiano reggiano râpé","20 g"],["citron jaune","0.5"],["gnocchi de pommes de terre fraîches","400 g"],["pousses d'épinards","100 g"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les épinards et la sauce","items":["Ciselez (dés) l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon 2 à 3 min pour le dorer puis ajoutez les épinards et poursuivez la cuisson 5 min.","Pendant ce temps, pressez ou hachez l'ail.","A l'aide d’une râpe, prélevez des zestes de citron (uniquement l’écorce de couleur) puis coupez-le en quartiers.","Au bout des 5 min, ajoutez l'ail, les zestes de citron, la ricotta et la crème. Salez, poivrez.","Couvrez et laissez cuire 10 min environ. Remuez régulièrement.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, préparez les gnocchis."]},{"titre":"Les gnocchis","items":["Dans une seconde sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les gnocchis 5 min environ jusqu'à ce qu'ils soient dorés."]},{"titre":"A table !","items":["Une fois le tout cuit, ajoutez les gnocchis dans la sauteuse des épinards. Mélangez bien.","Au moment de servir, parsemez les gnocchis de parmesan et arrosez d'un filet de jus de citron."]}]},{"id":"16833","nom":"Gnocchis crémeux à la burrata et harissa pimentée","image":"images/16833.webp","ingredients":[["gousse d'ail (6g)","1x"],["burrata (100g)","1x"],["persil plat","qq brins"],["gnocchis de pommes de terre fraîches","400 g"],["piment oiseau (4g)","2x"],["courgette (200g)","1x"],["concentré de tomate","35 g"]],"cuisine":["sel","poivre","2 huile d'olive (càs)","beurre"],"etapes":[{"titre":"La courgette","items":["Coupez la courgette en demi-rondelles.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites cuire la courgette 10 à 15 min. Salez, poivrez.","Conseil : Ne remuez pas les légumes immédiatement après les avoir déposés dans la poêle, laissez-les caraméliser quelques minutes pour obtenir une belle couleur dorée.","Pendant ce temps, réalisez la sauce."]},{"titre":"La sauce","items":["Dans un bol, déposez les ingrédients suivants :","Hachez les piments oiseaux (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après les avoir manipulés, ils peuvent irriter la peau. Ajustez la quantité selon votre goût.","Ajoutez le concentré de tomates et l'huile d'olive. Salez, poivrez et mélangez bien.","Coupez la burrata en morceaux. Mélangez bien."]},{"titre":"Les gnocchis","items":["Pressez ou hachez l'ail.","Dans une seconde sauteuse, faites fondre une noix de beurre à feu moyen à vif.","Faites revenir l'ail et les gnocchis 5 min environ. Remuez régulièrement.","Au bout des 5 min, ajoutez le mélange burrata/harissa, la courgette cuite et un fond d'eau.","Laissez mijoter quelques minutes jusqu'à ce que la burrata soit fondue.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Effeuillez et ciselez le persil. Au moment de passer à table, parsemez-le sur les gnocchis."]}]},{"id":"18655","nom":"Gratin d'orzo à la scamorza, poireau et poitrine fumée","image":"images/18655.webp","ingredients":[["crème","80 g"],["gousse d'ail (4g)","1x"],["scamorza fumée","100 g"],["poitrine fumée","90 g"],["poireau (215g)","1x"],["pâtes orzo","200 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La cuisson de l'orzo","items":["Préchauffez votre four à 250°C en mode grill !","Pendant ce temps, portez à ébullition une casserole d'eau salée.","Faites cuire l'orzo selon les indications du paquet.","En parallèle, préparez le reste des ingrédients."]},{"titre":"La garniture","items":["Coupez et retirez la base abîmée du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Coupez la poitrine fumée en morceaux.","Dans une sauteuse, faites chauffer un léger filet d'huile d'olive à feu moyen.","Faites revenir la poitrine fumée et le poireau 20 min environ jusqu'à ce que le poireau soit cuit. Salez, poivrez.","En parallèle, râpez la scamorza fumée.","Pressez ou hachez l'ail.","Une fois la garniture cuite, ajoutez la crème, l'ail et la moitié de la scamorza dans la sauteuse.","Mélangez 2 min à feu doux jusqu'à ce que le fromage soit fondu.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"A table !","items":["Dans un plat à gratin, déposez l'orzo égoutté et la poêlée de poireau et poitrine fumée. Mélangez bien.","Parsemez dessus le reste de scamorza et enfournez 5 min jusqu'à ce que le fromage soit fondu et doré."]}]},{"id":"19275","nom":"Gratin d'orzo aux deux fromages et lardons","image":"images/19275.webp","ingredients":[["tomme franc-comtoise râpée (lait pasteurisé)","60 g"],["parmigiano reggiano râpé","20 g"],["crème","80 g"],["pâtes orzo","200 g"],["lardons fumés","150 g"],["salade","50 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix"],"etapes":[{"titre":"L'orzo","items":["Préchauffez votre four en mode grill (240°C) !","Pendant ce temps, portez à ébullition une casserole d'eau salée.","Faites cuire l'orzo selon les indications du paquet.","En parallèle, préparez le reste des ingrédients."]},{"titre":"Le gratin","items":["Faites chauffer une sauteuse sans matière grasse à feu moyen.","Faites revenir les lardons 5 min environ.","Ajoutez la crème, le parmesan et la tomme franc-comtoise.","Mélangez 2 min à feu doux jusqu'à ce que les fromages soient fondus.","Dans un plat à gratin, déposez l'orzo et le mélange de lardons à la crème. Poivrez et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Enfournez 5 min pour faire gratiner le fromage.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"17744","nom":"Gratin de coquillettes, champignons, tomme franc-comtoise et truffe","image":"images/17744.webp","ingredients":[["sel aromatisé à la truffe (sachet)","0.5"],["crème","100 g"],["champignons de Paris blancs","250 g"],["tomme franc-comtoise râpée (lait pasteurisé)","60 g"],["ciboulette","qq brins"],["oignon jaune (125g)","1x"],["coquillettes demi-complètes","200 g"],["échalote","0.5"],["mélange de salade","50 g"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"Les coquillettes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Astuce : Vérifiez la cuisson des pâtes en les goûtant : elles finiront de cuire au four, donc elles doivent être très légèrement al dente.","Astuce : Gardez une petite louche d’eau de cuisson des pâtes. Si votre gratin paraît trop sec, ajoutez-en quelques cuillerées avant d’enfourner.","Pendant la cuisson des coquillettes, préparez la garniture."]},{"titre":"La garniture","items":["Préchauffez votre four sur grill à 250°C !","Émincez l'oignon.","Coupez les champignons de Paris en tranches.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et les champignons 10 min. Salez, poivrez.","En parallèle, ciselez la ciboulette.","Au bout des 10 min de cuisson, ajoutez la ciboulette, la crème, l'assaisonnement à la truffe et la moitié de la tomme. Poursuivez la cuisson 2 min.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le gratin","items":["Une fois le tout cuit, déposez les coquillettes et la garniture dans un plat allant au four. Mélangez bien.","Parsemez le tout avec le reste de tomme.","Enfournez 5 min environ sous le grill, jusqu’à ce que le fromage soit bien gratiné.","Pendant ce temps, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'échalote.","Versez l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Ajoutez la salade."]}]},{"id":"18996","nom":"Gratin de gnocchis à la raclette, épinards et piment chipotle","image":"images/18996.webp","ingredients":[["raclette au lait cru vache","60 g"],["crème","100 g"],["piment chipotle (pincée) (0.4g)","2x"],["gnocchis","400 g"],["pousses d'épinards","200 g"],["gousse d'ail (6g)","1x"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix"],"etapes":[{"titre":"La garniture","items":["Préchauffez votre four à 250°C en mode grill !","Pendant ce temps, émincez l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et l'ail 10 min.","Au bout des 10 min, ajoutez la crème, le piment chipotle et les pousses d'épinards (conservez une poignée d'épinards par personne). Salez, poivrez et poursuivez la cuisson 5 min environ.","Astuce : le piment est fort, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les gnocchis."]},{"titre":"Les gnocchis","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les gnocchis 5 min. Salez, poivrez. Remuez régulièrement."]},{"titre":"Le gratin","items":["Coupez la raclette en tranches.","Dans un plat à gratin, mélangez la garniture avec les gnocchis. Répartissez par-dessus les tranches de raclette.","Enfournez 5 min jusqu'à ce que le fromage gratine.","Assaisonnez le reste des pousses d'épinards d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"17160","nom":"Gratin de ravioles du Dauphiné, aubergine et sauce tomate","image":"images/17160.webp","ingredients":[["ravioles du Dauphiné IGP (240g) IGP","240 g"],["parmigiano reggiano râpé (20g)","20g"],["oignon jaune (110g)","1x"],["aubergine (275g)","1x"],["purée de tomates (200g)","200 g"],["mélange tex mex (sachet) (3g)","0.5"],["salade (50g)","50 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix"],"etapes":[{"titre":"L'aubergine","items":["Préchauffez le four à 220°C en chaleur tournante !","Pendant ce temps, coupez l'aubergine en fines tranches dans la longueur.","Déposez-les sur une plaque allant au four. Versez un filet d'huile d'olive. Salez, poivrez.","Enfournez 10 min environ, jusqu'à ce que les tranches commencent à s'attendrir.","Pendant ce temps, préparez la sauce tomate."]},{"titre":"La sauce tomate","items":["Émincez l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et le mélange tex-mex 5 min. Salez, poivrez.","Ajoutez la purée de tomates et un fond d'eau pour fluidifier la sauce et éviter qu'elle n'accroche. Laissez mijoter 10 à 15 min jusqu'à ce que la sauce soit chaude et légèrement épaissie.","Astuce : ajoutez une cuillère à café de sucre pour réduire l'acidité de la sauce tomate.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le gratin","items":["Dans un plat à gratin, alternez les couches d'aubergine, de sauce tomate et de ravioles.","Répétez l'opération avec le reste des ingrédients.","Parsemez de parmesan et enfournez 5 à 10 min, jusqu'à ce que les ravioles soient bien chaudes et le parmesan gratiné.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"18853","nom":"Gratin de rotolos aux épinards et ricotta","image":"images/18853.webp","ingredients":[["feuilles de lasagne (125g)","125 g"],["pousses d'épinards (200g)","200 g"],["ricotta (250g)","250 g"],["pulpe de tomates (210g)","210 g"],["gousse d'ail (6g)","1x"],["parmigiano reggiano râpé (30g)","30 g"],["oignon jaune (55g)","0.5"],["citron jaune (62.5g)","0.5"]],"cuisine":["huile d'olive","sel","poivre","100 ml eau"],"etapes":[{"titre":"La sauce tomate","items":["Préchauffez votre four à 200°C en chaleur tournante !","Pendant ce temps, ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Dans une casserole faites chauffer un filet d'huile d'olive à feu moyen.","Faites dorer l'oignon 5 min jusqu'à ce qu'il devienne translucide.","Ajoutez la pulpe de tomates, l'eau et l'ail. Salez, poivrez.","Astuce : ajoutez un peu de sucre dans votre sauce tomate si elle est trop acide.","Laissez mijoter à feu doux le temps de préparer le reste de la recette."]},{"titre":"La farce","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les épinards 5 min. Salez, poivrez.","Une fois cuits, essorez-les pour retirer un maximum d'eau.","Astuce : utilisez une deuxième sauteuse ou faites-les revenir en plusieurs fois si la quantité d'épinards est trop volumineuse.","À l'aide d’une râpe, prélevez des zestes de citron (uniquement l’écorce de couleur).","Pressez le citron.","Dans un saladier, mélangez la ricotta (sans l'eau de conservation), les zestes, le jus du citron et les épinards cuits. Salez, poivrez."]},{"titre":"Le montage","items":["Portez à ébullition une seconde casserole d'eau salée.","Faites cuire successivement ou 2 par 2 les feuilles de lasagnes 2 à 3 minutes.","Une fois cuites, déposez chaque feuille de lasagnes sur votre plan de travail ou sur un plateau sans les superposer.","Répartissez la farce sur un côté court des feuilles de lasagnes et laissez une marge de 1 à 2 cm sur les bords.","Roulez la feuille sur elle-même pour former un boudin.","Coupez chaque boudin en 3 ou 4.","Astuce : pour gagner du temps, vous pouvez également laisser les boudins entiers et réaliser des cannellonis à la place ou ne pas faire de boudin et transformer la recette en lasagnes."]},{"titre":"La cuisson","items":["Versez la moitié de la sauce tomate dans un plat allant au four.","Déposez les boudins coupés debout dans le plat rempli de sauce.","Versez le reste de la sauce tomate sur les boudins.","Couvrez d'un papier aluminium et enfournez 10 min.","Au bout des 10 min, parsemez de parmesan, arrosez d'un filet d'huile d'olive et enfournez à nouveau sans papier pendant 10 min jusqu'à ce que le fromage gratine et que les bords croustillent."]}]},{"id":"21776","nom":"Green mac'n'cheese aux poireaux","image":"images/21776.webp","ingredients":[["lait demi-écrémé stérilisé (300g)","300 ml"],["emmental pasteurisé râpé français (75g)","75 g"],["ail semoule (0.6g)","1 càc"],["pousses d'épinards (50g)","50 g"],["farine de blé (25g)","25 g"],["macaroni demi-complets (200g)","200 g"],["poireau (260g)","2x"]],"cuisine":["sel","poivre","huile d'olive","25 g beurre"],"etapes":[{"titre":"Les poireaux","items":["Coupez et retirez la base des poireaux. Incisez-les en deux dans la longueur et rincez-les soigneusement. Émincez-les.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les poireaux 20 min environ.","À mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson. Salez, poivrez.","Pendant la cuisson des poireaux, faites cuire les macaronis et préparez la béchamel."]},{"titre":"Les macaronis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les pâtes selon les indications du paquet."]},{"titre":"La béchamel verte","items":["Préchauffez le four à 230°C en mode grill.","Dans le bol d'un mixeur, déposez l'ail semoule, les pousses d'épinards et la moitié du lait. Salez, poivrez et mixez jusqu'à obtenir une texture homogène.","Dans une grande casserole, faites fondre le beurre à feu moyen.","Ajoutez la farine et remuez au fouet. Faites chauffer 30 sec à 1 min jusqu’à ce que l’ensemble soit doré.","Puis, ajoutez le reste de lait et fouettez énergiquement.","Faites cuire 5 min en remuant au fouet jusqu’à ce que la béchamel ait épaissi.","Une fois la béchamel prête, ajoutez la sauce verte et la moitié de l'emmental râpé.","Mélangez bien et faites épaissir de nouveau quelques minutes."]},{"titre":"Le mac'n'cheese","items":["Une fois les poireaux et les macaronis cuits, ajoutez-les dans la casserole de la béchamel verte. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Déposez le tout dans un plat à gratin. Parsemez du reste d'emmental râpé.","Enfournez 5 min environ jusqu'à ce que le fromage gratine."]}]},{"id":"19872","nom":"Halloumi tandoori, chutney de menthe et riz pilaf","image":"images/19872.webp","ingredients":[["halloumi (200g)","200 g"],["yaourt à la grecque (100g)","100 g"],["épices tandoori (sachet) (3g)","0.5"],["gousse d'ail (4g)","1x"],["cumin (sachet) (4g)","0.5"],["carotte (100g)","1x"],["riz concassé du Pendjab (150g)","150 g"],["gingembre (20g)","1 à 3 cm"],["citron vert (45g)","0.5"],["menthe (botte) (5g)","1x"]],"cuisine":["sel","poivre","huile de cuisson","400 ml eau","0.5 cube bouillon de légumes"],"etapes":[{"titre":"Le riz pilaf","items":["Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir l'ail et le riz 3 min environ. Versez l'eau, le bouillon de légumes émietté et portez à ébullition.","Baissez à feu moyen, couvrez et laissez cuire à petite ébullition 15 min. Salez, poivrez.","Astuce : Si le riz n'est pas suffisamment cuit et qu’il n’y a plus d'eau, rajoutez de l'eau chaude et poursuivez la cuisson quelques minutes.","Pendant ce temps, épluchez et râpez la carotte.","A mi-cuisson du riz, ajoutez la carotte à la sauteuse et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant la cuisson du riz, préparez le chutney."]},{"titre":"Le chutney","items":["Pressez le citron.","Pelez et coupez le gingembre en petits morceaux.","Effeuillez la menthe.","Dans le bol d'un mixeur, déposez le jus du citron, le gingembre, la menthe, le yaourt à la grecque et le cumin. Salez, poivrez.","Mixez jusqu'à obtenir une consistance homogène.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le halloumi","items":["Rincez le halloumi pour retirer l'excédent de sel et épongez-le à l'aide d'un essuie-tout.","Coupez le halloumi en tranche.","Dans une seconde sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir le halloumi avec les épices tandoori 2 à 3 min de chaque côté jusqu'à ce qu'il soit bien doré.","Servez le halloumi avec le riz nappé de chutney."]}]},{"id":"17167","nom":"Haricots blancs au paprika fumé et brocoli","image":"images/17167.webp","ingredients":[["paprika fumé (sachet)","0.5"],["crème","100 g"],["gousse d'ail (6g)","1x"],["riz basmati","150 g"],["haricots blancs conserve (g égouttés) (250g)","250x"],["concentré de tomates","20 g"],["brocoli","0.5"],["persil plat","qq brins"],["oignon jaune (125g)","1x"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Le brocoli","items":["Portez à ébullition une casserole d'eau salée.","Pendant ce temps, coupez les bouquets de brocoli. Épluchez la tige et émincez-la.","Faites cuire le brocoli 10 min environ.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une seconde casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"Les haricots blancs","items":["Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Égouttez et rincez les haricots blancs.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites dorer l'oignon 5 min.","Ajoutez l'ail, le concentré de tomates, le paprika fumé et poursuivez la cuisson 2 min.","Au bout des 2 min, ajoutez les haricots blancs et la crème.","Faites cuire à petits bouillons 5 min. Salez, poivrez.","En fin de cuisson, ajoutez le brocoli cuit et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Effeuillez et ciselez le persil.","Parsemez-le sur l'ensemble de la recette au moment de servir."]}]},{"id":"16020","nom":"Haricots blancs aux tomates, épinards et féta","image":"images/16020.webp","ingredients":[["oignon jaune (110g)","1x"],["origan (sachet)","0.25"],["gousse d'ail (6g)","1x"],["pulpe de tomates","200 g"],["haricots blancs conserve","250 g"],["féta","70 g"],["céleri branche (50g)","1x"],["pousses d'épinards","200 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes","items":["Retirez le bout abîmé du céleri branche et émincez-le.","Émincez l'oignon.","Pressez ou hachez l'ail.","Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez la pulpe de tomates, l'ail, le céleri et l'origan. Salez, poivrez.","Poursuivez la cuisson 10 min.","Astuce : ajoutez une cuillère à café de sucre pour réduire l'acidité de la sauce tomate."]},{"titre":"A table !","items":["Égouttez et rincez les haricots blancs.","En fin de cuisson, ajoutez les pousses d'épinards et les haricots blancs. Poursuivez la cuisson 5 min.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Émiettez la féta et parsemez-la sur le plat au moment de servir."]}]},{"id":"17344","nom":"Hot-dog de truite citronné et confit d'oignon rouge","image":"images/17344.webp","ingredients":[["pain hot-dog (160g)","2x"],["fromage blanc","100 g"],["oignon rouge (110g)","1x"],["citron jaune","0.5"],["pavé de truite","250 g"],["salade","50 g"]],"cuisine":["2 càs farine","1 oeuf","sel","poivre","huile d'olive","1 càc sucre","vinaigre de votre choix"],"etapes":[{"titre":"Le confit d'oignon","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, émincez l'oignon.","Dans une petite casserole, faites chauffer un filet d’huile d'olive à feu moyen.","Faites revenir l'oignon et le sucre 12 à 15 min jusqu’à ce qu’il soit légèrement confit. Salez, poivrez.","En parallèle, faites cuire la truite."]},{"titre":"La truite","items":["Dans deux assiettes creuses, déposez la farine et l’œuf battu.","Rincez et essuyez la truite. Salez et poivrez-la.","Coupez-la en morceaux et trempez-la successivement dans la farine, l’œuf, puis à nouveau dans la farine.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites dorer les morceaux de poisson 5 min environ en les retournant régulièrement jusqu’à ce qu’ils soient cuits à cœur.","Pendant ce temps, faites chauffer les pains et réalisez la sauce."]},{"titre":"La sauce","items":["Passez les pains à hot-dog au four selon les indications du paquet pour les faire dorer puis ouvrez-les en deux.","A l’aide d’une râpe, prélevez des zestes de citron (uniquement l’écorce de couleur) et coupez-le en quartiers.","Dans un bol, mélangez le fromage blanc avec les zestes de citron. Salez, poivrez."]},{"titre":"A table !","items":["Sur la base de chaque pain, étalez la sauce. Garnissez avec les morceaux de truite et le confit d'oignon. Arrosez le tout d'un filet de jus de citron.","Au moment de passer à table, assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"14465","nom":"Kebab végétal sauce blanche au basilic, tomate et oignons frits","image":"images/14465.webp","ingredients":[["pain pita (180g)","2x"],["kebab végétal","160 g"],["fromage blanc","100 g"],["oignons frits (sachet)","0.5"],["sucrine (170g)","1x"],["échalote","0.5"],["tomate ronde (200g)","2x"],["huile d'olive au basilic","20 ml"]],"cuisine":["sel","poivre","2 cs huile d'olive","1 cs vinaigre de votre choix"],"etapes":[{"titre":"La préparation","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le kebab végétal 5 min environ. Salez, poivrez.","En parallèle, émincez l’échalote.","Coupez les tomates en demi-rondelles.","Coupez la base de la sucrine et émincez-la.","Dans un bol, mélangez le fromage blanc et l'huile au basilic. Salez, poivrez et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les kebabs","items":["Faites dorer les pains pita au grille-pain.","Ouvrez les pains pita et étalez la sauce au basilic.","Garnissez avec quelques feuilles de sucrine, des tomates, du kebab végétal et de l'échalote. Parsemez d'oignons frits."]},{"titre":"La salade","items":["Dans un saladier, versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ajoutez le reste de sucrine, des tomates et d'échalote. Mélangez bien."]}]},{"id":"14467","nom":"Kebab végétal sauce blanche au piment fumé","image":"images/14467.webp","ingredients":[["pain pita (180g)","2x"],["kebab végétal","160 g"],["fromage blanc","100 g"],["oignons frits (sachet)","0.5"],["carotte (120g)","1x"],["huile de tournesol infusée au piment fumé","20 ml"],["sucrine (170g)","1x"],["oignon rouge","0.25"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"La préparation","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir le kebab végétal 5 min environ. Salez, poivrez.","En parallèle, émincez l'oignon.","Épluchez et râpez la carotte.","Coupez la base de la sucrine et émincez-la.","Dans un bol, mélangez le fromage blanc et l'huile au piment fumé (attention, elle est forte, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût). Salez, mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les kebab","items":["Faites dorer les pains pita au grille-pain.","Une fois chauds, ouvrez les pains pita et étalez la sauce au piment fumé.","Garnissez avec quelques feuilles de sucrine, de la carotte, du kebab végétal et de l'oignon. Parsemez d'oignons frits."]},{"titre":"La salade","items":["Dans un saladier, versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ajoutez le reste de sucrine, de carotte et de l'oignon rouge pour obtenir une salade."]}]},{"id":"21934","nom":"Köttbullars (boulettes de boeuf à la suédoise) et coquillettes","image":"images/21934.webp","ingredients":[["sauce soja salée (15g)","15 ml"],["crème (100g)","100 g"],["gousse d'ail (6g)","1x"],["coquillettes demi-complètes (200g)","200 g"],["haché de bœuf (250g)","250 g"],["oignon jaune (110g)","1x"],["persil plat (5g)","qq brins"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les coquillettes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les coquillettes selon les indications du paquet.","Pendant la cuisson des pâtes, préparez les köttbullars."]},{"titre":"Les köttbullars","items":["Pressez ou hachez l'ail.","Émincez l'oignon.","Dans un saladier, émiettez les steaks hachés. Salez, poivrez et formez 3 à 4 boulettes par personne.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et les boulettes 5 à 7 min jusqu'à ce qu'elles soient cuites à coeur (la chair n'est plus rose). Retournez-les régulièrement.","Astuce : si nécessaire, utilisez une seconde sauteuse ou faites cuire vos boulettes en plusieurs fois pour qu'elles soient bien dorées et cuisent correctement.","En fin de cuisson, ajoutez l'ail, la sauce soja et la crème. Poursuivez la cuisson 5 min jusqu'à ce que la sauce soit nappante.","Effeuillez et ciselez le persil.","Au moment de servir, parsemez le tout de persil."]}]},{"id":"17757","nom":"Lieu noir au beurre blanc aux zestes de citron, poireau et riz","image":"images/17757.webp","ingredients":[["beurre d'Isigny","50 g"],["zestes de citron (sachet)","0.5"],["vin blanc du Vaucluse","50 ml"],["riz basmati","150 g"],["lieu noir","240 g"],["échalote","0.5"],["poireau (215g)","1x"]],"cuisine":["sel","poivre","huile d'olive","1 càc vinaigre (blanc ou de cidre)","1 càs eau"],"etapes":[{"titre":"Le poireau","items":["Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif. Faites revenir le poireau 20 min environ.","À mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson. Salez, poivrez.","Pendant ce temps, préparez le beurre blanc."]},{"titre":"Le beurre blanc","items":["Ciselez (dés) l'échalote.","Coupez le beurre en morceaux.","Dans une petite casserole, versez le vin blanc, le vinaigre et l'eau.","Ajoutez l'échalote et faites bouillir jusqu'à ce qu'il reste environ 1 cuillère à soupe de liquide.","Hors du feu, laissez tiédir la casserole 2 à 3 min : vous devez pouvoir passer la main en dessous sans vous brûler.","Lorsque la casserole est tiède, ajoutez le beurre petit à petit tout en fouettant vigoureusement.","Salez, poivrez.","Astuce : si votre beurre blanc se sépare (le gras remonte à la surface), ajoutez 1 càs d’eau froide et fouettez énergiquement pour le rattraper.","Ajoutez les zestes de citron mélangez bien puis goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant que la casserole tiédie, faits cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson blanc. Salez et poivrez-le.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poisson blanc 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur.","Astuce : pour vérifier la cuisson du poisson, piquez-le avec une fourchette. Si la chair se détache facilement, il est cuit. Sinon, couvrez-le et laissez cuire 1 à 2 minutes de plus.","Au moment de servir, nappez votre assiette de beurre blanc aux zestes de citron."]}]},{"id":"14524","nom":"Lieu noir et orzo au Roquefort","image":"images/14524.webp","ingredients":[["gousse d'ail (4g)","1x"],["Roquefort","50 g"],["pâtes orzo","200 g"],["échalote (25g)","1x"],["lieu noir","240 g"]],"cuisine":["sel","poivre","huile d'olive","600 ml eau"],"etapes":[{"titre":"L'orzo au Roquefort","items":["Ciselez (dés) l'échalote.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'orzo, l'ail et l'échalote 1 min pour les nacrer (enrober d'huile). Versez l'eau et couvrez. Faites cuire 10 à 15 min. Salez, poivrez. Remuez régulièrement.","Astuce : ajoutez de l'eau en cours de cuisson si nécessaire.","En parallèle, coupez le Roquefort en morceaux.","Une fois l'orzo cuit, ajoutez le Roquefort. Mélangez bien jusqu'à ce qu'il soit fondu.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, faites cuire le poisson."]},{"titre":"Le lieu noir","items":["Rincez et essuyez le lieu noir. Salez et poivrez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif. Faites revenir le lieu noir 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur."]}]},{"id":"16248","nom":"Lieu noir, chutney aigre-doux mangue et légumes rôtis","image":"images/16248.webp","ingredients":[["carotte (100g)","1x"],["pomme de terre (440g)","2x"],["herbes de Provence (sachet)","0.5"],["lieu noir","240 g"],["bulbe de fenouil (200g)","1x"],["mangue","0.5"]],"cuisine":["sel","poivre","huile d'olive","1 càs eau","huile de cuisson","20 ml vinaigre (blanc ou de cidre)"],"etapes":[{"titre":"Les légumes","items":["Préchauffez votre four à 200°C en chaleur tournante !","Pendant ce temps, coupez la base et les tiges à ras du bulbe de fenouil. Retirez la partie dure au centre et émincez le reste.","Épluchez et coupez la carotte et les pommes de terre en morceaux.","Déposez le tout sur une plaque allant au four et versez un filet d'huile d'olive. Salez, poivrez et parsemez d'herbes de Provence. Mélangez bien.","Enfournez 20 à 25 min.","Pendant ce temps, préparez le chutney."]},{"titre":"Le chutney","items":["Épluchez et coupez la mangue en petits dés.","Dans une petite casserole, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir la mangue 2 min. Au bout des 2 min, ajoutez le vinaigre et l'eau. Remuez régulièrement.","Laissez mijoter 15 à 20 min à couvert jusqu'à ce que le tout soit compoté. Salez légèrement, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, préparez le poisson."]},{"titre":"Le poisson","items":["Rincez et essuyez le poisson. Salez et poivrez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poisson 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur."]}]},{"id":"19356","nom":"Macaronis à l'effiloché de porc et sauce à la fourme d'Ambert","image":"images/19356.webp","ingredients":[["gousse d'ail","0.5"],["fourme d'Ambert AOP (lait pasteurisé)","60 g"],["crème","80 g"],["effiloché de porc","200 g"],["macaroni demi-complets","200 g"],["noix sèche","40 g"],["oignon jaune","0.5"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","0.5 cube bouillon de bœuf"],"etapes":[{"titre":"L'effiloché de porc","items":["Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'ail et l'oignon 5 min. Poivrez, ne salez pas le bouillon apporte déjà du sel.","Au bout des 5 min, ajoutez l'effiloché de porc, un fond d'eau et le bouillon de boeuf émietté. Poursuivez la cuisson 5 à 10 min.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant la cuisson du porc, faites cuire les pâtes."]},{"titre":"Les pâtes","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les pâtes selon les indications du paquet.","Réservez un petit bol d'eau de cuisson des pâtes pour détendre la sauce.","En parallèle, préparez la sauce."]},{"titre":"La sauce à la fourme d'Ambert","items":["Coupez la fourme d'Ambert en petits dés.","Dans une petite casserole, faites chauffer la crème et la fourme d'Ambert jusqu'à ce que le fromage fonde.","Réservez au chaud."]},{"titre":"A table !","items":["Ouvrez les noix et hachez-les grossièrement.","Effeuillez et ciselez le persil.","Une fois le tout cuit, ajoutez les pâtes, un peu d'eau de cuisson des pâtes et la sauce à la fourme d'Ambert dans la sauteuse. Mélangez bien.","Astuce : ajoutez un peu d’eau de cuisson des pâtes permet de lier la sauce et de la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez votre plat de noix et de persil."]}]},{"id":"17074","nom":"Macaronis alla norcina (sauce crémeuse au porc et graines de fenouil)","image":"images/17074.webp","ingredients":[["gousse d'ail (5g)","1x"],["vin blanc du Vaucluse","50 ml"],["crème","100 g"],["graines de fenouil (sachet)","0.5"],["parmigiano reggiano râpé","20 g"],["chair à saucisse Bleu Blanc Coeur","240 g"],["macaroni demi-complets","200 g"],["oignon jaune (125g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les macaronis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les macaronis selon les indications du paquet.","Réservez un peu d'eau de cuisson pour la suite de la recette.","Pendant ce temps, faites cuire la chair à saucisse."]},{"titre":"La chair à saucisse","items":["Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, la chair à saucisse et l'ail 5 min environ. Salez légèrement, poivrez.","Au bout des 5 min, déglacez (versez) avec le vin blanc.","Ajoutez les graines de fenouil et poursuivez la cuisson 5 min environ jusqu'à ce que le porc soit cuit (la chair n'est plus rose)."]},{"titre":"A table !","items":["Une fois le tout cuit, ajoutez les macaronis, 2 càs d'eau de cuisson par personne, la moitié du parmesan et la crème à la sauteuse.","Mélangez bien et faites chauffer 2 à 3 min à feu moyen.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez le reste de parmesan sur vos assiettes."]}]},{"id":"18544","nom":"Macaronis aux trois fromages et jambon de Paris","image":"images/18544.webp","ingredients":[["jambon de Paris (tranche) (110g)","2x"],["crème","100 g"],["emmental pasteurisé râpé français","50 g"],["parmigiano reggiano râpé","20 g"],["cheddar râpé","60 g"],["macaronis demi-complets","200 g"]],"cuisine":["sel","poivre"],"etapes":[{"titre":"Les macaronis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les macaronis selon les indications du paquet.","Pendant ce temps, coupez le jambon en morceaux."]},{"titre":"A table !","items":["Une fois les pâtes cuites, égouttez-les et réservez-les. Remettez la casserole vide sur feu moyen.","Versez la crème et ajoutez le cheddar, l’emmental et le parmesan.","Faites fondre les fromages 2 à 3 min à feu doux en remuant.","Une fois les fromages fondus, ajoutez les macaronis et le jambon. Salez, poivrez, mélangez bien.","Goûtez et rectifiez l’assaisonnement si besoin."]}]},{"id":"22130","nom":"Macaronis sauce gorgonzola et poitrine fumée","image":"images/22130.webp","ingredients":[["gorgonzola (75g)","75 g"],["crème (100g)","100 g"],["poitrine fumée (90g)","90 g"],["vin blanc du Vaucluse (40g)","40 ml"],["macaroni demi-complets (200g)","200 g"]],"cuisine":["sel","poivre"],"etapes":[{"titre":"Les macaronis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les macaronis selon les indications du paquet.","Pendant ce temps, préparez la poitrine fumée."]},{"titre":"La poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Faites chauffer une sauteuse sans matière grasse à feu vif.","Faites dorer la poitrine fumée 5 min jusqu'à ce qu'elle soit bien colorée. Remuez régulièrement.","Réservez-la sur une assiette et gardez la sauteuse pour la sauce."]},{"titre":"La sauce","items":["Coupez le gorgonzola en dés.","​​​​​​​Une fois les pâtes cuites, égouttez-les et conservez un bol d'eau de cuisson des pâtes pour la sauce.","Dans la même sauteuse, déglacez (versez) avec le vin blanc et grattez bien les sucs. Laissez réduire de moitié.","Ajoutez le gorgonzola et la crème.","Faites chauffer 2 à 5 min à feu doux jusqu'à ce que le fromage fonde et que la sauce soit homogène. Poivrez et ne salez pas, le gorgonzola et la poitrine fumée apportent déjà du sel. Mélangez bien.","Ajoutez les macaronis puis progressivement un peu d'eau de cuisson des pâtes. Mélangez jusqu'à obtenir une sauce nappante qui enrobe bien les pâtes.","​​​​​​​Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez de poitrine fumée."]}]},{"id":"17109","nom":"Mafé de poivron et haricots rouge aux cacahuètes et gingembre","image":"images/17109.webp","ingredients":[["purée de cacahuètes","40 g"],["concentré de tomates","25 g"],["riz basmati","150 g"],["haricots rouges conserve (g égoutté) (150g)","150x"],["tomate ronde (80g)","1x"],["gingembre","1 à 3 cm"],["poivron rouge bio (250g)","1x"],["échalote (25g)","1x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","200 ml eau","huile de cuisson"],"etapes":[{"titre":"Les légumes","items":["Émincez l'échalote.","Coupez le poivron en lanières.","Coupez la tomate en dés.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'échalote, le poivron et la tomate 5 min. Remuez régulièrement. Salez, poivrez et remuez régulièrement.","En parallèle, préparez le reste des ingrédients."]},{"titre":"Le mafé","items":["Égouttez et rincez les haricots rouges.","Dans un bol, déposez les ingrédients suivants :","Pelez et hachez le gingembre.","Ajoutez la purée de cacahuètes et le concentré de tomates. Mélangez bien.","Au bout des 5 min de cuisson des légumes, ajoutez la préparation à la cacahuète et l'eau.","Mélangez jusqu'à obtenir une sauce homogène.","Ajoutez les haricots rouges et poursuivez la cuisson 10 à 15 min à feu moyen.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Effeuillez et ciselez le persil. Parsemez-le sur le mafé au moment de servir."]}]},{"id":"19904","nom":"Merguez végétales et courgette au parmesan","image":"images/19904.webp","ingredients":[["merguez 100% végétal (200g)","4x"],["origan (sachet) (1g)","0.25"],["fromage blanc (50g)","50 g"],["gousse d'ail (6g)","1x"],["parmigiano reggiano râpé (20g)","20 g"],["graines de couscous (150g)","150 g"],["courgette (200g)","1x"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile d'olive","200 ml eau"],"etapes":[{"titre":"La courgette au parmesan","items":["Émincez l'oignon.","Coupez la courgette en rondelles.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez la courgette, l'ail et l'origan.","Poursuivez la cuisson 10 min environ. Salez, poivrez. Remuez régulièrement.","En fin de cuisson, hors du feu, ajoutez le parmesan et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les merguez végétales."]},{"titre":"Les merguez végétales","items":["Faites chauffer une poêle sans matière grasse à feu moyen.","Faites cuire les merguez 10 à 15 min. Retournez-les régulièrement pour une coloration uniforme.","Pendant ce temps, préparez les graines de couscous et la sauce."]},{"titre":"Les graines de couscous et la sauce","items":["Portez à ébullition l'eau et déposez les graines de couscous dans un récipient.","Versez l'eau sur les graines de couscous. Couvrez et laissez gonfler 5 min.","Ajoutez un filet d'huile d'olive. Salez, poivrez et à l'aide d'une fourchette, égrainez-les (séparez les grains).","Dans un bol, mélangez le fromage blanc avec un filet d'huile d'olive. Salez, poivrez.","Dégustez les merguez avec la sauce au fromage blanc."]}]},{"id":"19259","nom":"Mezzalunas aux 4 fromages, choux de Bruxelles et crème à la truffe","image":"images/19259.webp","ingredients":[["mezzaluna 4 fromages","250 g"],["parmigiano reggiano râpé","20 g"],["assaisonnement à la truffe d'été (pincée) (0.4g)","2x"],["crème","150 g"],["choux de Bruxelles","200 g"],["oignon jaune (100g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon.","Coupez la base des choux de Bruxelles et coupez-les en 2 ou 4 s'ils sont un peu gros.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et les choux de Bruxelles 15 à 20 min. Salez, poivrez.","À mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson.","En parallèle, faites cuire les mezzalunas."]},{"titre":"Les mezzalunas aux 4 fromages","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les mezzalunas selon les indications du paquet.","Une fois les mezzalunas cuits, ajoutez-les à la sauteuse avec la crème. Faites cuire 1 à 2 min jusqu'à ce que la crème réduise et enrobe les pâtes.","Ajoutez l'assaisonnement à la truffe et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez votre assiette de parmesan."]}]},{"id":"15937","nom":"Mezzalunas ricotta cèpes, poitrine fumée, épinards et crème persillée","image":"images/15937.webp","ingredients":[["poitrine fumée","90 g"],["fromage blanc","100 g"],["oignon jaune","0.5"],["mezzaluna ricotta cèpes","250 g"],["gousse d'ail","0.5"],["pousses d'épinards","200 g"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes et la poitrine fumée","items":["Émincez l'oignon.","Coupez la poitrine fumée en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et la poitrine fumée 10 min environ.","Au bout des 10 min, ajoutez les pousses d'épinards et poursuivez la cuisson 5 min.","En parallèle, faites cuire les mezzalunas."]},{"titre":"Les mezzalunas ricotta cèpes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les mezzalunas selon les indications du paquet.","Une fois cuits, mélangez-les avec les légumes et la poitrine fumée."]},{"titre":"La crème persillée","items":["Pressez ou hachez l'ail.","Effeuillez et ciselez le persil.","Dans un bol, mélangez le fromage blanc, l'ail et le persil. Salez, poivrez.","Nappez la crème persillée sur les mezzalunas."]}]},{"id":"16815","nom":"Mezzalunas ricotta cèpes, portobello et fromage double crème","image":"images/16815.webp","ingredients":[["mezzalunas ricotta cèpes","250 g"],["fromage à tartiner double crème nature","60 g"],["gousse d'ail (6g)","1x"],["champignon Portobello","180 g"],["courgette (200g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes","items":["Coupez la courgette en demi-rondelles.","Coupez les champignons Portobello en fines tranches.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir la courgette, les Portobello et l'ail 15 min environ. Salez, poivrez."]},{"titre":"Les mezzalunas ricotta cèpes","items":["Portez une casserole d'eau salée à ébullition.","Faites cuire les mezzalunas selon les indications du paquet.","Une fois cuits, ajoutez les mezzalunas et le fromage à tartiner dans la sauteuse et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"18011","nom":"Mijoté de haricots blancs, champignons et épinards au lait de coco","image":"images/18011.webp","ingredients":[["champignons de Paris blancs","250 g"],["gousse d'ail","0.5"],["lait de coco","200 ml"],["haricots blancs conserve","150 g égoutté"],["riz basmati","150 g"],["paprika fumé (sachet)","0.5"],["herbes de Provence (sachet)","0.25"],["pousses d'épinards","100 g"],["oignon jaune (110g)","1x"]],"cuisine":["huile d'olive","sel","poivre"],"etapes":[{"titre":"Le mijoté","items":["Coupez les champignons en 2 ou en 4 s'ils sont trop gros.","Émincez l'oignon.","Pressez ou hachez l'ail.","Egouttez et rincez les haricots blancs.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, l'ail, les champignons et le paprika fumé 5 min. Salez, poivrez.","Astuce : Ne remuez pas les légumes immédiatement après les avoir déposés dans la poêle, laissez-les caraméliser quelques minutes pour obtenir une belle couleur dorée.","Ajoutez les haricots blancs, le lait de coco et les herbes de Provence et poursuivez la cuisson 5 min.","Ajoutez les épinards et laissez cuire 2 à 3 min environ. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet."]}]},{"id":"17316","nom":"Mijoté pimenté de saucisses à la sauce tomate, ail et gingembre","image":"images/17316.webp","ingredients":[["huile pimentée","10 ml"],["paprika (sachet)","0.5"],["pulpe de tomate fine","400 g"],["gousse d'ail","0.5"],["saucisse nature (240g) Bleu Blanc Coeur","2x"],["riz basmati","150 g"],["gingembre","1 à 3 cm"],["oignon jaune (125g)","1x"]],"cuisine":["sel","poivre","huile de cuisson","200 ml eau"],"etapes":[{"titre":"Le mijoté de saucisses","items":["Émincez l’oignon.","Coupez les saucisses en rondelles.","Dans une cocotte, faites chauffer un filet d’huile de cuisson à feu moyen à vif.","Faites revenir l'oignon et les saucisses 10 min environ en remuant régulièrement. Salez, poivrez.","Pendant ce temps, pelez et hachez l'ail et le gingembre.","Au bout des 10 min de cuisson, ajoutez l’ail, le gingembre, la pulpe de tomates, le paprika et l'eau. Couvrez et poursuivez la cuisson 10 min supplémentaires.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Au moment de servir, arrosez votre mijoté de saucisses d'un filet d'huile pimentée.","Astuce : l'huile pimentée est forte, ajoutez-en une petite quantité pour commencer et ajustez selon votre goût."]}]},{"id":"16846","nom":"Mujaddara à la féta (riz à la libanaise), oignon caramélisé et salade","image":"images/16846.webp","ingredients":[["féta","80 g"],["riz basmati","150 g"],["fromage blanc","100 g"],["pomme (105g)","1x"],["lentilles en conserve (g égoutté) (200g)","200x"],["oignon jaune (110g)","1x"],["coriandre","qq brins"],["carotte (100g)","1x"],["sucrine (170g)","1x"],["cumin (sachet)","0.5"]],"cuisine":["sel","poivre","huile d'olive","1 càs sucre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"La mujaddara","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Rincez et égouttez les lentilles.","Une fois le riz cuit, égouttez-le et mélangez-le avec les lentilles et le cumin. Salez, poivrez.","Pendant ce temps, préparez l'oignon caramélisé."]},{"titre":"L'oignon caramélisé","items":["Émincez l'oignon.","Dans une sauteuse, faites chauffer un filet d’huile d’olive à feu moyen à vif.","Faites revenir l'oignon et le sucre 10 à 12 min jusqu'à ce qu'il soit caramélisé. Remuez régulièrement.","En parallèle, préparez la salade et la sauce."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Coupez la pomme en fins quartiers.","Épluchez et râpez la carotte.","Coupez la base de la sucrine et émincez-la. Mélangez bien."]},{"titre":"A table !","items":["Salez, poivrez le fromage blanc et ajoutez un filet d'huile d'olive.","Émiettez la féta.","Ciselez la coriandre (en entier, les tiges se consomment).","Parsemez la mujaddara de féta, d'oignon caramélisé et de coriandre. Nappez de sauce et accompagnez de la salade."]}]},{"id":"22039","nom":"Nouilles au poulet, choux de Bruxelles et sauce teriyaki","image":"images/22039.webp","ingredients":[["nouilles asiatiques (120g)","120 g"],["sauce teriyaki (24g)","20 ml"],["choux de Bruxelles (200g)","200 g"],["gingembre (20g)","1 à 3 cm"],["oignon jaune (90g)","1x"],["champignon shimeji (150g)","150 g"],["emincés de cuisse de poulet (225g)","225 g"]],"cuisine":["sel","poivre","huile de cuisson (mélange 4 huiles par exemple)"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon.","Retirez la base des choux de Bruxelles et coupez-les en 2 ou en 4 s'ils sont un peu gros.","Épluchez et hachez le gingembre.","Coupez la base des shimejis et séparez-les si nécessaire.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir le poulet 5 min pour le dorer. Salez, poivrez. Réservez-le.","Faites revenir l'oignon, les choux de Bruxelles, les shimejis et le gingembre 10 min.","Baissez sur feu moyen, ajoutez un fond d'eau et le poulet. Couvrez et prolongez la cuisson 5 min jusqu'à ce que le poulet soit cuit à coeur (la chair n'est plus rose) et les légumes cuits. Salez, poivrez.","Une fois le tout cuit, s'il reste beaucoup d'eau mettez sur feu vif quelques secondes pour évaporer l'eau restante.","En parallèle, faites cuire les nouilles."]},{"titre":"Les nouilles","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les nouilles selon les indications du paquet.","Une fois cuites, égouttez-les et passez-les sous l’eau froide pour stopper leur cuisson.","Une fois le tout cuit, ajoutez les nouilles et la sauce teriyaki dans la sauteuse. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17945","nom":"Nouilles pimentées au boeuf haché, gingembre et cacahuètes","image":"images/17945.webp","ingredients":[["sauce soja salée","40 ml"],["oignon jaune (110g)","1x"],["gousse d'ail (6g)","1x"],["gingembre","1 à 3 cm"],["nouilles asiatiques","120 g"],["steak haché façon bouchère","250 g"],["piment oiseau (2g)","1x"],["sauce soja sucrée","20 ml"],["cébette (16g)","1x"],["cacahuètes grillées","25 g"]],"cuisine":["sel","poivre","huile de cuisson (mélange 4 huiles par exemple)","50 ml eau"],"etapes":[{"titre":"Le boeuf haché au gingembre","items":["Pelez et hachez l'ail et le gingembre.","Ciselez (dés) l'oignon.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon, l'ail, le gingembre, le piment et le steak haché émietté 5 min.","Au bout des 5 min, ajoutez l'eau, la sauce soja salée et sucrée et prolongez la cuisson 5 min environ.","En parallèle, faites cuire les nouilles."]},{"titre":"Les nouilles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet.","En parallèle, émincez la cébette.","Hachez les cacahuètes.","Une fois le boeuf cuit, ajoutez les nouilles dans la sauteuse et mélangez bien pour enrober le tout. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez la cébette et les cacahuètes sur l'ensemble du plat."]}]},{"id":"16140","nom":"Nuggets végétaux au caramel et chou pak choy","image":"images/16140.webp","ingredients":[["sauce soja salée","20 ml"],["nuoc mam (sauce poisson)","15 ml"],["sésame doré","10 g"],["riz basmati","150 g"],["nuggets végétaux","180 g"],["oignon jaune","0.5"],["coriandre","qq brins"],["chou pak choy (300g)","1x"]],"cuisine":["sel","poivre","huile de cuisson","2 càs sucre","2 càs eau"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, faites cuire les légumes."]},{"titre":"Les légumes","items":["Coupez la base du chou pak choy et émincez-le.","Émincez l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon et le chou pak choy 8 à 10 min jusqu'à ce qu'ils soient légèrement croquants (ou tendres selon votre goût). Poivrez.","A mi-cuisson, ajoutez un fond d’eau et couvrez pour accélérer la cuisson. Salez et poivrez. Remuez régulièrement.","En parallèle, préparez les nuggets."]},{"titre":"Les nuggets","items":["Dans une seconde sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites dorer les nuggets 2 à 3 min de chaque côté puis réservez-les dans une assiette.","Dans la même sauteuse, versez le sucre et l'eau et faites chauffer à feu moyen à vif 3 min jusqu'à ce que le sucre soit dissout et que le mélange brunisse. Surveillez bien et ne mélangez pas (ou sinon à la spatule en bois).","Une fois le caramel formé, ajoutez les nuggets, la sauce soja et la sauce nuoc mam. Poursuivez la cuisson 5 min environ. Remuez régulièrement pour enrober les nuggets. Poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Ciselez la coriandre (en entier, les tiges se consomment) et parsemez-le ainsi que le sésame doré sur l'ensemble de la recette."]}]},{"id":"15687","nom":"One pot de farfallines à la truite fumée, fèves et pesto de basilic et amandes","image":"images/15687.webp","ingredients":[["truite fumée","100 g"],["amandes crues","50 g"],["basilic (botte)","0.5"],["parmigiano reggiano râpé","20 g"],["oignon jaune (125g)","1x"],["gousse d'ail (5g)","1x"],["farfalline","200 g"],["fèves fraîches avec cosses","300 g"]],"cuisine":["eau","0.5 bouillon de légumes","3 huile d'olive (càs)","1 eau (càs) (pesto)","500 ml eau (ml) (farfallines)","sel","poivre"],"etapes":[{"titre":"La préparation","items":["Ciselez (dés) l'oignon.","Ecossez les fèves.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 3 min.","Au bout des 3 min, ajoutez les farfallines et mélangez bien pour les nacrer (les enrober d'huile).","Ajoutez l'eau, les fèves le bouillon et poursuivez la cuisson 10 min à feu doux.","Pendant ce temps, préparez le pesto."]},{"titre":"Le pesto","items":["Dans le bol d'un mixeur, déposez les ingrédients suivants :","Concassez grossièrement les amandes.","Pelez l'ail.","Effeuillez le basilic.","Ajoutez le parmesan, l'eau, l'huile d'olive et mixez jusqu'à obtenir une texture lisse et homogène. Salez, poivrez.","Suggestion : pour une texture plus liquide, ajoutez un peu d'eau.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le one pot","items":["Coupez la truite fumée en petits morceaux.","Au bout des 10 min de cuisson des pâtes, ajoutez un peu d'eau si elles ne vous semblent pas encore cuites, et prolongez la cuisson.","Ajoutez le pesto à la sauteuse et mélangez bien."]}]},{"id":"15659","nom":"One pot mexicain piquant au chorizo, riz et cheddar","image":"images/15659.webp","ingredients":[["riz basmati","150 g"],["carotte orange (200g)","2x"],["gousse d'ail (5g)","1x"],["cébette (16g)","1x"],["chorizo piquant tranché","80 g"],["mélange tex mex (sachet)","0.5"],["fromage blanc","100 g"],["citron vert","0.5"],["cheddar râpé","60 g"]],"cuisine":["sel","poivre","huile d'olive","0.5 bouillon de poule (cube)","500 ml eau"],"etapes":[{"titre":"Le one pot","items":["Epluchez et coupez les carottes en petits dés.","Pressez ou hachez l'ail.","Coupez les tranches de chorizo en morceaux.","Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les carottes, l'ail et le chorizo 5 min pour les dorer.","Au bout des 5 min, ajoutez le riz et faites-le revenir 3 min pour le nacrer (l'enrober d'huile).","Ensuite, ajoutez les épices tex-mex, l'eau et le bouillon de poule.","Faites cuire à petits bouillons 15 à 20 min jusqu'à ce que le riz soit cuit et que l'eau soit évaporée. Remuez régulièrement.","En parallèle, préparez le reste des ingrédients."]},{"titre":"La sauce","items":["À l'aide d’une râpe, prélevez des zestes de citron (uniquement l’écorce de couleur) et coupez-le en quartiers.","Mélangez les zestes avec le fromage blanc. Salez, poivrez.","Retirez la base de la cébette et émincez-la."]},{"titre":"A table !","items":["Déposez le riz dans des assiettes creuses, parsemez de cheddar et de cébette.","Nappez le tout de sauce au fromage blanc et arrosez d'un filet de jus de citron."]}]},{"id":"17612","nom":"One pot orzo, poulet et épinard","image":"images/17612.webp","ingredients":[["gousse d'ail (6g)","1x"],["parmigiano reggiano râpé","20 g"],["pâtes orzo","200 g"],["haut de cuisse de poulet","225 g"],["fromage à tartiner ail et fines herbes","60 g"],["amandes effilées","10 g"],["herbes de Provence (sachet)","0.25"],["pousses d'épinards","200 g"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile d'olive","0.5 cube bouillon de légumes","500 ml eau","beurre"],"etapes":[{"titre":"Les amandes effilées","items":["Faites chauffer une sauteuse à feu moyen sans matière grasse.","Faites torréfier les amandes 2 à 3 min jusqu'à ce qu'elles soient dorées.","Astuce : remuez régulièrement les amandes pour qu'elles ne brûlent pas.","Débarrassez-les et réservez la sauteuse."]},{"titre":"Le one pot","items":["Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Coupez le poulet en morceaux.","Dans la sauteuse, faites chauffer une noix de beurre et un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poulet 2 min environ pour le colorer et réservez-le dans une assiette.","Faites revenir l'oignon et l'ail 1 min environ. Ajoutez l'orzo, le poulet et les herbes de Provence. Faites-le revenir 3 min pour le nacrer (l'enrober d'huile). Ajoutez l'eau et le bouillon de légumes émietté. Salez légèrement et poivrez.","Faites cuire à petits bouillons 12 à 15 min. Remuez régulièrement.","Astuce : ajoutez de l'eau en cours de cuisson si nécessaire.","Quand il reste 5 min de cuisson, ajoutez les pousses d'épinard.","En fin de cuisson, ajoutez le fromage à tartiner, le parmesan et mélangez bien pour enrober le tout.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez le tout d'amandes."]}]},{"id":"18694","nom":"One pot pasta au poulet, champignons de Paris et pruneaux à l'orientale","image":"images/18694.webp","ingredients":[["haut de cuisse de poulet","225 g"],["champignons de Paris blancs","250 g"],["gousse d'ail (4g)","1x"],["ras el-hanout (sachet)","0.5"],["amandes effilées","15 g"],["pâtes perlées","200 g"],["pruneau","60 g"],["oignon jaune","0.5"],["coriandre","qq brins"]],"cuisine":["sel","poivre","huile d'olive","0.5 cube bouillon de poule","500 ml eau"],"etapes":[{"titre":"La préparation","items":["Coupez les hauts de cuisse en petits morceaux.","Coupez les champignons en tranches.","Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Coupez les pruneaux en dés."]},{"titre":"Le one pot","items":["Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, l'ail et les hauts de cuisse 5 min pour les colorer.","Au bout des 5 min, ajoutez les champignons, les pruneaux, les pâtes perlées, le ras el-hanout, l'eau et le bouillon de poule émietté. Mélangez bien. Salez, poivrez.","Faites cuire 12 à 15 min à petits bouillons à couvert. Remuez régulièrement.","Astuce : s'il reste trop d'eau dans la cocotte, retirez le couvercle et poursuivez la cuisson à feu vif quelques minutes.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"A table !","items":["Faites chauffer une poêle sans matière grasse. Faites revenir les amandes effilées 5 min. Remuez régulièrement.","En parallèle, ciselez la coriandre (en entier, les tiges se consomment).","Au moment de servir, parsemez votre plat avec la coriandre et les amandes effilées."]}]},{"id":"15825","nom":"Orzo à la sauce tomate aux épinards et crème de féta à l'ail des ours","image":"images/15825.webp","ingredients":[["oignon jaune (125g)","1x"],["gousse d'ail (5g)","1x"],["pulpe de tomates","400 g"],["crème de féta à l'ail des ours","90 g"],["pousses d'épinards","100 g"],["amandes crues","25 g"],["céleri branche (50g)","1x"],["pâtes orzo","200 g"]],"cuisine":["huile d'olive","sel","poivre"],"etapes":[{"titre":"La sauce tomate","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Retirez la base abîmée du céleri branche et émincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'ail, le céleri branche et l'oignon 5 min.","Au bout des 5 min, ajoutez la pulpe de tomates et les pousses d'épinards. Poursuivez la cuisson 10 min. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire l'orzo."]},{"titre":"L'orzo","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire l'orzo selon les indications du paquet.","Une fois le tout cuit, ajoutez l'orzo dans la sauteuse de la sauce et mélangez bien.","Hachez les amandes.","Servez l'orzo tomaté avec la crème de féta à l'ail des ours et parsemé d'amandes."]}]},{"id":"19391","nom":"Orzo citronné au saumon fumé et choux de Bruxelles","image":"images/19391.webp","ingredients":[["saumon fumé","100 g"],["gousse d'ail","0.5"],["pâtes orzo","200 g"],["citron jaune","0.5"],["choux de Bruxelles","300 g"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","2 càs eau de cuisson"],"etapes":[{"titre":"L'orzo et les choux de Bruxelles","items":["Portez à ébullition une casserole d’eau salée.","En parallèle, coupez les choux de Bruxelles en 2.","Faites cuire l'orzo et les choux de Bruxelles dans l'eau bouillante selon le temps indiqué sur le paquet d'orzo.","Une fois cuits, égouttez le tout et gardez un bol d'eau de cuisson."]},{"titre":"A table !","items":["Pressez ou hachez l'ail.","Coupez le saumon fumé en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l’ail, l'orzo et les choux de Bruxelles cuits et l'eau de cuisson 1 min environ. Poivrez.","Hors du feu, ajoutez le saumon fumé et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Effeuillez et ciselez le persil.","Coupez le citron en quartiers.","Arrosez votre assiette d'un filet de jus de citron et parsemez de persil."]}]},{"id":"15226","nom":"Orzotto tomaté aux épinards, parmesan et pignons de pin","image":"images/15226.webp","ingredients":[["pâtes orzo","200 g"],["concentré de tomates","35 g"],["pousses d'épinards","200 g"],["oignon jaune (125g)","1x"],["gousse d'ail (4g)","1x"],["parmigiano reggiano râpé","20 g"],["pignon de pin","25 g"],["origan séché","0.25"]],"cuisine":["400 ml eau","sel","poivre","huile de cuisson","0.5 cube bouillon de légumes"],"etapes":[{"titre":"L'orzotto","items":["Ciselez (dés) l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon 2 min environ.","Pressez ou hachez l'ail.","Ajoutez le concentré de tomates, l'ail, le bouillon de légumes, l'origan, l'orzo et l'eau.","Mélangez bien et poursuivez la cuisson 15 min environ à feu doux.","Remuez régulièrement. Salez, poivrez.","Au bout des 15 min de cuisson, si l'orzo n'est pas cuit, ajoutez un peu d'eau et prolongez la cuisson.","Pendant ce temps, préparez les épinards."]},{"titre":"Les épinards et pignons de pin","items":["Dans une seconde sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les épinards 5 min environ. Salez, poivrez.","En parallèle, faites chauffer une petite poêle sans matière grasse.","Faites dorer les pignons 1 à 2 min en remuant régulièrement.","Une fois l'orzotto cuit, ajoutez les épinards et la moitié du parmesan.","Mélangez bien, goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez des pignons de pin et du reste de parmesan."]}]},{"id":"17403","nom":"Pad thaï végétarien aux haricots verts et poivron","image":"images/17403.webp","ingredients":[["sirop d'érable","20 ml"],["sauce soja salée","40 ml"],["carotte (100g)","1x"],["sauce hoisin","10 ml"],["gousse d'ail","0.5"],["cacahuètes grillées sans sel","25 g"],["coriandre","qq brins"],["poivron vert (150g)","1x"],["cébette","0.5"],["citron vert","0.5"],["piment oiseau (2g)","1x"],["nouilles asiatiques","120 g"],["haricots verts","200 g"]],"cuisine":["huile de cuisson","poivre","sel"],"etapes":[{"titre":"Les légumes","items":["Épluchez et réalisez des tagliatelles de carotte à l'aide d'un économe.","Émincez la cébette et réservez la tige pour le dressage.","Coupez le poivron en fines lanières.","Équeutez les haricots verts et coupez-les en 2.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Pressez ou hachez l'ail."]},{"titre":"La cuisson des légumes","items":["Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir la cébette, l'ail et le piment pendant 1 min.","Ajoutez les haricots verts, le poivron et la carotte. Poursuivez la cuisson 7 à 9 min (les légumes doivent rester croquants). Salez légèrement, poivrez.","Pendant la cuisson des légumes, faites cuire les nouilles."]},{"titre":"Les nouilles asiatiques","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet.","Égouttez-les et passez-les sous l'eau froide pour stopper la cuisson.","En parallèle, préparez le reste des ingrédients."]},{"titre":"Le pad thaï","items":["Dans un bol, mélangez la sauce soja, le sirop d'érable et la sauce hoisin.","Coupez le citron en quartiers.","Ciselez la coriandre (en entier, les tiges se consomment).","Hachez grossièrement les cacahuètes.","Une fois les légumes cuits, ajoutez les nouilles et la sauce.","Mélangez bien et poursuivez la cuisson 1 min pour réchauffer le tout.","Au moment de servir, arrosez votre plat d'un filet de jus de citron.","Parsemez de cacahuètes, de cébette et de coriandre."]}]},{"id":"22114","nom":"Palak falafels (mijoté indien aux épinards)","image":"images/22114.webp","ingredients":[["crème (200g)","200 g"],["gousse d'ail (12g)","2x"],["falafels de lentille corail, lait de coco et curry (400g)","400 g"],["amandes effilées (25g)","25 g"],["concentré de tomates (40g)","40 g"],["cumin (sachet) (8g)","1x"],["riz concassé du Pendjab (300g)","300 g"],["gingembre (20g)","1 à 3 cm"],["pousses d'épinards (400g)","400 g"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant la cuisson du riz, préparez les épinards."]},{"titre":"Les épinards","items":["Faites chauffer une sauteuse à feu moyen sans matière grasse.","Faites torréfier les amandes 1 à 2 min jusqu'à ce qu'elles soient dorées. Remuez régulièrement.","Débarrassez les amandes puis conservez la sauteuse pour la suite.","Pelez et hachez l'ail et le gingembre.","Dans la sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'ail, le gingembre, les pousses d'épinards et le cumin 5 min. Salez, poivrez.","Ajoutez le concentré de tomates et la crème. Mélangez bien et laissez mijoter 1 à 2 min.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les falafels."]},{"titre":"Les falafels","items":["Dans une seconde sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir les falafels 5 min environ. Remuez régulièrement.","Répartissez les falafels sur le mijoté, parsemez d'amandes et accompagnez de riz.","Astuce : ajoutez les falafels sur le mijoté au dernier moment pour garder leur croustillant."]}]},{"id":"17002","nom":"Panzanella aux coeurs d'artichauts, féta AOP et fenouil","image":"images/17002.webp","ingredients":[["petits pains (160g)","2x"],["tomate (105g)","1x"],["bulbe de fenouil (180g)","1x"],["roquette","50 g"],["féta","70 g"],["cœurs d'artichauts","80 g"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"Les croûtons","items":["Coupez les petits pains en dés.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites dorer les petits pains 5 min environ jusqu'à ce que les croûtons soient dorés. Salez, poivrez.","En parallèle, réalisez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Versez l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Coupez la tomate en fins quartiers.","Émiettez la féta.","Retirez les tiges du fenouil et émincez le bulbe.","Coupez les artichauts en morceaux.","Ajoutez les croûtons et la roquette.","Goûtez et rectifiez l’assaisonnement si nécessaire."]}]},{"id":"17957","nom":"Panzanella aux figues rôties, burrata et noisettes","image":"images/17957.webp","ingredients":[["petit pain graines de courge (160g)","2x"],["figue (140g)","4x"],["noisettes décortiquées","25 g"],["roquette","50 g"],["tomate (100g)","1x"],["oignon rouge","0.25"],["burrata (100g)","1x"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix","huile d'olive"],"etapes":[{"titre":"Les croûtons","items":["Coupez les petits pains en dés.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les dés de pain 5 à 7 min jusqu'à ce qu'ils soient dorés. Salez, poivrez.","Réservez-les dans un autre récipient et conservez la sauteuse."]},{"titre":"Les figues rôties","items":["Coupez les figues en 4 ou 6 si elles sont trop grosses.","Dans la même sauteuse que les croûtons, faites de nouveau chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les figues 5 à 10 min jusqu'à ce qu'elles soient dorées.","En parallèle, préparez la panzanella."]},{"titre":"La panzanella","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'oignon rouge.","Versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Coupez la tomate en dés.","Hachez grossièrement les noisettes.","Ajoutez la roquette, les figues rôties et les croûtons. Mélangez bien.","Déchirez la burrata et répartissez les morceaux sur chaque assiette."]}]},{"id":"22025","nom":"Panzerottis (ricotta, citron, épinards) à la sauce tomate et chipolatas","image":"images/22025.webp","ingredients":[["Panzerottis ricotta épinard et citron (200g)","200 g"],["pulpe de tomates (210g)","210 g"],["gousse d'ail (6g)","1x"],["oignon jaune (90g)","1x"],["salade (50g)","50 g"],["chipolata nature (240g) Bleu Blanc Coeur","4x"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","100 ml eau"],"etapes":[{"titre":"La sauce tomate","items":["Pressez ou hachez l'ail.","Ciselez (dés) l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et l'ail 5 min.","Ajoutez la pulpe de tomate et l'eau. Salez, poivrez.","Laissez mijoter à couvert pendant 10 min environ.","Astuce : si la sauce réduit trop vite, ajoutez un petit filet d'eau.","Goûtez et ajoutez une pincée de sel si nécessaire.","En parallèle, faites cuire les chipolatas."]},{"titre":"Les chipolatas","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les chipolatas 10 min environ en les retournant régulièrement jusqu'à ce qu'elles soient bien dorées et cuites à cœur.","Pendant ce temps, faites cuire les panzerottis."]},{"titre":"Les panzerottis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les panzerottis selon les indications du paquet.","Lorsqu'ils sont cuits, égouttez-les puis ajoutez-les à la sauteuse de la sauce tomate. Mélangez pour bien tout enrober.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"15450","nom":"Parmentier d'effiloché de porc à la courge butternut et crème de parmesan","image":"images/15450.webp","ingredients":[["effiloché de porc","200 g"],["gousse d'ail (6g)","1x"],["parmigiano reggiano râpé","20 g"],["crème","100 g"],["courge butternut","500 g"],["oignon jaune (130g)","1x"],["multifeuille","50 g"]],"cuisine":["sel","poivre","vinaigre de votre choix","lait","beurre","0.5 bouillon de poule (cube)","huile d'olive"],"etapes":[{"titre":"La purée de butternut","items":["Épluchez et coupez le butternut en deux. Retirez les graines à l'aide d'une cuillère. Coupez-le en tranches puis taillez celles-ci en morceaux.","Dans une casserole, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir la courge 5 min.","Ajoutez le bouillon de poule et de l'eau à mi-hauteur.","Faites cuire à feu moyen 20 à 25 min à couvert.","Une fois la courge cuite, mixez-la ou réduisez-la en purée. Ajoutez un filet de lait et une noix de beurre pour une purée plus onctueuse. Salez, poivrez.","Pendant ce temps, préparez l'effiloché de porc et la crème de parmesan."]},{"titre":"L'effiloché de porc","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 10 min environ. Remuez régulièrement.","Au bout des 10 min de cuisson, ajoutez l'effiloché de porc, l'ail et poursuivez la cuisson 5 min supplémentaires. Remuez régulièrement. Salez, poivrez.","Pendant ce temps, préparez la crème de parmesan."]},{"titre":"La crème de parmesan","items":["Dans une petite casserole, faites chauffer la crème et le parmesan 3 à 5 min à feu doux.","Remuez régulièrement. Poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le parmentier","items":["Une fois le tout cuit, déposez l'effiloché de porc au confit d'oignon dans un plat à gratin et répartissez par-dessus la purée de butternut..","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]},{"titre":"","items":["Servez sans attendre le parmentier d'effiloché de porc à la courge butternut nappé de crème de parmesan ! Accompagnez-le de la salade."]}]},{"id":"16878","nom":"Pavé de rumsteak alla tagliata et crème de champignons","image":"images/16878.webp","ingredients":[["pavé de rumsteak (240g)","2x"],["gousse d'ail","0.5"],["champignons de Paris blancs","250 g"],["crème","100 g"],["penne demi-complètes","200 g"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile d'olive","1 càc moutarde","200 ml eau","0.25 cube bouillon de légumes","beurre"],"etapes":[{"titre":"Les pennes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Pendant ce temps, préparez la sauce."]},{"titre":"La sauce","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Coupez les champignons en tranches.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, les champignons et l'ail 5 min. Salez, poivrez.","Au bout des 5 min, ajoutez l'eau et le bouillon de légumes. Portez à ébullition et faites réduire 5 à 10 min.","Ajoutez la crème et la moutarde et poursuivez la cuisson 3 à 5 min jusqu'à ce que la sauce soit nappante.","Astuce : Pour vérifier la consistance de la sauce, trempez une cuillère à soupe dedans et passez votre doigt dessus. La sauce est prête quand il laisse une trace nette.","Déposez le tout dans le bol d'un mixeur.","Mixez la sauce jusqu'à obtenir une texture lisse et homogène.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire la viande."]},{"titre":"Les pavés de rumsteak","items":["Dans une poêle, faites chauffer un filet d’huile d'olive et une noix de beurre à feu moyen à vif.","Faites cuire les pavés de rumsteak 2 à 3 min de chaque côté selon la cuisson souhaitée. Salez, poivrez.","Coupez les pavés de rumsteak en fines tranches (2 cm ou moins).","Nappez la viande avec la crème de champignons."]}]},{"id":"7463","nom":"Pavé de saumon laqué à la clémentine et à l'érable","image":"images/7463.webp","ingredients":[["clémentine (80g)","1x"],["pomme de terre (400g)","2x"],["sirop d'érable","10 ml"],["pavés de saumon (240g)","2x"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Les pommes de terre","items":["Épluchez et coupez les pommes de terre en dés.","Dans une sauteuse, faites chauffer un filet d’huile de cuisson à feu vif.","Faites revenir les dés de pommes de terre 5 min pour les colorer légèrement.","Baissez sur feu moyen, couvrez et poursuivez la cuisson 15 min, en remuant régulièrement, jusqu’à ce qu’ils soient tendres. Salez, poivrez.","En parallèle, préparez le saumon."]},{"titre":"Le saumon","items":["Rincez et essuyez les pavés de saumon. Salez et poivrez-les.","Émincez l'oignon.","Épluchez et découpez la clémentine en quartiers.","Dans une seconde sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'oignon 10 min environ.","Ajoutez les clémentines et les pavés de saumon. Faites dorer les pavés, côté peau en premier, 2 à 3 min de chaque côté jusqu'à ce qu'ils soient cuits à coeur.","Astuce : pour savoir quand les retourner, regardez sur le côté : lorsqu'ils sont cuits à mi-hauteur, retournez-les !","En fin de cuisson, déglacez (versez) avec le sirop d'érable et poursuivez la cuisson 1 min en nappant le saumon."]}]},{"id":"21932","nom":"Pavé de saumon sauce teriyaki à l'orange","image":"images/21932.webp","ingredients":[["sauce soja salée (23g)","20 ml"],["gousse d'ail (3g)","0.5"],["nouilles asiatiques (120g)","120 g"],["pavés de saumon (240g)","240 g"],["sésame doré (10g)","10 g"],["orange (150g)","1x"]],"cuisine":["sel","poivre","huile de cuisson","1 càc farine ou maïzena","100 ml eau (sauce)"],"etapes":[{"titre":"Le saumon","items":["Rincez et essuyez les pavés de saumon. Salez et poivrez-les.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites dorer les pavés de saumon (côté peau en premier) 2 à 3 min de chaque côté jusqu'à ce qu'ils soient cuits à coeur.","Astuce : pour savoir quand les retourner, regardez sur le côté : lorsqu'ils sont cuits à mi-hauteur, retournez-les !","Une fois cuits, réservez-les sur une assiette et gardez la sauteuse."]},{"titre":"La sauce","items":["Pressez ou hachez l'ail.","Pressez l'orange.","Dans la même sauteuse que celle du saumon, faites de nouveau chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'ail 1 à 2 min. Ajoutez la farine ou la maïzena, puis le jus d'orange, la sauce soja et l'eau en mélangeant bien.","Prolongez la cuisson 2 à 5 min jusqu'à ce que la sauce soit nappante.","Maintenez sur feu doux le temps de la cuisson des nouilles."]},{"titre":"Les nouilles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet en remuant régulièrement pour éviter qu'elles ne collent.","Égouttez-les.","Servez les nouilles avec le saumon nappé de sauce. Parsemez de sésame."]}]},{"id":"17348","nom":"Pavé de truite et orzo à la fourme d'Ambert","image":"images/17348.webp","ingredients":[["gousse d'ail (4g)","1x"],["échalote (25g)","1x"],["pavé de truite (250g)","2x"],["pâtes orzo","200 g"],["fourme d'Ambert (lait pasteurisé)","60 g"]],"cuisine":["sel","poivre","huile d'olive","600 ml eau","0.5 bouillon de légumes (cube)"],"etapes":[{"titre":"L'orzo à la fourme d'Ambert","items":["Ciselez (dés) l'échalote.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites dorer l'échalote et l'ail 2 min.","Ajoutez l'orzo et faites-le revenir 1 min pour le nacrer (l'enrober d'huile).","Versez l'eau et le bouillon émietté et couvrez. Faites cuire 10 à 15 min jusqu'à ce que l'orzo soit cuit. Salez, poivrez. Remuez régulièrement.","Astuce : ajoutez de l'eau en cours de cuisson si nécessaire.","Pendant ce temps, faites cuire le poisson."]},{"titre":"La truite","items":["Rincez et essuyez la truite. Salez et poivrez-la.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir la truite 2 à 3 min de chaque côté jusqu'à ce qu'elle soit cuite à coeur.","Pour savoir quand les retourner, regardez sur le côté : lorsqu'ils sont cuits à mi-hauteur, retournez-les !"]},{"titre":"A table !","items":["Coupez la fourme d'Ambert en morceaux.","Une fois l'orzo cuit, ajoutez la fourme dans la sauteuse et mélangez bien jusqu'à ce qu'elle soit fondue.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17958","nom":"Pennes à la poitrine fumée, champignons et parmesan","image":"images/17958.webp","ingredients":[["poitrine fumée","90 g"],["parmigiano reggiano râpé","20 g"],["crème","100 g"],["penne demi-complètes","200 g"],["champignons de Paris blancs","250 g"],["poireau (215g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les penne","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","En parallèle, faites cuire la poitrine fumée et les légumes."]},{"titre":"La poitrine fumée et les légumes","items":["Coupez et retirez la base abîmée du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Coupez les champignons en tranches.","Coupez la poitrine fumée en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir la poitrine fumée 2 min.","Au bout des 2 min, ajoutez le poireau, les champignons et poursuivez la cuisson 15 min. Salez, poivrez.","Au bout des 15 min, ajoutez la crème et les pennes cuites.","Faites revenir le tout 2 à 3 min jusqu'à ce que la sauce soit nappante.","Astuce : Ajoutez un peu d’eau de cuisson des pâtes pour lier la sauce et la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Au moment de passer à table, parsemez vos pennes de parmesan."]}]},{"id":"15796","nom":"Pennes al ragù de veau","image":"images/15796.webp","ingredients":[["carotte (240g)","2x"],["herbes de Provence (sachet)","0.25"],["gousse d'ail (5g)","1x"],["purée de tomates","250 g"],["veau haché","250 g"],["oignon jaune","0.5"],["pennes demi-complètes","200 g"]],"cuisine":["sel","poivre","huile d'olive","0.25 bouillon de bœuf (cube)"],"etapes":[{"titre":"Le veau","items":["Emincez l'oignon.","Epluchez et coupez les carottes en fines demi-rondelles.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les carottes, l'oignon et le veau haché 5 min environ.","Au bout des 5 min, ajoutez la purée de tomates, l'ail, le bouillon de boeuf et les herbes de Provence. Salez, poivrez.","Couvrez et faites mijoter 10 min environ à feu moyen.","Ajoutez un peu d'eau si nécessaire.","Astuce : ajoutez une cuillère à café de sucre pour réduire l'acidité de la sauce tomate.","Pendant ce temps, faites cuire les pennes."]},{"titre":"Les pennes","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les pennes selon les indications du paquet."]}]},{"id":"19278","nom":"Pennes au saumon et crème citronnée","image":"images/19278.webp","ingredients":[["crème","80 g"],["gousse d'ail","0.5"],["pennes demi-complètes","200 g"],["pavé de saumon","240 g"],["citron jaune","0.5"],["échalote (25g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les pennes","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les pennes selon les indications du paquet.","Gardez un peu d'eau de cuisson pour réaliser la sauce.","Une fois cuites, égouttez-les et remettez-les dans la casserole.","Pendant la cuisson des pennes, faites cuire le saumon."]},{"titre":"Le saumon","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites dorer les pavés de saumon (côté peau en premier) 2 à 3 min de chaque côté. Salez, poivrez.","Pour savoir quand les retourner, regardez sur le côté : lorsqu’ils sont cuits à mi-hauteur, retournez-les !","Une fois cuit, retirez la peau du saumon et coupez-le en gros dés.","En parallèle, réalisez la sauce."]},{"titre":"La sauce","items":["Pressez le citron jaune.","Pressez ou hachez l'ail.","Ciselez (dés) l'échalote.","Dans une petite casserole, versez la crème et portez à ébullition.","Ajoutez l'ail, l'échalote et le jus de citron. Salez et poivrez. Poursuivez la cuisson à feu doux 2 min environ.","Une fois le tout cuit, ajoutez la crème, les dés de saumon et un peu d'eau de cuisson dans la casserole des pennes. Mélangez délicatement.","Astuce : ajoutez un peu d’eau de cuisson des pâtes permet de lier la sauce et de la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Faites chauffer le tout 1 min à feu doux.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"18725","nom":"Pennes au thon à la sauce tomate et pangrattato","image":"images/18725.webp","ingredients":[["penne demi-complètes","200 g"],["thon entier au naturel (g égoutté) (93g)","93x"],["pulpe de tomates","210 g"],["parmigiano reggiano râpé","20 g"],["crème","80 g"],["chapelure panko","25 g"],["citron jaune","0.5"],["gousse d'ail","0.25"],["persil plat","qq brins"],["oignon jaune","0.5"]],"cuisine":["huile d'olive","sel","poivre"],"etapes":[{"titre":"Les pâtes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Astuce : conservez un bol d'eau de cuisson des pâtes pour ajuster la consistance de la sauce.","Pendant la cuisson des pâtes, préparez la sauce."]},{"titre":"La sauce","items":["Ciselez (dés) l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 5 min jusqu'à ce qu'il soit translucide.","Ajoutez la pulpe de tomate et le thon. Salez, poivrez et mélangez bien.","Faites mijoter à couvert le temps de la cuisson des pâtes et préparez le pangrattato."]},{"titre":"Le pangrattato","items":["Pressez ou hachez l'ail.","Dans une petite poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'ail et la chapelure panko 5 à 10 min jusqu'à ce qu'elle soit dorée et croustillante.","En parallèle, effeuillez et ciselez le persil.","À l'aide d’une râpe, prélevez les zestes de citron (uniquement l’écorce de couleur).","Dans un bol, mélangez la chapelure à l'ail, le parmesan, le persil, les zestes de citron (plus ou moins selon votre goût). Salez, poivrez et mélangez bien."]},{"titre":"A table !","items":["Pressez le citron.","Une fois les pâtes cuites, ajoutez-les dans la sauteuse avec la crème et le jus de citron (plus ou moins selon votre goût). Mélangez pour tout enrober.","Astuce : ajustez la consistance de la sauce avec de l'eau de cuisson des pâtes.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Servez vos pennes au thon à la sauce tomate parsemées du pangrattato."]}]},{"id":"15855","nom":"Pennes aux crevettes sauce marinara (basilic, tomates et ail)","image":"images/15855.webp","ingredients":[["penne demi-complètes","200 g"],["crevettes cuites nature","125 g"],["basilic séché (sachet)","0.25"],["purée de tomates","250 g"],["gousse d'ail (6g)","1x"],["pousses d'épinards","100 g"],["oignon jaune (125g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les pennes","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les pennes selon les indications du paquet.","Pendant ce temps, préparez la sauce marinara."]},{"titre":"La sauce marinara","items":["Émincez l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 10 min.","Pendant ce temps, pressez ou hachez l'ail.","Au bout des 10 min de cuisson, ajoutez les crevettes, l'ail, le basilic séché, la purée de tomates et les pousses d'épinards dans la sauteuse. Poursuivez la cuisson 5 min. Salez, poivrez.","Ajoutez les pennes égouttées et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17650","nom":"Pennes aux émincés de porc thym citron et champignons","image":"images/17650.webp","ingredients":[["émincés de porc thym citron","240 g"],["champignons de Paris blancs","250 g"],["oignon jaune (110g)","1x"],["gousse d'ail (6g)","1x"],["pennes demi-complètes","200 g"],["crème","100 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La garniture","items":["Coupez les champignons en tranches.","Émincez l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les émincés de porc 5 min jusqu'à ce qu'ils soient cuits et dorés (la chair n'est plus rose) puis réservez-les.","Dans la même sauteuse, faites de nouveau chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, l'ail et les champignons 10 min jusqu'à ce que l'oignon et les champignons soient dorés. Salez, poivrez.","Pendant la cuisson des légumes, faites cuire les pâtes."]},{"titre":"Les pennes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Gardez un petit bol d'eau de cuisson pour la sauce."]},{"titre":"A table !","items":["Une fois les champignons grillés, ajoutez la crème, les émincés de porc, les pâtes et un peu d'eau de cuisson des pâtes.","Poursuivez la cuisson 2 min environ et mélangez bien jusqu'à ce que la sauce soit nappante."]}]},{"id":"21811","nom":"Pizza à la mortadelle, noix et burrata","image":"images/21811.webp","ingredients":[["fromage blanc (100g)","100 g"],["mortadelle aux pistaches (90g)","90 g"],["burrata (100g)","1x"],["sucrine (100g)","1x"],["noix sèche (40g)","40 g"],["pâte à pizza (300g)","300 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix"],"etapes":[{"titre":"La cuisson de la pâte à pizza","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, déposez la pâte à pizza sur une plaque allant au four. Arrosez d'un filet d'huile d'olive. Salez, poivrez.","Enfournez 10 min environ jusqu'à ce que la pâte soit cuite et dorée.","En parallèle, préparez la garniture."]},{"titre":"La garniture","items":["Ouvrez et hachez les noix.","Déchirez la mortadelle en morceaux.","Coupez la burrata en morceaux.","Salez et poivrez généreusement le fromage blanc.","Une fois la pâte à pizza cuite, étalez le fromage blanc puis répartissez dessus la mortadelle et la burrata.","Parsemez de noix et arrosez d'un filet d'huile d'olive.","Coupez la base de la sucrine et émincez-la. Assaisonnez-la d'un filet d'huile d'olive et de vinaigre. Salez, poivrez."]}]},{"id":"15990","nom":"Pizza épinards, œuf et parmesan","image":"images/15990.webp","ingredients":[["boule à pizza (300g)","1x"],["purée de tomates","250 g"],["parmigiano reggiano râpé","20 g"],["mozzarella de vache","125 g"],["oignon rouge","0.5"],["pousses d'épinards","100 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","1 oeuf","farine"],"etapes":[{"titre":"La garniture","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, coupez la mozzarella en morceaux.","Émincez l'oignon rouge."]},{"titre":"La pizza","items":["Sur un plan de travail fariné, déposez votre boule de pâte à pizza.","À l'aide de vos mains, étirez la pâte à pizza sur les côtés progressivement pour obtenir un disque de pâte.","Déposez votre pâte à pizza sur une plaque allant au four munie d'une feuille de papier cuisson.","Étalez la purée de tomates sur la pâte.","Répartissez dessus la moitié des pousses d'épinards, l'oignon rouge et les morceaux de mozzarella. Salez, poivrez et versez un filet d'huile d'olive.","Parsemez de parmesan.","Enfournez 10 min environ.","Au bout des 10 min de cuisson, cassez l’œuf au centre de la pizza et enfournez de nouveau 5 min jusqu'à ce le blanc soit cuit et la pâte cuite et dorée (soulevez délicatement pour vérifier)."]},{"titre":"La salade","items":["Assaisonnez le reste de pousses d'épinards d'un filet d'huile d'olive et de vinaigre."]},{"titre":"","items":["Servez sans attendre votre pizza épinards, oeuf et parmesan accompagnée de la salade !"]}]},{"id":"18735","nom":"Pizza piccante (farce à merguez de porc) aux épices tex-mex","image":"images/18735.webp","ingredients":[["oignon jaune (110g)","1x"],["mélange tex-mex (sachet)","0.5"],["farce à merguez au porc Bleu Blanc Coeur","240 g"],["pâte à pizza","300 g"],["purée de tomates","100 g"],["mozzarella râpée","30 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La garniture","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, émincez l'oignon.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir l'oignon, la farce à merguez émiettée et le mélange tex-mex 5 à 10 min. Salez, poivrez."]},{"titre":"La pizza","items":["Déroulez la pâte à pizza sur une plaque allant au four munie d'un papier cuisson.","Etalez la purée de tomates et répartissez dessus l'oignon et la farce à merguez.","Saupoudrez le tout de mozzarella râpée.","Enfournez 10 à 15 min jusqu’à ce que la pizza soit dorée et cuite (soulevez délicatement pour vérifier)."]}]},{"id":"16736","nom":"Poêlée de spätzles au pesto de basilic et champignons","image":"images/16736.webp","ingredients":[["oignon rouge (90g)","1x"],["basilic","0.5"],["parmigiano reggiano râpé","20 g"],["champignons de Paris blancs","250 g"],["gousse d'ail","0.5"],["spätzle frais","400 g"],["graines de courge","15 g"]],"cuisine":["3 càs huile d'olive","1 càs eau","sel","poivre"],"etapes":[{"titre":"Les champignons et les spätzles","items":["Coupez les champignons en tranches.","Émincez l'oignon rouge.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et les champignons 10 min.","Au bout des 10 min, ajoutez les spätzles et poursuivez la cuisson 5 min. Salez, poivrez.","En parallèle, réalisez le pesto."]},{"titre":"Le pesto de basilic","items":["Dans le bol d'un mixeur, déposez les ingrédients suivants :","Pelez l'ail.","Effeuillez le basilic.","Ajoutez le parmesan, l'huile d'olive et l'eau. Salez, poivrez.","Mixez jusqu'à obtenir une texture homogène.","Astuce : Ajoutez un peu d'eau si vous souhaitez un pesto plus liquide.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez votre assiette des graines de courge."]}]},{"id":"15530","nom":"Poêlée de spätzles aux cœurs d'artichauts et aux noix","image":"images/15530.webp","ingredients":[["spätzle frais","400 g"],["fromage blanc","100 g"],["cœurs d'artichauts","80 g"],["poireau (300g)","1x"],["persil plat","qq brins"],["noix sèche (avec coque)","40 g"],["oignon rouge","0.5"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon rouge.","Coupez et retirez la base abîmée du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poireau et l'oignon 15 min.","A mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson. Salez, poivrez.","Coupez les coeurs d'artichauts en morceaux.","Au bout des 15 min de cuisson, ajoutez les coeurs d'artichauts et poursuivez la cuisson 2 min.","Pendant la cuisson des légumes, faites cuire les spätzle."]},{"titre":"Les spätzles","items":["Dans une seconde sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les spätzles 5 min jusqu'à ce qu'ils soient dorés.","Une fois les légumes cuits, ajoutez les spätzles dans la sauteuse des légumes et mélangez bien.","En parallèle, réalisez la sauce au fromage blanc."]},{"titre":"La sauce au fromage blanc","items":["Effeuillez et ciselez le persil.","Dans un bol, mélangez le fromage blanc avec le persil et un filet d'huile d'olive. Salez, poivrez.","Ouvrez les noix et hachez-les grossièrement.","Nappez la poëlée de sauce au fromage blanc et parsemez de noix."]}]},{"id":"20872","nom":"Poké de crevettes au gingembre & kiwi, vinaigrette acidulée","image":"images/20872.webp","ingredients":[["kiwi vert (240g)","3x"],["roquette (150g)","150 g"],["graines de courge (25g)","25 g"],["gousse d'ail (6g)","1x"],["boulgour (360g)","360 g"],["crevettes cuites nature (380g)","380 g"],["gingembre (20g)","1 à 3 cm"],["endive (550g)","5x"]],"cuisine":["7 càs huile d'olive8 (vinaigrette)","5 càs vinaigre de votre choix (vinaigrette)","sel","poivre"],"etapes":[{"titre":"Le boulgour","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le boulgour selon les indications du paquet.","Lorsqu'il est cuit, égouttez-le.","Astuce : pour éviter que le boulgour soit trop aqueux, laissez-le s'égoutter le temps de la recette.","Ajoutez un filet d'huile d'olive et de vinaigre et laissez-le refroidir à température ambiante.","Pendant ce temps, préparez les crevettes."]},{"titre":"Les crevettes","items":["Pressez ou hachez l'ail.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les crevettes et l'ail 3 à 5 min pour les réchauffer. Ne salez pas, les crevettes le sont déjà.","En parallèle, coupez les légumes."]},{"titre":"La salade","items":["Epluchez et coupez le kiwi en dés.","Retirez la base de l'endive. Coupez-la en 2 et retirez la partie centrale dure. Émincez-la.","Epluchez et râpez le gingembre.","Dans un bol, déposez l'huile d'olive, le vinaigre et le gingembre, salez, poivrez et mélangez pour obtenir une vinaigrette.","Dans des bols, déposez le boulgour, puis répartissez, dessus en compartiment, les crevettes, l'endive, le kiwi et la roquette.","Nappez le tout de vinaigrette et parsemez de graines de courge."]}]},{"id":"16688","nom":"Porc au caramel et blette","image":"images/16688.webp","ingredients":[["sauce soja salée","20 ml"],["nuoc mam (sauce poisson)","15 ml"],["sauté d'échine de porc Bleu Blanc Coeur","240 g"],["sésame doré","10 g"],["riz basmati","150 g"],["coriandre","qq brins"],["oignon jaune","0.5"],["blette","200 g"]],"cuisine":["sel","poivre","huile de cuisson","2 càs sucre","2 càs eau"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon.","Coupez la base des blettes (sur 2 cm environ) et émincez-les.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon et les blettes 15 à 20 min.","A mi-cuisson, ajoutez un fond d’eau et couvrez pour accélérer la cuisson. Salez et poivrez. Remuez régulièrement.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, faites cuire le porc au caramel."]},{"titre":"Le porc","items":["Redécoupez les morceaux de porc s'ils sont un peu gros.","Dans une seconde sauteuse, versez le sucre et l'eau et faites chauffer à feu moyen à vif 3 min jusqu'à ce que le sucre soit dissout et que le mélange brunisse. Surveillez bien et ne mélangez pas (ou sinon à la spatule en bois).","Une fois le caramel formé, ajoutez le porc, la sauce soja et la sauce nuoc mam. Poursuivez la cuisson 10 min environ. Remuez régulièrement. Poivrez.","Ciselez la coriandre (en entier, les tiges se consomment) et parsemez-la ainsi que le sésame sur votre assiette."]}]},{"id":"22124","nom":"Porc au caramel et chou pak choy","image":"images/22124.webp","ingredients":[["sauce soja salée (23g)","20 ml"],["nuoc mam (sauce poisson) (18g)","15 ml"],["gousse d'ail (6g)","1x"],["oignon jaune (62.5g)","0.5"],["sauté d'échine de porc (240g) Bleu Blanc Coeur","240 g"],["sésame doré (10g)","10 g"],["riz concassé du Pendjab (150g)","150 g"],["coriandre (5g)","qq brins"],["chou pak choy (270g)","2x"]],"cuisine":["sel","poivre","huile de cuisson","4 càs sucre (caramel)","2 càs eau (caramel)"],"etapes":[{"titre":"Le porc","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Épongez la viande à l'aide d'un essuie-tout. Redécoupez les morceaux de porc afin qu'ils soient de taille similaire si nécessaire. Salez, poivrez.","Dans une sauteuse, versez le sucre et l'eau et faites chauffer à feu moyen 3 min jusqu'à ce que le sucre soit dissous et que le mélange brunisse. Surveillez bien la cuisson et, si besoin, mélangez uniquement à l'aide d'une spatule en bois.","Astuce : surveillez bien le caramel : dès qu'il prend une couleur ambrée, ajoutez le porc pour éviter qu'il ne brûle.","Une fois le caramel formé, ajoutez le porc, la sauce soja et la sauce nuoc mam. Poursuivez la cuisson 10 à 15 min jusqu'à ce que la sauce soit nappante et enrobe le porc. Remuez régulièrement.","Pendant ce temps, préparez les légumes."]},{"titre":"Les légumes","items":["Émincez l'oignon.","Coupez la base du chou pak choy et émincez-le.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'oignon, l'ail et le chou pak choy 8 à 10 min jusqu'à ce qu'ils soient légèrement croquants (ou tendres selon votre goût). Salez légèrement, poivrez.","A mi-cuisson, ajoutez un fond d’eau et couvrez pour accélérer la cuisson. Remuez régulièrement.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire le riz selon les indications du paquet.","Ciselez la coriandre (en entier, les tiges se consomment).","Au moment de servir, parsemez la coriandre et le sésame sur votre plat."]}]},{"id":"17497","nom":"Poulet caramélisé à la figue et purée de légumes","image":"images/17497.webp","ingredients":[["confiture figue","28 g"],["sauce soja salée","10 ml"],["gousse d'ail (6g)","1x"],["aiguillette de poulet La Nouvelle Agriculture","250 g"],["carotte (200g)","2x"],["navet rond (100g)","1x"],["pomme de terre (400g)","2x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","lait","beurre"],"etapes":[{"titre":"La purée de légumes","items":["Portez à ébullition une casserole d'eau salée.","Pendant ce temps, épluchez les légumes. Coupez les pommes de terre et le navet en dés, et les carottes en petits morceaux (elles cuisent plus lentement).","Déposez-les dans une casserole d’eau salée froide et portez à ébullition.","Faites cuire 20 à 25 min jusqu’à ce qu’ils soient bien tendres.","Égouttez et réduisez le tout en purée. Salez, poivrez.","Ajoutez une noix de beurre et un filet de lait pour une purée plus onctueuse.","En parallèle, préparez le poulet."]},{"titre":"Le poulet","items":["Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les aiguillettes 5 min jusqu'à ce qu'elles soient cuites à coeur (la chair n'est plus rose). Retournez-les régulièrement. Poivrez, ne salez pas, la sauce soja apporte déjà du sel.","En fin de cuisson, ajoutez le la confiture de figue, la sauce soja et l'ail. Mélangez bien 1 à 2 min pour enrober le poulet.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Effeuillez et ciselez le persil.","Au moment de servir, parsemez le tout de persil."]}]},{"id":"18417","nom":"Poulet sauce aigre-doux, chou pak choy et sésame","image":"images/18417.webp","ingredients":[["aiguillette de poulet La Nouvelle Agriculture","250 g"],["sauce piment doux","40 ml"],["sauce soja salée","20 ml"],["gousse d'ail (6g)","1x"],["riz basmati","150 g"],["sésame doré","10 g"],["oignon jaune (110g)","1x"],["gingembre","1 à 3 cm"],["chou pak choy (135g)","1x"]],"cuisine":["100 ml eau","huile de cuisson","sel","poivre","1 càc sucre ou miel","1 càc vinaigre (blanc ou de cidre)","0.5 càc maïzena"],"etapes":[{"titre":"La marinade","items":["Coupez le poulet en morceaux.","Pressez ou hachez l'ail et le gingembre.","Dans un saladier, mélangez la sauce soja, l'ail, le gingembre et le poulet. Ne salez pas, la sauce soja apporte déjà du sel. Poivrez.","Mélangez bien et laissez mariner au frais le temps de la cuisson du riz et de la préparation des légumes."]},{"titre":"Le riz et les légumes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, coupez la base du chou pak choy et émincez-le finement.","Émincez l'oignon."]},{"titre":"Le poulet sauce aigre-douce","items":["Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir le poulet sans la marinade (conservez-la) 5 min environ jusqu'à ce qu'il soit bien doré.","Astuce : le poulet est bien saisi quand il a une croûte dorée et se détache facilement de la poêle.","Débarrassez-le sur une assiette. Gardez la sauteuse.","Dans la même sauteuse, faites chauffer un nouveau filet d'huile de cuisson à feu moyen.","Faites revenir les légumes 5 min environ.","Dans un saladier, délayez la maïzena avec l'eau à l'aide d'un fouet. Ajoutez ensuite le vinaigre, le sucre et la sauce piment doux. Mélangez bien.","Une fois les légumes cuits, réservez-les avec le poulet.","Versez la sauce dans la sauteuse et portez à ébullition puis baissez à feu moyen 2 à 3 min.","Une fois la sauce épaissie et nappante, ajoutez les légumes et le poulet. Mélangez bien pour enrober le tout.","Astuce : pour vérifier la consistance de la sauce, trempez une cuillère à soupe dedans et passez votre doigt dessus. La sauce est prête lorsque la trace est nette.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez votre assiette de sésame doré."]}]},{"id":"20172","nom":"Poulet sauce au poivre fumé et poêlée de haricots verts et champignons","image":"images/20172.webp","ingredients":[["haut de cuisse de poulet désossé (225g)","225 g"],["crème (80g)","80 g"],["cognac (19g)","20 ml"],["poivre noir fumé au bois de hêtre (baie) (1g)","4x"],["échalote (25g)","1x"],["persil plat (5g)","qq brins"],["champignons de Paris blancs (250g)","250 g"],["riz concassé du Pendjab (120g)","120 g"],["haricots verts (400g)","400 g"],["gousse d'ail (6g)","1x"]],"cuisine":["sel","poivre","huile d'olive","250 ml eau (sauce)","0.5 bouillon de poule (cube)","1 maïzena (càc)","beurre"],"etapes":[{"titre":"Le poulet","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Épongez le poulet à l'aide d'un essuie-tout. Salez, poivrez.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les hauts de cuisse 2 à 3 min de chaque côté puis réservez-les sur une assiette.","Gardez la sauteuse pour la sauce au poivre et au cognac."]},{"titre":"La sauce au poivre et au cognac","items":["Ciselez (dés) l'échalote.","Effeuillez et ciselez le persil.","Écrasez les baies de poivre fumé avec le plat de la lame d'un couteau ou le fond d'un verre.","Astuce : ajustez la quantité de poivre selon vos goûts.","Délayez la maïzena dans un peu d'eau froide et réservez-la pour la fin de cuisson de la sauce.","Dans la sauteuse ayant servi à la cuisson du poulet, faites fondre une noix de beurre à feu moyen.","Faites revenir l'échalote et le poivre 3 min environ. Remuez régulièrement.","Au bout des 3 min, déglacez (versez) avec le cognac.","Ajoutez l'eau et le bouillon de poule émietté. Portez à ébullition et faites réduire de moitié.","Ajoutez la maïzena délayée, la crème et la moitié du persil dans la sauteuse. Mélangez bien.","Replacez le poulet et poursuivez 10 à 15 min à feu doux jusqu'à ce qu'il soit cuit à coeur (la chair n'est plus rose) et que la sauce soit légèrement nappante.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant la cuisson du poulet, préparez le riz et les légumes."]},{"titre":"Le riz et les légumes","items":["Equeutez les haricots verts.","Portez à ébullition deux casseroles d'eau salée.","Dans l'une, faites cuire le riz selon les indications du paquet.","Dans l'autre, faites cuire les haricots verts 10 min environ, jusqu'à ce qu'ils soient légèrement tendres : ils finiront de cuire avec les champignons. Égouttez puis passez-les sous l’eau froide pour stopper la cuisson.","Coupez les champignons en tranches.","Pressez ou hachez l'ail.","Dans la casserole ayant servi aux haricots verts, faites chauffer une noix de beurre à feu moyen.","Faites revenir les haricots verts, les champignons et l'ail 8 à 10 min, jusqu'à ce que les champignons soient légèrement dorés.","Servez le poulet nappé de sauce au poivre et au cognac accompagné du riz et des légumes. Parsemez le tout du reste de persil.","Astuce : passez votre sauce au chinois (à la passoire) pour retirer les baies de poivre."]}]},{"id":"19902","nom":"Poulet sauce satay (cacahuètes et lait de coco)","image":"images/19902.webp","ingredients":[["gingembre (20g)","1 à 3 cm"],["cébette (8g)","0.5"],["gousse d'ail (6g)","1x"],["cacahuètes grillées sans sel (100g)","100 g"],["lait de coco (150g)","150 ml"],["filet de poulet La Nouvelle Agriculture (300g)","2x"],["double concentré de tomates (35g)","35 g"],["oignon jaune (110g)","1x"],["riz concassé du Pendjab (150g)","150 g"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Le poulet","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Épongez la viande à l'aide d'un essuie-tout. Salez, poivrez.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Saisissez les filets de poulet 2 à 3 min de chaque côté pour les dorer puis réservez-les sur une assiette."]},{"titre":"La sauce satay","items":["Dans le bol d'un mixeur, déposez les cacahuètes, le lait de coco et le concentré de tomates.","Mixez jusqu'à obtention d'une sauce homogène.","Astuce : ajoutez de l'eau pour une sauce plus liquide.","Émincez l'oignon.","Pelez et hachez finement le gingembre et l'ail.","Dans la même sauteuse que le poulet, faites de nouveau chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'oignon, l'ail et le gingembre 2 min.","Au bout des 2 min, ajoutez la sauce aux cacahuètes et mélangez 1 à 2 min.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le poulet sauce satay","items":["Replacez le poulet dans la sauteuse avec la sauce. Couvrez et poursuivez la cuisson 10 à 15 min jusqu'à ce qu'il soit cuit à coeur (la chair n'est plus rose).","Goûtez, rectifiez l’assaisonnement et ajustez la quantité d'eau si nécessaire.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Retirez la base de la cébette et émincez-la.","Au moment de servir, parsemez le poulet de cébette."]}]},{"id":"18604","nom":"Quesadillas au cheddar, crème de haricots rouges et piment chipotle","image":"images/18604.webp","ingredients":[["tortilla (200g)","4x"],["piment chipotle (pincée) (0.5g)","2x"],["gousse d'ail","0.5"],["fromage blanc","100 g"],["cheddar râpé","60 g"],["haricots rouges conserve","100 g égoutté"],["carotte (200g)","2x"],["oignon rouge","0.25"],["citron vert","0.5"],["salade","50 g"]],"cuisine":["sel","poivre","2 càs huile d'olive"],"etapes":[{"titre":"La crème de haricots rouges","items":["Pelez l'ail.","Rincez et égouttez les haricots rouges.","Dans le bol d'un mixeur, déposez l'ail, les haricots rouges égouttés, un filet d'huile d'olive et le piment chipotle (Le piment est fort, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût). Salez. Mixez jusqu'à obtenir une texture homogène.","Goûtez et rectifiez la quantité de piment chipotle selon votre goût."]},{"titre":"La salade","items":["A l'aide d'une râpe, prélevez des zestes de citron (uniquement l'écorce de couleur) et pressez-le. Réservez les zestes.","Épluchez et râpez les carottes.","Dans un saladier, versez le jus de citron et l'huile d'olive. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ajoutez les carottes et la salade. Mélangez bien."]},{"titre":"La sauce au citron vert","items":["Dans un bol, mélangez le fromage blanc, les zestes de citron vert et un filet d'huile d'olive. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les quesadillas","items":["Émincez finement l'oignon.","Sur chaque tortilla, étalez la crème de haricots rouges.","Répartissez par-dessus l'oignon et le cheddar.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Pliez les tortillas en 2 et faites-les dorer 2 à 3 min sur chaque face.","Astuce : couvrez la poêle pendant la cuisson pour aider le cheddar à bien fondre sans brûler la tortilla.","Dégustez sans attendre vos quesadillas accompagnées de la salade et de la sauce au citron vert."]}]},{"id":"16523","nom":"Ragoût de pois chiches et d'orzo à la courgette, féta et menthe","image":"images/16523.webp","ingredients":[["pâtes orzo","100 g"],["pois chiches conserve","265 g"],["oignon jaune (110g)","1x"],["gousse d'ail (6g)","1x"],["cumin (sachet)","0.5"],["courgette (200g)","1x"],["menthe","qq brins"],["pulpe de tomates","400 g"],["féta","80 g"]],"cuisine":["0.5 bouillon de légumes","250 ml eau","sel","poivre"],"etapes":[{"titre":"La préparation","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Coupez la courgette en demi-rondelles.","Égouttez et rincez les pois chiches."]},{"titre":"Le ragoût","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et la courgette 3 min.","Ajoutez les pois chiches, l'orzo et le cumin et faites revenir le tout 1 min. Salez, poivrez.","Ajoutez la pulpe de tomates, l'ail, l'eau et le bouillon de légumes. Mélangez et portez à ébullition.","Baissez le feu, couvrez et laissez mijoter 15 min environ jusqu'à ce que l'orzo soit cuit.","Ajoutez un peu d'eau en cours de cuisson si nécessaire.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Effeuillez et ciselez la menthe.","Émiettez la féta.","Au moment de servir, parsemez la menthe et la féta sur le ragoût."]}]},{"id":"19478","nom":"Ramen de porc à la provençale, pak choy et oignons frits","image":"images/19478.webp","ingredients":[["émincés de porc provençal (240g)","240 g"],["nouilles asiatiques (225g)","225 g"],["céleri branche (50g)","1x"],["gousse d'ail (6g)","1x"],["oignons frits (sachet) (8g)","1x"],["cébette (16g)","1x"],["gingembre (20g)","1 à 3 cm"],["sauce sriracha (10g)","10 ml"],["chou pak choy (135g)","1x"]],"cuisine":["huile de cuisson","sel","poivre","0.5 cube bouillon de poule","800 ml eau"],"etapes":[{"titre":"Les émincés de porc","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Dans une cocotte, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir les émincés de porc 5 à 7 min (la chair n'est plus rose, la viande est cuite à cœur).","Réservez la viande dans une assiette et gardez la cocotte pour le reste de la recette.","En parallèle, préparez la garniture."]},{"titre":"Le bouillon","items":["Retirez le bout abîmé du céleri branche et émincez-le finement.","Coupez la base du chou pak choy et émincez-le.","Pelez et hachez l'ail et le gingembre.","Dans la cocotte ayant servi à la cuisson des émincés de porc, faites chauffer de nouveau un filet d'huile de cuisson à feu moyen.","Faites revenir le céleri, le chou pak choy, le gingembre et l'ail 2 min en grattant les sucs de la viande. Salez, poivrez.","Au bout des 2 min, ajoutez l'eau et le bouillon de poule émietté.","Portez à ébullition, puis baissez à feu moyen et laissez mijoter à petits bouillons, à couvert 10 min.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Le ramen","items":["Retirez la base de la cébette et émincez-la.","Une fois le bouillon mijoté, ajoutez-y les nouilles et faites-les cuire selon les indications du paquet. Remuez bien pendant la cuisson pour éviter qu'elles ne collent entre elles.","Dans des assiettes creuses ou des bols, déposez les émincés de porc puis versez le bouillon et sa garniture dessus.","Parsemez d'oignons frits et de cébette et nappez de sriracha."]}]},{"id":"19528","nom":"Ramen pimenté de canard au chou pak choy et sésame doré","image":"images/19528.webp","ingredients":[["sauce soja salée","20 ml"],["filet de canard (240g)","2x"],["sésame doré","10 g"],["nouilles asiatiques","120 g"],["gousse d'ail (4g)","1x"],["gingembre","1 à 3 cm"],["piment oiseau (2g)","1x"],["chou pak choy (135g)","1x"],["cébette (16g)","1x"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile de cuisson","0.25 bouillon de poule (cube)","800 ml eau","1 càs sucre"],"etapes":[{"titre":"Le canard","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Épongez la viande à l'aide d'un essuie-tout.","Quadrillez la peau des filets de canard à l'aide d'un couteau, sans inciser la chair. Lors de la cuisson, cela permettra à la chaleur de bien pénétrer dans les filets !","Faites chauffer une sauteuse sans matière grasse à feu vif.","Une fois la sauteuse chaude, saisissez les filets de canard côté peau 2 à 4 min jusqu'à ce que la peau soit bien dorée.","Baissez sur feu moyen, retournez les filets et poursuivez la cuisson 3 à 6 min selon la cuisson souhaitée (rosée ou à point).","Réservez le canard cuit dans une feuille de papier aluminium et laissez-le reposer le temps de préparer le reste des ingrédients.","Retirez l’excédent de gras et gardez la sauteuse pour la préparation du bouillon."]},{"titre":"Le chou pak choy","items":["Coupez le chou pak choy en 2.","Dans une seconde sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir le chou pak choy avec le sucre et un fond d'eau 5 à 8 min par face à couvert. Salez, poivrez.","Pendant la cuisson du chou pak choy, réalisez le bouillon."]},{"titre":"Le bouillon","items":["Pelez et hachez l'ail et le gingembre.","Émincez l'oignon.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Dans la sauteuse du canard, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'oignon, l'ail et le gingembre 5 min puis ajoutez l'eau, le piment, le bouillon de poule émietté et la sauce soja.","Astuce : ne salez pas, le bouillon et la sauce soja apportent déjà du sel.","Portez à ébullition 5 min puis ajoutez les nouilles, et poursuivez la cuisson selon le temps indiqué sur le paquet.","Astuce : ajoutez de l'eau en cours de cuisson si nécessaire."]},{"titre":"A table !","items":["Retirez la base de la cébette et émincez-la.","Coupez le canard en tranches fines.","Dans des bols, répartissez les nouilles et le bouillon. Déposez dessus le canard et le chou pak choy. Parsemez de cébette et de sésame."]}]},{"id":"21208","nom":"Ravioles à poêler (aux 3 fromages) et tomates cerises rôties au basilic","image":"images/21208.webp","ingredients":[["ravioles aux 3 fromages à poêler (300g)","300 g"],["gousse d'ail (6g)","1x"],["parmigiano reggiano râpé (20g)","20 g"],["tomate cerise (300g)","300 g"],["oignon rouge (55g)","0.5"],["basilic (5g)","qq brins"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les ravioles","items":["Dans une sauteuse, faites chauffer un filet d'huile d'huile d'olive à feu vif.","Faites revenir les ravioles 5 min environ jusqu'à ce qu'elles soient bien dorées. Remuez régulièrement. Salez, poivrez.","Débarrassez-les sur une assiette et gardez la sauteuse pour la suite de la recette.","En parallèle, préparez les légumes."]},{"titre":"Les tomates cerises","items":["Coupez les tomates cerises en 2.","Émincez l'oignon.","Pressez ou hachez l'ail.","Dans la sauteuse des ravioles, faites chauffer de nouveau un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, les tomates cerises et l'ail 10 à 15 min jusqu'à ce que l'oignon soit cuit et que les tomates aient rendu leur jus et compotent légèrement. Salez, poivrez.","Mélangez régulièrement."]},{"titre":"La sauce","items":["Effeuillez et ciselez le basilic.","Une fois les tomates cuites, dans le bol d'un mixeur, déposez la moitié des tomates cerises et le basilic (gardez quelques feuilles pour le dressage).","Mixez le tout jusqu'à obtenir une sauce homogène.","Goûtez et ajoutez un peu de sel si nécessaire.","Dans la sauteuse des tomates cerises, ajoutez les ravioles et la sauce. Mélangez bien pour tout enrober.","Poursuivez la cuisson 1 à 2 min pour réchauffer l'ensemble.","Au moment de servir, parsemez le tout de parmesan et du reste de basilic."]}]},{"id":"16025","nom":"Raviolis ricotta di bufala et épinard, poitrine fumée et crème persillée","image":"images/16025.webp","ingredients":[["poitrine fumée","90 g"],["champignons de Paris blancs","250 g"],["gousse d'ail","0.5"],["fromage blanc","100 g"],["ravioli ricotta di bufala epinard","250 g"],["oignon jaune","0.5"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes et la poitrine fumée","items":["Emincez l'oignon.","Coupez les champignons en tranches.","Coupez la poitrine fumée en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et la poitrine fumée 8 min.","Au bout des 8 min, ajoutez les champignons et poursuivez 10 min environ.","En parallèle, préparez le reste des ingrédients."]},{"titre":"Les raviolis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les raviolis selon les indications du paquet.","Une fois cuits, mélangez-les avec les légumes et la poitrine fumée.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"La crème persillée","items":["Pressez ou hachez l'ail.","Effeuillez et ciselez le persil.","Dans un bol, mélangez le fromage blanc, l'ail et le persil. Salez, poivrez.","Nappez la sauce sur les pâtes au moment de servir."]}]},{"id":"22191","nom":"Rigatonis au poulet, crème de truffe et choux de Bruxelles","image":"images/22191.webp","ingredients":[["rigatoni (200g)","200 g"],["émincés de cuisse de poulet (225g)","225 g"],["choux de Bruxelles (200g)","200 g"],["oignon jaune (55g)","0.5"],["crème à la truffe (120g)","120 g"],["parmigiano reggiano râpé (20g)","20 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les rigatonis et les choux de Bruxelles","items":["Portez à ébullition une casserole d'eau salée.","Coupez les choux de Bruxelles en 2.","Faites cuire les pâtes et les choux de Bruxelles selon le temps indiqué sur le paquet de pâtes.","Avant de les égoutter, réservez un peu d'eau de cuisson.","Égouttez-les.","En parallèle, faites cuire l'oignon et le poulet."]},{"titre":"Le poulet","items":["Emincez l'oignon.","Dans une grande sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon 5 min.","Ajoutez ensuite le poulet et poursuivez la cuisson 4 à 6 min jusqu'à ce qu'il soit cuit à coeur. Salez, poivrez."]},{"titre":"À table !","items":["Lorsque le poulet est cuit, ajoutez la crème à la truffe, les pâtes et les choux de Bruxelles à la sauteuse.","Faites cuire 2 à 3 min, jusqu'à ce que la crème réduise légèrement et enrobe les pâtes. Si nécessaire, ajoutez un peu d'eau de cuisson des pâtes pour détendre et lier la sauce.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez les assiettes de parmesan."]}]},{"id":"21807","nom":"Risotto au saumon fumé et brocoli","image":"images/21807.webp","ingredients":[["saumon fumé (100g)","100 g"],["riz rond blanc (150g)","150 g"],["citron jaune (55g)","0.5"],["parmigiano reggiano râpé (20g)","20 g"],["brocoli (375g)","0.75"]],"cuisine":["sel","poivre","huile d'olive","600 ml eau","0.5 cube bouillon de légumes"],"etapes":[{"titre":"Le risotto et le brocoli","items":["Coupez les bouquets de brocoli en petits morceaux. Épluchez la tige et émincez-la.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir le brocoli 5 min.","Au bout des 5 min, ajoutez le riz et faites-le revenir 2 min pour le nacrer (l'enrober d'huile).","Ajoutez l'eau et le bouillon de légumes émietté. Salez légèrement et poivrez.","Faites cuire à petits bouillons 12 à 15 min à couvert. Remuez régulièrement.","Ajoutez de l'eau en fin de cuisson si nécessaire et poursuivez quelques minutes."]},{"titre":"A table !","items":["Coupez le saumon fumé en morceaux.","Une fois le riz cuit, hors du feu, ajoutez le saumon fumé, le parmesan et mélangez bien.","Astuce : Pour plus d'onctuosité, vous pouvez ajouter une noix de beurre dans le risotto.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez le citron en quartiers.","Arrosez votre plat d'un filet de jus de citron au moment de servir."]}]},{"id":"20126","nom":"Riz au poulet, aubergines mijotées et sauce tomate-teriyaki","image":"images/20126.webp","ingredients":[["aubergine (560g)","2x"],["tomate (100g)","1x"],["concentré de tomates (70g)","70 g"],["haut de cuisse de poulet (225g)","225 g"],["riz concassé du Pendjab (120g)","120 g"],["oignon jaune (110g)","1x"],["sauce teriyaki (24g)","20 ml"],["cébette (16g)","1x"]],"cuisine":["150 ml eau (sauce)","0.25 cube bouillon de poule","1 càc sucre","sel","poivre","huile d'olive"],"etapes":[{"titre":"Le riz","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre. <!-- --> <!-- notionvc: 80bc42ec-b68e-4f77-88ca-0d6484e57eb7 -->","Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, préparez le mijoté."]},{"titre":"Les aubergines","items":["Emincez l'oignon.","Coupez les aubergines en dés.","Coupez la tomate en dés.","Dans une grande cocotte, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon et les aubergines 5 à 10 min pour les dorer. Salez, poivrez.","Ajoutez ensuite la tomate, la moitié du concentré de tomates et environ un demi-verre d'eau. Couvrez et laissez mijoter 25 à 30 min jusqu'à ce que les aubergines soient fondantes.","En parallèle, faites cuire le poulet."]},{"titre":"Le riz au poulet","items":["Épongez la viande à l'aide d'un essuie-tout.","Coupez le poulet en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir le poulet 4 à 6 min jusqu'à ce qu'il soit cuit à coeur (la chair n'est plus rose). Salez, poivrez.","Ensuite, ajoutez le riz et mélangez bien. Maintenez à feu doux pour le garder chaud le temps de préparer la sauce teriyaki."]},{"titre":"La sauce","items":["Dans une petite casserole, mélangez le reste de concentré de tomates, la sauce teriyaki, le sucre, l'eau et le bouillon de poule émietté. Poivrez. Ne salez pas.","Faites chauffer à feu moyen 5 à 10 min jusqu'à ce que la sauce réduise légèrement et soit nappante. Mélangez bien.","Goûtez et ajoutez une pincée de sel si nécessaire.","Retirez la base de la cébette et émincez-la.","Servez le riz au poulet d'un côté de l'assiette et disposez les aubergines à côté.","Nappez le tout de sauce et parsemez de cébette."]}]},{"id":"18534","nom":"Riz cantonais à la poitrine fumée, coriandre et huile de sésame","image":"images/18534.webp","ingredients":[["sauce soja salée","20 ml"],["poitrine fumée","90 g"],["gousse d'ail","0.5"],["huile de sésame toasté","10 ml"],["riz basmati","150 g"],["petits pois conserve","110 g égoutté"],["carotte (120g)","1x"],["coriandre (botte)","0.5"],["cébette (16g)","1x"]],"cuisine":["2 oeuf","huile de cuisson","sel","poivre"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Une fois cuit, égouttez-le et réservez-le au chaud dans la casserole.","Pendant ce temps, réalisez la garniture."]},{"titre":"La garniture","items":["Épluchez et râpez la carotte.","Retirez la base de la cébette et émincez-la.","Pressez ou hachez l'ail.","Coupez la poitrine fumée en morceaux.","Egouttez et rincez les petits pois.","Dans un bol, battez les œufs. Salez, poivrez.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Versez les œufs et remuez régulièrement pendant 2 min de façon à obtenir des œufs brouillés.","Une fois cuits, réservez-les sur une assiette et gardez la sauteuse pour le riz cantonais."]},{"titre":"Le riz cantonais","items":["Dans la même sauteuse que les œufs brouillés, faites chauffer de nouveau un filet d'huile de cuisson à feu vif.","Faites revenir la cébette et la poitrine fumée 5 min. Remuez régulièrement.","Au bout des 5 min, ajoutez le riz cuit, les petits pois, les oeufs brouillés, la carotte, l'ail et la sauce soja. Poivrez. Mélangez bien et faites revenir l'ensemble 2 min à feu moyen.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Ciselez la coriandre (en entier, les tiges se consomment).","Au moment de passer à table, parsemez le riz cantonais de coriandre et arrosez d'huile de sésame."]}]},{"id":"15973","nom":"Riz crémeux au poulet, champignons et parmesan","image":"images/15973.webp","ingredients":[["parmigiano reggiano râpé","15 g"],["aiguillette de poulet","250 g"],["champignons de Paris bruns","200 g"],["riz rond blanc","150 g"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile d'olive","0.5 bouillon de poule (cube)","600 ml eau"],"etapes":[{"titre":"Le poulet et les légumes","items":["Dans une casserole, portez à ébullition l'eau et le bouillon de poule.","Coupez les aiguillettes de poulet en morceaux.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poulet 5 min environ jusqu'à ce qu'il soit cuit (la chair n'est plus rose). Réservez-le.","En parallèle, coupez les champignons en 2 ou 4 s'ils sont trop gros.","Ciselez (dés) l'oignon."]},{"titre":"Le riz crémeux","items":["Dans la même sauteuse, faites chauffer de nouveau un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et les champignons 1 min environ. Ajoutez le riz et faites-le revenir 3 min pour le nacrer (l'enrober d'huile). Versez le bouillon. Salez légèrement et poivrez.","Faites cuire à petits bouillons 15 à 20 min. Remuez régulièrement.","Une fois le tout cuit, ajoutez le poulet et le parmesan dans la sauteuse et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17536","nom":"Riz sauté au brocoli et champignons de Paris","image":"images/17536.webp","ingredients":[["coriandre","qq brins"],["sauce soja salée","20 ml"],["riz basmati","150 g"],["carotte (100g)","1x"],["cébette (16g)","1x"],["noix de cajou","25 g"],["champignons de Paris blancs","250 g"],["gousse d'ail","0.5"],["gingembre","1 à 3 cm"],["huile de sésame toasté","10 ml"],["brocoli","0.5"]],"cuisine":["2 oeuf","huile de cuisson (mélange 4 huiles par exemple)","sel","poivre"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant la cuisson du riz, réalisez la garniture."]},{"titre":"La garniture","items":["Astuce : faites torréfier les noix de cajou à sec 2 min au début dans la sauteuse, puis réservez-les pour parsemer au dressage.","Épluchez et hachez l'ail et le gingembre.","Épluchez et râpez la carotte.","Coupez les champignons de Paris en tranches.","Coupez le bout abîmé de la tige de l'oignon nouveau. Ciselez (dés) le bulbe et émincez la tige, réservez-la pour le dressage.","Coupez de petits bouquets de brocoli. Épluchez la tige et émincez-la.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir le bulbe de l'oignon nouveau, la carotte, les champignons, le brocoli, l'ail et le gingembre 15 à 20 min."]},{"titre":"Le riz sauté et l'oeuf","items":["Lorsque tout est cuit, ajoutez le riz, la sauce soja et l'huile de sésame à la sauteuse des légumes.","Faites revenir 1 à 2 min.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites cuire les œufs au plat 2 à 3 min. Salez, poivrez.","Ciselez la coriandre (en entier les tiges se consomment).","Au moment de servir, déposez les œufs au plat sur le riz et parsemez dessus la tige de l'oignon nouveau, la coriandre et les noix de cajou."]}]},{"id":"19379","nom":"Rösti burger au saumon fumé, sauce fromage blanc aux noix","image":"images/19379.webp","ingredients":[["pain à burger (200g)","2x"],["pomme de terre (220g)","1x"],["fromage blanc","100 g"],["gousse d'ail","0.5"],["saumon fumé","100 g"],["noix sèche (avec coques)","40 g"],["salade","50 g"],["oignon rouge","0.25"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","1 oeuf","3 càs farine","huile de cuisson"],"etapes":[{"titre":"Les röstis","items":["Épluchez et râpez la pomme de terre.","Pressez ou hachez l'ail.","Dans un saladier, mélangez la pomme de terre, l'ail, l’œuf et la farine. Salez, poivrez.","Dans une sauteuse, faites chauffer un bon fond d'huile de cuisson à feu moyen à vif.","A l'aide d'une louche, déposez de la pâte à röstis dans la sauteuse de manière à obtenir un rösti par personne et tassez bien.","Faites cuire les galettes 3 à 5 min de chaque côté (selon l'épaisseur).","Une fois les röstis cuits, déposez-les sur une assiette munie de papier absorbant pour retirer l'excédent d'huile.","En parallèle, préparez la sauce."]},{"titre":"La sauce","items":["Ouvrez et hachez grossièrement les noix.","Faites chauffer une poêle sans matière grasse à feu moyen.","Faites torréfier les noix 2 à 3 min environ.","Une fois les noix torréfiées, dans un bol, mélangez-les avec le fromage blanc. Salez, poivrez."]},{"titre":"Les burgers","items":["Ouvrez les pains à burger en deux et faites-les dorer au grille-pain.","Coupez l'oignon rouge en rondelles.","Coupez le saumon fumé en morceaux.","Sur la base de chaque pain à burger, déposez un peu de fromage blanc aux noix, un rösti, du saumon fumé et de l'oignon rouge.","Refermez les burgers.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"17273","nom":"Rougail mauricien pimenté d'encornets","image":"images/17273.webp","ingredients":[["gousse d'ail","0.5"],["huile pimentée","10 ml"],["riz basmati","150 g"],["poêlée d'encornets piment d'Espelette","200 g"],["pulpe de tomates","400 g"],["paprika fumé (sachet)","0.25"],["gingembre","1 à 3 cm"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile de cuisson (mélange 4 huiles par exemple)","200 ml eau"],"etapes":[{"titre":"Le rougail","items":["Émincez l’oignon.","Dans une cocotte, faites chauffer un filet d’huile de cuisson à feu moyen.","Faites revenir l'oignon 10 min. Remuez régulièrement.","Pendant ce temps, pressez ou hachez l'ail.","Épluchez et hachez finement le gingembre.","Au bout des 10 min, ajoutez l’ail, le gingembre, la pulpe de tomates, le paprika, les encornet et l'eau. Couvrez et poursuivez la cuisson 10 min environ. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Au moment de servir, arrosez votre rougail d'huile pimentée."]}]},{"id":"16540","nom":"Rougail pimenté de lieu noir","image":"images/16540.webp","ingredients":[["oignon jaune (110g)","1x"],["riz basmati","150 g"],["gousse d'ail (6g)","1x"],["citron vert","0.5"],["gingembre","1 à 3 cm"],["piment oiseau (2g)","1x"],["pulpe de tomates","210 g"],["lieu noir","240 g"]],"cuisine":["200 ml eau","huile de cuisson","sel","poivre"],"etapes":[{"titre":"Le poisson","items":["Rincez et essuyez le poisson. Salez et poivrez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poisson 1 à 2 min de chaque côté. Débarrassez-le dans une assiette et réservez la sauteuse pour la sauce.","Pendant ce temps, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant la cuisson du riz, préparez la sauce."]},{"titre":"La sauce","items":["Émincez l’oignon.","Pelez et hachez l'ail et le gingembre.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Dans la sauteuse, faites chauffer un filet d’huile de cuisson à feu moyen à vif.","Faites revenir l'oignon et l'ail 5 min.","Au bout des 5 min de cuisson, ajoutez la pulpe de tomates, le piment oiseau, le gingembre et l'eau. Couvrez et poursuivez la cuisson 10 min supplémentaires.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Lorsque tout est cuit, ajoutez le poisson à la sauteuse et couvrez 2 à 3 min jusqu'à ce qu'il soit chaud et cuit à coeur.","Pendant ce temps, coupez le citron en quartiers.","Astuce : prélevez un peu de zeste de citron et ajoute-les à la avant de servir pour une touche de fraîcheur qui équilibre le piment.","Au moment de servir, nappez votre poisson avec la sauce et versez un filet de jus de citron."]}]},{"id":"18748","nom":"Salade asiatique de nouilles au poulet croustillant panko, vinaigrette pad thaï","image":"images/18748.webp","ingredients":[["carotte (100g)","1x"],["gingembre","1 à 3 cm"],["nouilles asiatiques","120 g"],["citron vert","0.5"],["sauce pad thaï","20 ml"],["chou rouge","250 g"],["aiguillette de poulet La Nouvelle Agriculture","250 g"],["chapelure panko","50 g"],["cacahuètes caramelisées","25 g"]],"cuisine":["poivre","sel","2 càs huile de votre choix (noix, olive, colza, sésame)","1 oeuf","farine","huile de cuisson"],"etapes":[{"titre":"Les nouilles","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet, en remuant régulièrement pour éviter qu’elles ne collent.","Une fois cuites, égouttez-les et passez-les sous l'eau froide pour stopper la cuisson.","Pendant ce temps, préparez le poulet croustillant."]},{"titre":"Le poulet croustillant","items":["Coupez les aiguillettes en 2 ou 3. Salez, poivrez-les.","Dans trois assiettes creuses, déposez un peu de farine, l'oeuf battu et la chapelure panko.","Trempez le poulet successivement dans la farine, l’œuf et la panure pour bien les enrober.","Dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Saisissez le poulet 2 à 3 min de chaque côté jusqu'à ce qu'il soit cuit à coeur (la chair n'est plus rose).","Pendant ce temps, préparez la salade."]},{"titre":"La salade","items":["Pelez et hachez le gingembre.","A l’aide d’une râpe, prélevez des zestes de citron vert (uniquement l’écorce de couleur) et pressez-le.","Épluchez et râpez la carotte.","Retirez les feuilles abîmées du chou rouge et la tige centrale. Émincez les feuilles.","Dans un saladier, déposez les ingrédients suivants :","Versez la sauce pad thaï, l'huile de votre choix, le gingembre, le jus et les zestes de citron. Mélangez bien pour obtenir une vinaigrette. Salez et poivrez.","Ajoutez la carotte, le chou et les nouilles cuites et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Hachez les cacahuètes.","Déposez le poulet pané et parsemez de cacahuètes."]}]},{"id":"15277","nom":"Salade asiatique de nouilles façon pad thaï, coriandre et cacahuètes","image":"images/15277.webp","ingredients":[["gousse d'ail","0.5"],["sauce pad thaï","20 ml"],["cacahuètes grillées sans sel","25 g"],["chou rouge","100 g"],["nouilles asiatiques","120 g"],["oignon rouge","0.25"],["citron vert","0.5"],["coriandre (botte)","0.5"],["radis bleu","0.5"],["carotte orange (100g)","1x"]],"cuisine":["poivre","sel","1 càs huile de votre choix (noix, olive, colza, sésame)"],"etapes":[{"titre":"Les nouilles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet.","Une fois cuites, égouttez-les et passez-les sous l'eau froide pour stopper la cuisson.","Pendant ce temps, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'oignon rouge.","Pressez ou hachez l'ail.","A l’aide d’une râpe, prélevez des zestes de citron vert (uniquement l’écorce de couleur) et pressez-le.","Versez la sauce pad thaï, l'huile de votre choix et mélangez bien pour obtenir une vinaigrette. Salez et poivrez.","Épluchez et râpez la carotte et le radis bleu.","Ciselez la coriandre (en entier, les tiges se consomment).","Retirez les feuilles abîmées du chou rouge et la tige centrale. Émincez les feuilles.","Hachez les cacahuètes.","Ajoutez les nouilles cuites et le sésame noir. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17306","nom":"Salade asiatique de poulet au miel et soja, fèves, concombre et sésame","image":"images/17306.webp","ingredients":[["miel","10 ml"],["sauce soja salée","20 ml"],["nouilles asiatiques","120 g"],["sésame doré","10 g"],["filet de poulet La Nouvelle Agriculture (300g)","2x"],["cébette (16g)","1x"],["oignon rouge","0.25"],["concombre noa (250g)","1x"],["fèves fraîches avec cosses","200 g"]],"cuisine":["sel","poivre","1 càs huile de tournesol (poulet)","2 càs huile de tournesol (salade)"],"etapes":[{"titre":"Le poulet","items":["Coupez les filets de poulet en morceaux.","Dans un bol, mélangez le miel, la sauce soja, l'huile de tournesol et le poulet. Poivrez.","Dans une sauteuse, faites chauffer un filet d'huile de tournesol à feu moyen à vif.","Faites revenir les morceaux de poulet avec la marinade 7 à 10 min. Retournez-les régulièrement jusqu'à ce qu'ils soient cuits à coeur (leur chair n'est plus rose).","En parallèle, faites cuire les nouilles asiatiques et les fèves."]},{"titre":"Les nouilles asiatiques et les fèves","items":["Portez à ébullition une casserole d'eau salée.","Pendant ce temps, écossez les fèves.","Faites cuire les fèves 12 min environ. A mi-cuisson, ajoutez les nouilles.","Une fois le tout cuit, égouttez et passez le tout sous l'eau froide pour stopper la cuisson.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'oignon rouge.","Versez l'huile de tournesol. Salez légèrement, poivrez. Mélangez bien.","Épluchez et coupez le concombre en demi-rondelles.","Retirez la base de la cébette et émincez-la.","Une fois cuits, ajoutez le poulet avec la marinade, les fèves et les nouilles. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez la salade de sésame doré."]}]},{"id":"15886","nom":"Salade asiatique pimentée de boeuf, concombre et cacahuètes","image":"images/15886.webp","ingredients":[["carpaccio tranches rondes","200 g"],["nouilles asiatiques","120 g"],["sauce teriyaki","20 ml"],["gousse d'ail","0.5"],["piment oiseau (2g)","1x"],["carotte (100g)","1x"],["cacahuètes grillées sans sel","25 g"],["concombre noa","0.5"],["sucrine","0.5"],["menthe-coriandre (botte)","0.5"]],"cuisine":["2 càs huile de tournesol","sel","huile de cuisson"],"etapes":[{"titre":"Les nouilles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet.","Une fois cuites, égouttez-les et passez-les sous l'eau froide pour stopper la cuisson.","En parallèle, préparez le reste des ingrédients."]},{"titre":"Le boeuf","items":["Pressez ou hachez l'ail.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'ail et le piment 1 min.","Ensuite, ajoutez les tranches de carpaccio et saisissez-les 30 sec environ de chaque côté. Salez.","Ajustez la cuisson selon votre goût."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Versez l'huile de tournesol et la sauce teriyaki. Mélangez bien.","Épluchez et râpez la carotte.","Épluchez et coupez le concombre en demi-rondelles.","Hachez grossièrement les cacahuètes.","Effeuillez la menthe.","Ciselez la coriandre (en entier, les tiges se consomment) et la menthe.","Ajoutez les nouilles refroidies et le carpaccio de boeuf. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez la base de la sucrine et émincez-la.","Dans des assiettes, déposez au fond la salade. Répartissez dessus la salade de nouilles asiatiques."]}]},{"id":"21205","nom":"Salade BLT (Bacon Laitue et Tomate)","image":"images/21205.webp","ingredients":[["poitrine fumée (90g)","90 g"],["baguette tradition (135g)","135 g"],["oignons frits (sachet) (8g)","1x"],["sucrine (100g)","1x"],["persil plat (5g)","qq brins"],["parmigiano reggiano râpé (20g)","20 g"],["tomate (100g)","1x"],["concombre noa (125g)","0.5"],["échalote (12.5g)","0.5"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"La poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Faites chauffer une sauteuse sans matière grasse à feu vif.","Faites dorer la poitrine fumée 3 à 5 min. Remuez régulièrement.","Une fois cuite, réservez la poitrine fumée et gardez la sauteuse.","En parallèle, préparez les croûtons."]},{"titre":"Les croûtons","items":["Effeuillez et ciselez le persil.","Coupez la baguette en dés.","Dans la même sauteuse que la poitrine fumée, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les croûtons 5 à 10 min jusqu'à ce qu'ils soient croustillants. En fin de cuisson, ajoutez le persil, le sel, le poivre et mélangez bien.","Pendant ce temps, préparez la salade."]},{"titre":"La salade BLT","items":["Ciselez (dés) l'échalote.","Retirez la base de la sucrine et émincez-la.","Épluchez et coupez le concombre en demi-rondelles.","Coupez la tomate en dés.","Dans un saladier, versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ajoutez l'échalote, la sucrine, le concombre, la tomate, la poitrine fumée, les oignons frits et les croûtons. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez la salade de parmesan."]}]},{"id":"19380","nom":"Salade californienne de quinoa, avocat, kiwi et cranberries","image":"images/19380.webp","ingredients":[["fromage blanc","50 g"],["cranberries","25 g"],["noix de pécan","25 g"],["avocat (180g)","1x"],["pomme","0.5"],["pousses d'épinards","50 g"],["kiwi vert (73g)","1x"],["ciboulette","qq brins"],["quinoa blanc","150 g"]],"cuisine":["sel","poivre","3 càs huile d'olive","2 càs vinaigre de votre choix","1 càc moutarde"],"etapes":[{"titre":"Le quinoa","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le quinoa selon les indications du paquet.","Égouttez le quinoa et laissez-le refroidir.","Astuce : après l’avoir égoutté, ne rincez pas le quinoa (il retiendrait l’eau de rinçage et rendrait la salade trop aqueuse). Laissez-le simplement refroidir à température ambiante.","Pendant la cuisson du quinoa, préparez la salade."]},{"titre":"La salade","items":["Coupez l'avocat en tranches.","Coupez le kiwi en morceaux.","Coupez la pomme en fins quartiers.","Hachez les cranberries et les noix de pécan.","Ciselez la ciboulette.","Dans un saladier, versez l’huile d’olive et le vinaigre. Ajoutez la moutarde et le fromage blanc. Salez, poivrez. Mélangez pour obtenir une vinaigrette.","Ajoutez les pousses d'épinards et le quinoa refroidi (il peut se servir encore un peu tiède). Mélangez bien.","Déposez les pousses d'épinards et le quinoa assaisonnés dans des bols.","Répartissez l'avocat, le kiwi et la pomme par-dessus.","Parsemez de cranberries, de noix et de ciboulette."]}]},{"id":"16353","nom":"Salade de boulgour, courgette et poulet au gingembre","image":"images/16353.webp","ingredients":[["filet de poulet (300g)","2x"],["courgette (200g)","1x"],["citron vert","0.5"],["échalote","0.5"],["cerfeuil","qq brins"],["gingembre","1 à 3 cm"],["pousses d'épinards","50 g"],["boulgour","120 g"]],"cuisine":["2 càs huile d'olive","sel","poivre"],"etapes":[{"titre":"Le boulgour","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire le boulgour selon les indications du paquet.","Une fois cuit, égouttez-le et passez-le sous l'eau froide pour le refroidir.","En parallèle, faites cuire le poulet."]},{"titre":"La cuisson du poulet","items":["Pelez et hachez finement le gingembre.","Coupez les filets de poulet en lanières.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poulet avec le gingembre 5 min environ. Remuez régulièrement. Salez, poivrez.","Pendant ce temps, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'échalote.","Pressez le citron.","Versez l'huile d'olive. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Épluchez et râpez la courgette.","Effeuillez le cerfeuil.","Ajoutez les pousses d'épinards, le boulgour et le poulet au gingembre. Mélangez bien."]}]},{"id":"13725","nom":"Salade de boulgour, poulet au zaatar, concombre et tomates cerises","image":"images/13725.webp","ingredients":[["mélange zaatar (sachet)","0.5"],["céleri branche (50g)","1x"],["citron jaune (185g)","1x"],["concombre","0.5"],["échalote","0.5"],["boulgour","150 g"],["aiguillette de poulet La Nouvelle Agriculture","250 g"],["tomate cerise","100 g"]],"cuisine":["2 cs huile d'olive","sel","poivre"],"etapes":[{"titre":"Le boulgour","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le boulgour selon les indications du paquet.","En parallèle, préparez le poulet."]},{"titre":"Le poulet au zaatar","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les aiguillettes de poulet avec le zaatar 5 min jusqu'à ce qu'elles soient cuites à coeur (la chair n'est plus rose). Retournez-les régulièrement. Salez, poivrez.","Pendant ce temps, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","A l'aide d'une râpe, prélevez les zestes de citron (que l'écorce de couleur) et pressez-le.","Ajoutez l'huile d'olive, salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ciselez (dés) l'échalote.","Retirez le bout abîmé du céleri branche et émincez-le.","Coupez les tomates cerises en 2.","Épluchez et coupez le concombre en petits dés.","Ajoutez le boulgour. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez le poulet en morceaux et déposez-les sur la salade."]}]},{"id":"17785","nom":"Salade de brocoli, poitrine fumée, oeuf mollet et amandes","image":"images/17785.webp","ingredients":[["poitrine fumée","90 g"],["amandes effilées","15 g"],["brocoli","0.5"],["tomate ronde (160g)","2x"],["sucrine (170g)","1x"],["oignon rouge","0.25"]],"cuisine":["sel","poivre","1 càs vinaigre de votre choix","2 oeuf","2 càs huile d'olive","1 càc moutarde"],"etapes":[{"titre":"Les oeufs mollets","items":["Portez à ébullition une casserole d'eau.","Faites cuire les oeufs 6 min.","Une fois cuits, réservez-les dans un bol d'eau froide pour stopper la cuisson.","Ecalez les oeufs délicatement au moment de servir.","Pendant ce temps, préparez le brocoli."]},{"titre":"Le brocoli","items":["Portez à ébullition une seconde casserole d'eau salée.","En parallèle, coupez les bouquets de brocoli. Épluchez la tige et émincez-la.","Faites cuire le brocoli 5 à 10 min selon la cuisson désirée. Une fois cuit, égouttez-le et laissez-le tiédir à température ambiante.","Pendant ce temps, préparez les amandes et la poitrine fumée."]},{"titre":"Les amandes et la poitrine fumée","items":["Faites chauffer une poêle sans matière grasse à feu moyen à vif.","Faites torréfier les amandes effilées 2 à 5 min. Remuez régulièrement. Réservez-les dans une assiette.","En parallèle, coupez la poitrine fumée en morceaux.","Dans la même poêle, faites dorer la poitrine fumée 5 min. Remuez régulièrement."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'oignon.","Ajoutez la moutarde, l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Coupez les tomates en dés.","Coupez la base de la sucrine et émincez-la.","Ajoutez le brocoli, la poitrine fumée et les amandes. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, déposez un oeuf mollet au milieu de chaque assiette."]}]},{"id":"21210","nom":"Salade de concombre et courgette au piment chipotle, yaourt grec et aneth","image":"images/21210.webp","ingredients":[["baguette tradition (135g)","135 g"],["sauce soja salée (23g)","20 ml"],["piment chipotle (pincée) (0.8g)","1x"],["aneth (10g)","0.5"],["oignon rouge (27.5g)","0.25"],["concombre noa (500g)","2x"],["courgette (200g)","1x"],["citron jaune (50g)","0.5"],["gousse d'ail (2g)","0.5"],["sésame doré (10g)","10 g"],["yaourt à la grecque (200g)","200 g"]],"cuisine":["2 càs huile d'olive","sel","poivre"],"etapes":[{"titre":"Les croûtons","items":["Coupez la baguette en dés.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu vif.","Faites dorer la baguette 5 min jusqu'à ce que les croûtons soient bien croustillants. Salez. Remuez régulièrement.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Pressez ou hachez l'ail.","Pressez le citron.","Effeuillez et ciselez l'aneth (réservez-en un peu pour la sauce).","Émincez l'oignon.","Épluchez et coupez les concombres en bâtonnets.","Coupez la courgette en fines demi-rondelles.","Dans un saladier, versez l'huile d'olive, la sauce soja, l'ail, le jus de citron et le piment chipotle. Mélangez bien pour obtenir une vinaigrette. Le piment est fort, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût.","Astuce : vous pouvez remplacez votre huile par de l'huile de colza, de noix ou de lin pour complétez vos apports journaliers en oméga 3.<!-- notionvc: 939f7f84-45d3-46d5-be5c-93f36de074d5 -->","Ajoutez l'oignon, les concombres, la courgette et l'aneth dans le saladier et mélangez bien pour tout enrober de vinaigrette.","Goûtez et ajoutez du sel et du jus de citron si nécessaire."]},{"titre":"A table !","items":["Dans un bol, mélangez le yaourt à la grecque et le reste d'aneth. Salez, poivrez.","Dans des assiettes creuses, étalez un peu de sauce au yaourt dans le fond.","Déposez par-dessus la salade et les croûtons. Nappez le tout avec le reste de sauce.","Parsemez de sésame doré."]}]},{"id":"18303","nom":"Salade de kaki, burrata, roquette et pignons de pin","image":"images/18303.webp","ingredients":[["burrata (100g)","1x"],["quinoa blanc","150 g"],["vinaigre balsamique","20 ml"],["pignon de pin","15 g"],["kaki","0.5"],["betterave cuite","200 g"],["échalote","0.5"],["roquette","50 g"]],"cuisine":["sel","poivre","2 càs huile d'olive"],"etapes":[{"titre":"Le quinoa","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le quinoa selon les indications du paquet.","Une fois cuit, égouttez-le et laissez-le refroidir dans la passoire.","Astuce : après l’avoir égoutté, ne rincez pas le quinoa (il retiendrait l’eau de rinçage et rendrait la salade trop aqueuse). Laissez-le simplement refroidir à température ambiante.","Pendant la cuisson du quinoa préparez le reste des ingrédients."]},{"titre":"La salade","items":["Astuce : pour plus de saveur et de croquant, faites torréfier les pignons de pin dans une poêle quelques minutes à feu moyen, sans matière grasse.","Ciselez (dés) l'échalote.","Coupez la betterave et le kaki en dés.","Dans un saladier, mélangez l'huile d'olive, l'échalote, le quinoa et la roquette. Salez, poivrez.","Dans des bols ou assiettes creuses, répartissez le mélange de quinoa / roquette. Répartissez les dés de kaki et de betterave par-dessus.","Déposez la burrata, arrosez de vinaigre balsamique et parsemez de pignons de pin. Salez, poivrez."]}]},{"id":"21884","nom":"Salade de lentilles & féta, citron et pignons torréfiés","image":"images/21884.webp","ingredients":[["lentilles en conserve (g égoutté) (265g)","265x"],["oignon rouge (20g)","0.25"],["endive (110g)","1x"],["carotte (200g)","2x"],["pignon de pin (15g)","15 g"],["féta (80g)","80 g"],["citron jaune (55g)","0.5"],["cranberries (25g)","25 g"],["pousses d'épinards (50g)","50 g"]],"cuisine":["3 càs huile d'olive","sel","poivre"],"etapes":[{"titre":"La salade","items":["Ciselez (dés) l'oignon rouge.","Pressez le citron.","Épluchez et râpez les carottes.","Égouttez et rincez les lentilles.","Émiettez la féta.","Retirez la base de l'endive. Coupez-la en 2 et retirez la partie centrale dure. Émincez-la.","Dans un saladier, mélangez le jus de citron et l'huile d'olive pour obtenir une vinaigrette. Salez, poivrez.","Ajoutez les pousses d'épinards, l’oignon rouge, les carottes, l'endive, les lentilles et la féta. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez les cranberries et les pignons de pin sur la salade."]}]},{"id":"19700","nom":"Salade de lentilles, avocat, noisettes et féta","image":"images/19700.webp","ingredients":[["lentilles en conserve (g égoutté) (265g)","265x"],["noisettes","25 g"],["avocat (180g)","1x"],["concombre noa (250g)","1x"],["persil plat","qq brins"],["féta","100 g"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"La salade","items":["Astuce : Pour révéler pleinement leurs arômes, faites torréfier les noisettes à sec dans une poêle chaude pendant quelques minutes, en remuant régulièrement. Elles dégageront une odeur plus intense et apporteront plus de profondeur aux saveurs de votre plat.Effeuillez et ciselez le persil.","Hachez grossièrement les noisettes.","Épluchez et coupez le concombre en dés.","Émiettez la féta.","Coupez l'avocat en dés.","Égouttez et rincez les lentilles.","Dans un saladier, versez l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Astuce : Pour donner du peps à votre vinaigrette, ajoutez une cuillère de moutarde.","Ajoutez les noisettes, le concombre, la féta, l'avocat et les lentilles.","Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"15384","nom":"Salade de lentilles, dinde au curry de France et mimolette","image":"images/15384.webp","ingredients":[["escalope de dinde (240g)","2x"],["lentilles blondes","150 g"],["curry de France (sachet)","0.5"],["carotte (100g)","1x"],["échalote","0.5"],["céleri branche (50g)","1x"],["mimolette jeune au lait de vache pasteurisé","60 g"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix","1 càc moutarde"],"etapes":[{"titre":"Les lentilles blondes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les lentiles selon les indications du paquet.","Pendant ce temps, faites cuire la dinde au curry."]},{"titre":"La dinde au curry","items":["Coupez la dinde en aiguillettes.","Dans une sauteuse, faites chauffer une filet d'huile d'olive à feu moyen à vif.","Faites revenir les aiguillettes de dinde avec le curry 5 min environ jusqu'à ce qu'elle soit cuite à coeur (la chair n'est plus rose). Salez, poivrez."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'échalote.","Versez l'huile d'olive, la moutarde et le vinaigre. Salez, poivrez. Mélangez bien jusqu'à obtenir une vinaigrette.","Épluchez et réalisez des tagliatelles de carotte à l'aide d'un économe.","Émincez le céleri branche.","Coupez la mimolette en morceaux.","Ajoutez la dinde et les lentilles cuites. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"","items":["Servez sans attendre votre salade de lentilles, dinde au curry et mimolette !"]}]},{"id":"17283","nom":"Salade de lentilles, poulet au curry fort et mimolette","image":"images/17283.webp","ingredients":[["curry jaune fort (sachet)","0.5"],["carotte (100g)","1x"],["mimolette jeune au lait de vache pasteurisé","60 g"],["aiguillette de poulet La Nouvelle Agriculture","250 g"],["lentilles blondes","150 g"],["échalote","0.5"],["céleri branche (50g)","1x"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix","1 càc moutarde"],"etapes":[{"titre":"Les lentilles blondes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les lentilles selon les indications du paquet.","Pendant ce temps, faites cuire la dinde au curry."]},{"titre":"Le poulet au curry","items":["Redécoupez les aiguillettes de poulet.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poulet et le curry 5 min environ jusqu'à ce qu'il soit cuit à coeur (la chair n'est plus rose). Salez, poivrez."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'échalote.","Versez l'huile d'olive, la moutarde et le vinaigre. Salez, poivrez. Mélangez bien jusqu'à obtenir une vinaigrette.","Épluchez et réalisez des tagliatelles de carotte à l'aide d'un économe.","Émincez le céleri branche.","Coupez la mimolette en morceaux.","Ajoutez le poulet et les lentilles cuites. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"19692","nom":"Salade de pâtes perlées à la truite fumée, concombre et aneth","image":"images/19692.webp","ingredients":[["fromage blanc","100 g"],["truite fumée","100 g"],["pâtes perlées","200 g"],["citron","0.5"],["aneth","qq brins"],["échalote","0.5"],["pousses d'épinards","50 g"],["concombre noa (250g)","1x"]],"cuisine":["2 càs huile d'olive","sel","poivre"],"etapes":[{"titre":"Les pâtes","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Une fois cuites, égouttez-les et rincez-les à l'eau froide pour les refroidir.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"La salade","items":["Pressez le citron.","Ciselez (dés) l'échalote.","Effeuillez et ciselez l'aneth.","Dans un saladier, ajoutez le fromage blanc, l'échalote et l'aneth.","Versez l'huile d'olive et le jus de citron. Salez, poivrez et mélangez bien.","Coupez la truite fumée en morceaux.","Épluchez et coupez le concombre en dés.","Ajoutez les pousses d'épinards et les pâtes perlées refroidies. Mélangez.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"21289","nom":"Salade de pâtes perlées au saumon fumé, concombre et aneth","image":"images/21289.webp","ingredients":[["céleri branche (50g)","1x"],["concombre noa (250g)","1x"],["échalote (12.5g)","0.5"],["amandes effilées (15g)","15 g"],["pâtes perlées (200g)","200 g"],["citron jaune (50g)","0.5"],["aneth (10g)","0.5"],["saumon fumé (100g)","100 g"]],"cuisine":["2 càs huile d'olive","sel","poivre"],"etapes":[{"titre":"Les pâtes perlées","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes perlées selon les indications du paquet.","Une fois cuites, égouttez-les et passez-les sous l'eau froide.","Astuce : rincez les pâtes à l'eau froide après cuisson pour les refroidir rapidement et éviter qu'elles ne collent dans la salade.","En parallèle, préparez le reste des ingrédients."]},{"titre":"La salade","items":["Ciselez (dés) l'échalote.","Retirez le bout abîmé du céleri branche et émincez-le.","Épluchez le concombre et coupez-le en petits dés.","Coupez le saumon fumé en morceaux.","Effeuillez et ciselez l'aneth.","Pressez le citron.","Dans un saladier, versez l'huile d'olive et le jus de citron. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Ajoutez l'échalote, le céleri, le concombre, le saumon fumé, l'aneth, les pâtes perlées et les amandes. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"14890","nom":"Salade de pois chiches rôtis aux épices grillées, féta et orange","image":"images/14890.webp","ingredients":[["féta","80 g"],["pois chiches conserve","200 g"],["petit pain de seigle (160g)","2x"],["mélange d'épices grillées (sachet)","0.5"],["roquette","50 g"],["carotte (100g)","1x"],["orange (200g)","1x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","2 cs huile d'olive","1 cs vinaigre de votre choix"],"etapes":[{"titre":"Les pois chiches rôtis et les croûtons","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, rincez et égouttez les pois chiches.","Coupez les petits pains de seigle en morceaux.","Déposez les pois chiches et les croûtons sur une plaque allant au four.","Versez un filet d'huile d'olive, salez, poivrez. Ajoutez le mélange d'épices grillées sur les pois chiches. Mélangez bien pour tout enrober.","Enfournez le tout 5 à 8 min jusqu'à ce que les croûtons soient dorés.","Pendant ce temps, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Épluchez et râpez la carotte.","Émiettez la féta.","Posez l'orange à plat. Coupez les extrémités. Avec un couteau tranchant en épousant la forme du fruit, retirez la peau et les membranes blanches autour de l'agrume. Tenez ensuite l'agrume dans le creux de la main et passez votre couteau entre chaque membrane pour détacher la moitié des tranches (segments). Une fois les tranches retirées, pressez le reste pour récupérer le jus.","Effeuillez et ciselez le persil.","Ajoutez la roquette, les pois chiches rôtis et les croûtons. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"21814","nom":"Salade de poulet et kiwi à la féta","image":"images/21814.webp","ingredients":[["boulgour (120g)","120 g"],["dés de filet de poulet (240g)","240 g"],["kiwi vert (80g)","1x"],["féta (100g)","100 g"],["menthe (5g)","qq brins"],["endive (110g)","1x"],["échalote (12.5g)","0.5"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre (blanc ou de cidre)"],"etapes":[{"titre":"Le boulgour","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Portez à ébullition une casserole d'eau salée.","Faites cuire le boulgour selon les indications du paquet.","Astuce : le boulgour se gorge d'eau à la cuisson, égouttez-le donc bien avant de l'utiliser, sinon la salade sera plus fade.","Pendant la cuisson du boulgour, faites cuire le poulet."]},{"titre":"Le poulet","items":["Épongez la viande à l'aide d'un essuie-tout. Salez, poivrez.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les dés de poulet 5 min environ, jusqu'à ce qu'ils soient bien dorés et cuit à coeur (la chair n'est plus rose). Mélangez régulièrement.","Si nécessaire, faites-les cuire en plusieurs fois afin qu'ils puissent bien dorer."]},{"titre":"La salade","items":["Ciselez (dés) l'échalote.","Épluchez et coupez le kiwi en dés.","Retirez la base de l'endive. Coupez-la en 2 et retirez la partie centrale dure. Émincez-la.","Effeuillez et ciselez la menthe.","Émiettez la féta.","Dans un saladiern versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ajoutez l'échalote, le kiwi, l'endive la menthe, la féta, le boulgour et le poulet.","Mélangez bien, goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17203","nom":"Salade de quinoa, fenouil et pomme au manouri","image":"images/17203.webp","ingredients":[["manouri","100 g"],["quinoa blanc","150 g"],["menthe","qq brins"],["pomme (125g)","1x"],["échalote","0.5"],["bulbe de fenouil (180g)","1x"]],"cuisine":["sel","poivre","3 càs huile d'olive","2 càs vinaigre de votre choix"],"etapes":[{"titre":"Le quinoa","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le quinoa selon les indications du paquet.","Pendant la cuisson du quinoa, faites cuire le manouri."]},{"titre":"Le manouri","items":["Coupez le manouri en tranches.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le manouri 2 à 3 min sur chaque face jusqu'à ce qu'il soit doré. Poivrez."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'échalote.","Versez l'huile d'olive et le vinaigre. Salez et poivrez. Mélangez bien pour obtenir une vinaigrette.","Coupez la pomme en morceaux.","Coupez la base et les tiges à ras du bulbe de fenouil. Retirez la partie dure au centre et émincez le reste.","Effeuillez et ciselez la menthe.","Ajoutez le manouri et le quinoa. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"16893","nom":"Salade de riz à la cantonaise (poitrine fumée et coriandre fraîche)","image":"images/16893.webp","ingredients":[["sauce soja salée","20 ml"],["poitrine fumée","90 g"],["riz basmati","150 g"],["gousse d'ail","0.5"],["cacahuètes grillées sans sel","25 g"],["carotte (200g)","2x"],["cébette (16g)","1x"],["coriandre (botte)","0.5"],["petits pois (avec cosses)","300 g"]],"cuisine":["1 oeuf","huile de cuisson","sel","poivre","1 eau (càs)"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Pendant ce temps, écossez les petits pois.","Faites cuire le riz et les petits pois selon les indications du paquet de riz.","Une fois le tout cuit, passez-les sous l'eau froide pour les refroidir.","Pendant ce temps, préparez la garniture."]},{"titre":"L'oeuf brouillé et la poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites dorer la poitrine fumée 5 min environ.","Une fois cuite, débarrassez-la et conservez la poêle.","Pendant ce temps, battez l'oeuf dans un bol. Salez, poivrez.","Versez l'oeuf dans la poêle et remuez régulièrement pendant 2 min de manière à obtenir un oeuf brouillé.","Une fois cuit, réservez-le."]},{"titre":"La sauce","items":["Dans un bol, déposez les ingrédients suivants :","Retirez la base de la cébette et émincez-la.","Pressez ou hachez l'ail.","Ajoutez la sauce soja et l'eau. Poivrez. Mélangez bien."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Épluchez et râpez les carottes.","Ciselez la coriandre (en entier, les tiges se consomment).","Hachez grossièrement les cacahuètes.","Ajoutez le riz, les petits pois, l’œuf, la poitrine fumée et la sauce. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"11061","nom":"Salade de riz aux maquereaux, poivron et raisins secs","image":"images/11061.webp","ingredients":[["riz basmati","150 g"],["citron jaune","0.5"],["filet de maquereau fumé nature","200 g"],["amandes effilées","15 g"],["raisin sec sultana","25 g"],["tomate (100g)","1x"],["poivron rouge","0.5"]],"cuisine":["sel","poivre","1 càs vinaigre de votre choix","2 càs huile d'olive"],"etapes":[{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Une fois cuit, passez-le sous l'eau froide pour le refroidir.","Pendant ce temps, préparez les amandes."]},{"titre":"Les amandes torréfiées","items":["Dans une poêle sans matière grasse, faites dorer les amandes 1 à 2 min à feu moyen, en remuant régulièrement.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","À l'aide d'une râpe, prélevez les zestes du citron (uniquement l'écorce de couleur) puis pressez-le.","Versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Astuce : Si vous aimez, ajoutez un filet de miel ou un peu de moutarde dans la vinaigrette pour adoucir l’amertume du maquereau.","Coupez le poivron et la tomate en petits dés.","Retirez la peau et les éventuelles arêtes du maquereau. Coupez-les en morceaux.","Hachez grossièrement les amandes torréfiées.","Ajoutez les raisins secs et le riz. Salez, poivrez. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17400","nom":"Salade de roquette au chorizo, oeuf dur et grana padano","image":"images/17400.webp","ingredients":[["chorizo","80 g"],["roquette","100 g"],["tomate (200g)","2x"],["grana padano au lait cru","20 g"],["oignon rouge","0.25"],["concombre noa (250g)","1x"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix","2 oeuf"],"etapes":[{"titre":"Les oeufs durs","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les œufs 9 min.","Quand ils sont cuits, plongez-les dans l'eau froide pour stopper la cuisson et écalez-les délicatement.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'oignon.","Versez l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Épluchez et coupez le concombre en dés.","Coupez les tomates en fins quartiers.","A l'aide d'un économe, réalisez des copeaux de grana padano.","Coupez le chorizo et les œufs durs en 4.","Ajoutez la roquette et mélangez délicatement le tout.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"15569","nom":"Salade de saumon, pommes de terre, pousses d'épinards et sauce à l'estragon","image":"images/15569.webp","ingredients":[["pavé de saumon","240 g"],["pomme de terre (440g)","2x"],["estragon séché (sachet)","0.25"],["gousse d'ail","0.5"],["oignon rouge","0.25"],["pousses d'épinards","50 g"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"Les pommes de terre","items":["Epluchez et coupez les pommes de terre en morceaux.","Déposez-les dans une casserole et recouvrez-les très largement d'eau. Salez.","Faites-les cuire 12 min environ jusqu’à ce qu’elles soient tendres mais pas réduites en purée.","Pendant ce temps, faites cuire le saumon."]},{"titre":"Le saumon","items":["Rincez et essuyez les pavés de saumon. Salez et poivrez-les.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites dorer les pavés de saumon 2 à 3 min de chaque côté (côté peau en premier).","Astuce : pour savoir quand retourner le saumon, regardez sur le côté du pavé : lorsqu'il est cuit à mi-hauteur, retournez-le.","Une fois cuits, retirez la peau et coupez-les en morceaux.","En parallèle, préparez la sauce et la salade."]},{"titre":"La sauce à l'estragon","items":["Dans un bol, déposez les ingrédients suivants :","Pressez ou hachez l'ail.","Ajoutez l'estragon, l'huile d'olive et le vinaigre.","Salez, poivrez et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'oignon rouge.","Ajoutez les pousses d'épinards, le saumon et les pommes de terre refroidis. Mélangez bien."]},{"titre":"","items":["Servez sans attendre votre salade de saumon nappée de la sauce à l'estragon !"]}]},{"id":"21034","nom":"Salade lyonnaise aux lardons fumés végétaux et oeuf mollet","image":"images/21034.webp","ingredients":[["baguette tradition (135g)","135 g"],["oignon rouge (20g)","0.25"],["persil plat (5g)","qq brins"],["lardons végétaux fumés (100g)","100 g"],["tomate cerise (200g)","200 g"],["salade (50g)","50 g"]],"cuisine":["sel","poivre","huile d'olive","2 oeuf","1 càs vinaigre de votre choix","2 càs huile d'olive","1 càs moutarde","20 mL eau (mL)","beurre"],"etapes":[{"titre":"Les pickles d'oignon","items":["Émincez l'oignon.","Dans une casserole, portez à ébullition l'eau et le vinaigre. Mélangez bien.","Hors du feu, ajoutez l'oignon et laissez reposer le temps de la recette.","Pendant ce temps, préparez les croûtons et les lardons végétaux."]},{"titre":"Les croûtons et les lardons","items":["Coupez la baguette en petits dés.","Dans une grande sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les lardons végétaux 5 min. Réservez-les sur une assiette.","Faites chauffer de nouveau un filet d'huile d'olive et une noix de beurre à feu vif.","Faites revenir les croûtons 5 min jusqu'à ce qu'ils soient dorés. Baissez le feu à mi-cuisson et remuez régulièrement.","Une fois les croûtons dorés, ajoutez les lardons et maintenez au chaud (à feu très doux).","En parallèle, réalisez les oeufs."]},{"titre":"Les oeufs mollets","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les oeufs 6 min.","Une fois cuits, réservez-les dans un bol d'eau froide pour stopper la cuisson.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez la moutarde, l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Astuce : multipliez les quantités de vinaigrette pour une salade plus gourmande.","Coupez les tomates en 2 ou 4 si elles sont trop grosses.","Effeuillez et ciselez le persil.","Ajoutez la salade, les croûtons et lardons végétaux. Mélangez bien.","Goûtez et ajoutez une pincée de sel si nécessaire.","Écalez les oeufs.","Servez sans attendre la salade lyonnaise aux lardons végétaux parsemée des pickles et l'oeuf mollet au centre."]}]},{"id":"17093","nom":"Salade mexicaine de haricots rouges, maïs, concombre et cheddar","image":"images/17093.webp","ingredients":[["mélange tex-mex (sachet) (6g)","1x"],["maïs en conserve","50 g égoutté"],["haricots rouges conserve","50 g égoutté"],["cheddar en bloc","60 g"],["boulgour","100 g"],["concombre noa (250g)","1x"],["oignon rouge","0.25"],["coriandre","qq brins"],["citron vert (90g)","1x"]],"cuisine":["sel","poivre","3 càs huile d'olive"],"etapes":[{"titre":"Le boulgour","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le boulgour selon les indications du paquet.","Une fois cuit, égouttez et laissez-le refroidir.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","À l'aide d'une râpe, prélevez les zestes (uniquement l'écorce de couleur) et pressez le citron.","Versez l'huile d'olive. Ajoutez le mélange tex-mex, salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Ciselez (dés) l'oignon.","Épluchez et coupez le concombre en petits dés.","Ciselez la coriandre (en entier les tiges se consomment).","Coupez le cheddar en dés.","Égouttez et rincez le maïs et les haricots rouges.","Ajoutez le boulgour refroidi et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"19746","nom":"Salade tiède de boudin blanc, pomme et endive","image":"images/19746.webp","ingredients":[["graines de courge (15g)","15 g"],["boudin blanc au porto (260g)","2x"],["citron jaune (75g)","0.5"],["endive (110g)","1x"],["sucrine (170g)","1x"],["pomme (125g)","1x"],["baguette tradition (135g)","135 g"]],"cuisine":["sel","poivre","2 càs huile d'olive"],"etapes":[{"titre":"Le boudin et les pommes","items":["Coupez la pomme en fins quartiers.","Coupez les boudins en rondelles.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Saisissez la pomme et les boudins 5 min puis baissez à feu moyen et poursuivez la cuisson 5 à 10 min environ. Salez, poivrez.","Pendant ce temps, préparez les croûtons et le reste des ingrédients."]},{"titre":"Les croûtons","items":["Coupez la baguette en dés.","Dans une seconde sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites dorer la baguette 5 min environ. Salez, poivrez. Remuez régulièrement."]},{"titre":"La salade","items":["Pressez le citron.","Retirez la base de l'endive. Coupez-la en 2 et retirez la partie centrale dure. Émincez-la.","Coupez la base de la sucrine et émincez-la.","Dans un saladier, mélangez le jus de citron et l'huile d'olive jusqu'à obtenir une vinaigrette. Salez, poivrez.","Ajoutez l'endive, la sucrine, les boudins, les croûtons et la pomme.","Au moment de servir, parsemez la salade de graines de courge."]}]},{"id":"18492","nom":"Sandwich au jambon blanc, burrata et sel fumé","image":"images/18492.webp","ingredients":[["baguette tradition","265 g"],["jambon de Paris (tranche) (110g)","2x"],["burrata (100g)","1x"],["concentré de tomates","25 g"],["sel fumé viking","2 pincée"],["salade","50 g"]],"cuisine":["sel","poivre","huile d'olive","1 càc sucre","vinaigre de votre choix","40 g beurre"],"etapes":[{"titre":"La préparation","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, humidifiez légèrement la baguette et déposez-la sur une plaque allant au four.","Faites cuire selon les indications du paquet.","En parallèle, passez le beurre 15 sec au micro-ondes pour le ramollir (il ne doit pas être fondu).","Dans un bol, mélangez le beurre mou, le sucre et le concentré de tomates. Salez, poivrez.","Coupez les tranches de jambon en 2."]},{"titre":"Les sandwichs","items":["Coupez et ouvrez la baguette pour réaliser un sandwich par personne.","Etalez dans chaque demi-baguette le beurre à la tomate.","Répartissez le jambon et déchirez la burrata par-dessus.","Versez un filet d'huile d'olive, parsemez de sel fumé et ajoutez un peu de salade.","Assaisonnez le reste de salade d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"18756","nom":"Saucisse à la forestière (sauce aux champignons et à la crème)","image":"images/18756.webp","ingredients":[["crème","100 g"],["champignons de Paris blancs","250 g"],["gousse d'ail (4g)","1x"],["riz basmati","150 g"],["oignon jaune (110g)","1x"],["persil plat","qq brins"],["saucisse nature (240g) Bleu Blanc Coeur","2x"]],"cuisine":["sel","poivre","huile d'olive","1 càs moutarde"],"etapes":[{"titre":"La sauce forestière","items":["Émincez l'oignon.","Coupez les champignons de Paris en fines tranches.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, l'ail et les champignons 10 min environ jusqu'à ce qu'ils soient grillés. Salez, poivrez.","Astuce : les champignons sont prêts quand ils ont rendu leur eau et commencent à accrocher.","Au bout des 10 min, ajoutez la moutarde et la crème.","Laissez mijoter à feu doux 3 à 7 min jusqu'à ce que la sauce soit nappante.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les saucisses et le riz."]},{"titre":"Les saucisses","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu vif.","Faites cuire les saucisses 10 à 15 min en remuant régulièrement jusqu’à ce qu’elles soient cuites à coeur.","Astuce : grattez le fond de la poêle avec un peu d'eau pour décoller les sucs et versez le tout dans la sauteuse des champignons pour obtenir une sauce encore plus savoureuse."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant ce temps, effeuillez et ciselez le persil.","Au moment de servir, parsemez le tout de persil."]}]},{"id":"16710","nom":"Saucisse du boucher et courgette sautée au citron et à la féta","image":"images/16710.webp","ingredients":[["féta","80 g"],["citron jaune","0.5"],["échalote (25g)","1x"],["courgette (200g)","1x"],["saucisse nature (240g) Bleu Blanc Coeur","2x"],["graines de couscous","150 g"]],"cuisine":["sel","poivre","huile d'olive","200 ml eau"],"etapes":[{"titre":"Les saucisses","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les saucisses 10 à 15 min jusqu'à ce qu'elles soient cuites à coeur (la chair n'est plus rose). Retournez-les régulièrement.","Pendant ce temps, préparez les courgettes."]},{"titre":"La courgette au citron et à la féta","items":["Émincez l'échalote.","A l'aide d'un économe, réalisez des tagliatelles de courgette.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'échalote et la courgette 10 min. Salez, poivrez.","En parallèle, pressez le citron.","Émiettez la féta.","Au bout des 10 min de cuisson, ajoutez le jus de citron et la féta émiettée et poursuivez la cuisson 1 min. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les graines de couscous."]},{"titre":"Les graines de couscous","items":["Portez à ébullition l'eau et dans un récipient déposez les graines de couscous.","Versez l'eau sur les graines de couscous. Couvrez et laissez gonfler 5 min.","Ajoutez-y un filet d'huile d'olive. Salez, poivrez et à l'aide d'une fourchette, égrainez-le (séparez les grains)."]}]},{"id":"18590","nom":"Saucisse du boucher et gnocchis au poireau et sel fumé","image":"images/18590.webp","ingredients":[["gnocchis de pommes de terre fraîches","400 g"],["sel fumé viking (pincée) (1g)","2x"],["saucisse nature (240g) Bleu Blanc Coeur","2x"],["poireau bio (360g)","2x"],["échalote (25g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les poireaux et les gnocchis","items":["Émincez l'échalote.","Coupez et retirez la base des poireaux. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-les.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites cuire les poireaux et l'échalote 10 min environ.","Au bout des 10 min, ajoutez les gnocchis et prolongez la cuisson 10 min environ.","Couvrez à mi-cuisson, jusqu'à ce qu'ils soient dorés et moelleux. Salez avec le sel fumé, poivrez. Remuez régulièrement.","Pendant ce temps, faites cuire les saucisses."]},{"titre":"Les saucisses","items":["Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites cuire les saucisses 10 à 15 min. Retournez-les régulièrement."]}]},{"id":"21369","nom":"Saucisse du boucher, sauce à l'échalote et chou-fleur rôti","image":"images/21369.webp","ingredients":[["crème (100g)","100 g"],["herbes de Provence (sachet) (1g)","0.25"],["saucisse du boucher (240g) Bleu Blanc Coeur","2x"],["échalote (25g)","1x"],["salade (50g)","50 g"],["chou fleur (600g)","1x"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","1 càc moutarde"],"etapes":[{"titre":"Le chou-fleur","items":["Préchauffez le four à 220°C en chaleur tournante !","Pendant ce temps, retirez les feuilles et le pied abîmé du chou-fleur. Coupez-le en petits bouquets. Épluchez la tige et émincez-la.","Déposez le chou-fleur sur une plaque allant au four. Versez un filet d'huile d'olive. Salez, poivrez et mélangez bien pour tout enrober.","Enfournez 20 à 25 min jusqu'à ce que le chou-fleur soit tendre et légèrement doré.","Astuce : Si le chou-fleur dore trop rapidement, recouvrez votre plat de papier aluminium. Cela permettra une cuisson uniforme sans brûler le dessus.","En parallèle, préparez les saucisses."]},{"titre":"Les saucisses","items":["Coupez l'échalote en 4.","Déposez-la dans un plat allant au four avec les saucisses.","Versez un filet d'huile d'olive et parsemez d'herbes de Provence.","Mélangez bien pour tout enrober et enfournez 20 à 25 min jusqu'à ce que les saucisses soient cuites à coeur (la chair n'est plus rose) en même temps que le chou-fleur.","Astuce : ajoutez un fond d'eau pendant la cuisson."]},{"titre":"La sauce","items":["Lorsque les saucisses sont cuites, retirez-les du plat et réservez-les sur une assiette recouverte de papier aluminium pour les maintenir au chaud.","Ajoutez la crème et la moutarde dans le plat avec l'échalote.","Mélangez bien pour décoller les sucs puis enfournez de nouveau jusqu'à ce que la crème réduise et soit nappante.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Assaisonnez la salade d'un filet d'huile d'olive et de vinaigre.","Au moment de servir, nappez votre saucisse de sauce et accompagnez-la du chou-fleur rôti et de la salade."]}]},{"id":"15964","nom":"Saumon et orzo à la crème citronnée","image":"images/15964.webp","ingredients":[["gousse d'ail","0.5"],["citron jaune","0.5"],["pavés de saumon","240 g"],["pâtes orzo","200 g"],["crème","100 g"],["échalote (25g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"L'orzo","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire l'orzo selon les indications du paquet.","En parallèle, faites cuire le saumon et réalisez la sauce."]},{"titre":"Le saumon","items":["Rincez et essuyez les pavés de saumon.","Dans une poêle, faites chauffer un filet d’huile d’olive à feu moyen à vif.","Faites cuire les pavés de saumon 2 à 3 min de chaque côté en commençant par le côté peau. Salez, poivrez.","Astuce : Pour savoir quand les retourner, regardez sur le côté : lorsqu’ils sont cuits à mi-hauteur, retournez-les !","Une fois cuit, retirez la peau du saumon et coupez-le en gros dés.","En parallèle, réaliser la sauce."]},{"titre":"La sauce","items":["Pressez le citron jaune.","Pressez ou hachez l'ail.","Ciselez (dés) l'échalote.","Dans une petite casserole, versez la crème et portez à ébullition.","Ajoutez l'ail, l'échalote et le jus de citron. Salez et poivrez. Poursuivez la cuisson à feu doux 2 min environ.","Une fois la sauce prête, versez-la dans la casserole de l'orzo avec les dés de saumon.","Faites chauffer le tout 1 min à feu doux pour tout enrober."]}]},{"id":"21938","nom":"Saumon fumé, courgette et orzo citronné","image":"images/21938.webp","ingredients":[["citron jaune (55g)","0.5"],["crème (100g)","100 g"],["échalote (25g)","1x"],["pâtes orzo (200g)","200 g"],["courgette (400g)","2x"],["saumon fumé (100g)","100 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La garniture","items":["Émincez l'échalote.","Coupez les courgettes en demi-rondelles.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'échalote et les courgettes 10 à 15 min jusqu'à ce que les courgettes soient fondantes. Poivrez.","Astuce : ne salez pas, le saumon fumé apporte déjà du sel.","En parallèle, faites cuire l'orzo."]},{"titre":"L'orzo","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire l'orzo selon les indications du paquet.","Gardez un peu d'eau de cuisson pour la sauce.","Pendant ce temps, préparez la sauce."]},{"titre":"La sauce citronnée","items":["Pressez le citron.","Dans une petite casserole, versez la crème. Portez à ébullition.","Ajoutez le jus de citron. Salez et poivrez. Poursuivez la cuisson à feu doux 2 min environ.","Pendant la préparation de la sauce, coupez le saumon fumé en morceaux.","Une fois le tout cuit, ajoutez la sauce citronnée, l'orzo égoutté, un peu d'eau de cuisson et le saumon fumé dans la sauteuse des courgettes. Mélangez bien pour enrober le tout.","Astuce : ajoutez un peu d'eau de cuisson des pâtes permet de lier la sauce et de la rendre plus onctueuse grâce à l'amidon qu'elle contient.","Goûtez et ajoutez une pincée de sel si nécessaire."]}]},{"id":"15928","nom":"Saumon teriyaki et riz au poireau","image":"images/15928.webp","ingredients":[["pavés de saumon","240 g"],["sauce teriyaki","20 ml"],["riz basmati","150 g"],["poireau (300g)","1x"]],"cuisine":["huile de cuisson (mélange 4 huiles par exemple)","sel","poivre"],"etapes":[{"titre":"La marinade","items":["Rincez et essuyez les pavés de saumon. Poivrez-les.","Enrobez les pavés de saumon avec la sauce teriyaki et réservez-les au réfrigérateur 10 min environ.","Pendant ce temps, préparez le poireau."]},{"titre":"Le poireau","items":["Coupez et retirez la base abîmée du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Emincez-le.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir le poireau 20 min environ. Salez, poivrez.","A mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson.","En parallèle, lancez la cuisson du riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Une fois le tout cuit, mélangez le poireau avec le riz.","Pendant la cuisson du riz, faites cuire le saumon."]},{"titre":"Le saumon","items":["Dans une poêle, faites chauffer un filet d’huile de cuisson à feu moyen à vif.","Faites dorer les pavés de saumon avec la sauce (côté peau en premier) 2 à 3 min de chaque côté jusqu'à ce qu'ils soient cuits à coeur. Pour savoir quand les retourner, regardez sur le côté : lorsqu’ils sont cuits à mi-hauteur, retournez-les !","Penchez la sauteuse et à l'aide d'une cuillère, récupérez la sauce pour la verser sur le saumon et bien l'enrober."]}]},{"id":"17981","nom":"Sausage roll (feuilleté à la chair à saucisse et au cheddar)","image":"images/17981.webp","ingredients":[["pâte feuilletée (230g)","1x"],["cheddar râpé","60 g"],["gousse d'ail","0.5"],["carotte (120g)","1x"],["chair à saucisse Bleu Blanc Coeur","240 g"],["salade","50 g"]],"cuisine":["sel","poivre","1 càs moutarde (rolls)","2 càs huile d'olive","1 càs vinaigre de votre choix","1 càc moutarde (vinaigrette)"],"etapes":[{"titre":"Les sausage rolls","items":["Préchauffez votre four à 200°C en chaleur tournante !","Pendant ce temps, pressez ou hachez l'ail.","Dans un saladier, mélangez la chair à saucisse, le cheddar, l'ail et la moutarde. Salez légèrement, poivrez.","Coupez la pâte feuilletée en 2 de manière à obtenir une bande par personne.","Façonnez 1 rouleau de farce par personne et enroulez-le de pâte. Badigeonnez légèrement les bords de la pâte avec un peu d’eau avant de rouler pour bien la sceller.","Déposez les rouleaux sur une plaque allant au four munie de papier cuisson.","Enfournez 18 à 20 min jusqu'à ce que la farce soit cuite à coeur.","Astuce : pour vérifier la cuisson, insérez la lame d’un couteau au centre : elle doit ressortir chaude et sans jus rosé.","Pendant ce temps, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Versez la moutarde et le vinaigre. Salez, poivrez. Ajoutez l'huile d'olive et mélangez bien pour obtenir une vinaigrette.","Épluchez et réalisez des tagliatelles de carotte à l'aide d'un économe.","Ajoutez la salade. Mélangez bien."]}]},{"id":"17272","nom":"Sauté d'encornets et chou pak choy à la sichuanaise (ail, piment et gingembre)","image":"images/17272.webp","ingredients":[["chou pak choy (135g)","1x"],["oignon jaune","0.5"],["piment oiseau (2g)","1x"],["gingembre","1 à 3 cm"],["gousse d'ail (6g)","1x"],["carotte (100g)","1x"],["riz basmati","150 g"],["poêlée d'encornets piment d'Espelette","200 g"]],"cuisine":["sel","poivre","huile de cuisson (mélange 4 huiles par exemple)"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon.","Épluchez et coupez la carotte en fins bâtonnets.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Pelez et hachez l'ail et le gingembre.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif. Faites revenir la carotte, le piment, le gingembre, l'ail et l'oignon 10 min.","Pendant la cuisson des légumes, coupez la base et effeuillez le chou pak choy.","Au bout des 10 min de cuisson, ajoutez le chou pak choy à la sauteuse et prolongez la cuisson 5 min (les légumes peuvent être encore un peu croquants). Salez légèrement, poivrez.","En parallèle, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet."]},{"titre":"A table !","items":["Lorsque tout est cuit, ajoutez les encornets dans la sauteuse et prolongez la cuisson 5 min environ pour qu'ils soient bien chauds.","Servez sans attendre avec le riz."]}]},{"id":"19543","nom":"Sauté de canard au balsamique, carotte et lentilles vertes","image":"images/19543.webp","ingredients":[["sauté de canard sans os avec peau","300 g"],["carotte (200g)","2x"],["vinaigre balsamique (pot) (30g)","1x"],["gousse d'ail (5g)","1x"],["lentilles vertes","150 g"],["bouquet garni (5g)","1x"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","25 g beurre","400 ml eau","0.5 bouillon de poule (cube)","huile de cuisson"],"etapes":[{"titre":"La préparation","items":["Portez à ébullition l'eau et le bouillon de poule.","Épluchez et coupez les carottes en fines rondelles.","Pressez ou hachez l'ail."]},{"titre":"Le sauté de canard","items":["Salez et poivrez le sauté de canard.","Dans une cocotte, faites chauffer le beurre et un filet d'huile de cuisson à feu vif.","Faites revenir le sauté de canard 5 min jusqu'à ce qu'il soit doré.","Au bout des 5 min, ajoutez l'ail, les carottes et l'oignon.","Faites revenir le tout 5 min.","Déglacez (versez) avec le vinaigre balsamique.","Ajoutez le bouillon de poule et le bouquet garni.","Couvrez et laissez mijoter à feu doux 1h.","En parallèle, faites cuire les lentilles."]},{"titre":"Les lentilles","items":["Dans une casserole, déposez les lentilles vertes et couvrez très largement d'eau.","Faites-les cuire selon les indications du paquet. Ne salez pas, le sel durcit les lentilles.","Une fois cuites, égouttez les lentilles.","Au bout des 1h de cuisson du canard, ajoutez les lentilles cuites et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"14531","nom":"Smashed quesadillas de porc au mélange tex-mex et cheddar","image":"images/14531.webp","ingredients":[["tortilla (200g)","4x"],["cheddar râpé","90 g"],["mélange tex-mex (sachet)","0.5"],["oignon jaune (110g)","1x"],["purée de tomates","250 g"],["chair à saucisse Bleu Blanc Coeur","240 g"]],"cuisine":["huile de cuisson","poivre","sel","1 càs sucre"],"etapes":[{"titre":"L'oignon confit","items":["Émincez l'oignon.","Dans une casserole, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon et le sucre 12 à 15 min. Remuez régulièrement. Salez, poivrez."]},{"titre":"Les smashed quesadillas","items":["Dans un bol, mélangez le mélange tex-mex et la chair à saucisse. Poivrez. Ne salez pas, la chair à saucisse est déjà assaisonnée.","Répartissez la chair à saucisse sur toute la surface des tortillas.","Dans une poêle, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir la tortilla côté chair à saucisse 2 à 3 min en écrasant avec une spatule pour obtenir une belle caramélisation de la viande.","Retournez la tortilla et répartissez dessus un peu de purée de tomates, d'oignon confit et de cheddar râpé.","Refermez la tortilla pour obtenir une quesadilla et poursuivez la cuisson 1 à 2 min jusqu'à ce que le cheddar soit fondu.","Recommencez l'opération jusqu'à épuisement des ingrédients."]},{"titre":"","items":["Dégustez sans attendre vos smashed quesadillas de porc au mélange tex-mex et cheddar !"]}]},{"id":"19899","nom":"Soupe de lentilles aux boulettes de porc, carotte et basilic","image":"images/19899.webp","ingredients":[["lentilles vertes (150g)","150 g"],["carotte (100g)","1x"],["gousse d'ail (6g)","1x"],["bouquet garni (5g)","1x"],["oignon jaune (110g)","1x"],["boulettes de porc nature (240g) Bleu Blanc Coeur","8x"],["purée de tomates (200g)","200 g"],["basilic (5g)","qq brins"]],"cuisine":["huile d'olive","600 ml eau","sel","poivre","0.5 bouillon de légumes"],"etapes":[{"titre":"La préparation","items":["Dans une cocotte, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les boulettes 8 min jusqu'à ce qu'elles soient bien dorées. Remuez régulièrement.","Réservez-les sur une assiette et gardez la cocotte pour la suite de la recette.","En parallèle, émincez l'oignon.","Épluchez et coupez la carotte en fines demi-rondelles (0,3 cm max).","Pressez ou hachez l'ail."]},{"titre":"La soupe","items":["Dans la même cocotte que celle des boulettes, faites chauffer de nouveau un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, l'ail et la carotte 10 min.","Ajoutez la purée de tomates, l'eau, le bouillon de légumes émietté, les lentilles et le bouquet garni.","Faites cuire 30 min environ à couvert jusqu'à ce que les lentilles soient tendres.","Astuce : ajoutez un peu d’eau en cours de cuisson si nécessaire.","Ne salez pas, le sel durcit les lentilles.","Au bout des 30 min de cuisson des lentilles, ajoutez les boulettes et poursuivez la cuisson 2 min pour réchauffer le tout.","Goûtez et ajoutez une pincée de sel et de poivre si nécessaire.","Effeuillez et ciselez le basilic.","Au moment de servir, parsemez la soupe de basilic."]}]},{"id":"16887","nom":"Soupe de lentilles corail à la coriandre et croustillant de féta au miel","image":"images/16887.webp","ingredients":[["feuilles de filo (125g)","4x"],["féta","100 g"],["oignon jaune (125g)","1x"],["miel","10 ml"],["cumin (sachet)","0.5"],["lentilles corail","150 g"],["Purée de tomates","200 g"],["coriandre","qq brins"]],"cuisine":["huile d'olive","sel","poivre","500 ml eau","0.5 bouillon de légumes (cube)"],"etapes":[{"titre":"La soupe","items":["Émincez l'oignon.","Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez le cumin, la purée de tomates, le bouillon de légumes, l'eau et les lentilles. Ne salez pas, le sel durcit les lentilles.","Portez à ébullition puis baissez à feu moyen. Couvrez et faites mijoter 15 min environ.","Une fois les lentilles cuites, mixez le tout jusqu'à obtenir une texture lisse et homogène. Salez, poivrez.","Astuce : ajoutez plus ou moins d'eau selon la texture souhaitée.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En fin de cuisson, réalisez les croustillants de féta."]},{"titre":"Les croustillants de féta","items":["Coupez la féta en morceaux.","Badigeonnez les feuilles de filo d'huile d'olive et superposez-les deux par deux.","Répartissez au milieu de chaque feuille la féta et repliez les feuilles de filo pour envelopper le fromage.","Écrasez la féta à l'aide d'un rouleau à pâtisserie pour la répartir.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites dorer les croustillants de féta 3 min sur chaque face.","Réservez-les sur une feuille de papier absorbant pour retirer l'excédent d'huile.","Arrosez-les de miel.","Ciselez la coriandre (en entier, les tiges se consomment) et parsemez-la sur la soupe."]}]},{"id":"14236","nom":"Soupe froide de courgettes à la féta, croûtons à l'ail et noisettes","image":"images/14236.webp","ingredients":[["courgette (600g)","3x"],["huile de noisette","20 ml"],["origan (sachet)","0.25"],["gousse d'ail (8g)","2x"],["oignon jaune","0.5"],["noisettes décortiquées","25 g"],["baguette tradition","135 g"],["féta","100 g"]],"cuisine":["sel","poivre","huile d'olive","600 eau (ml)","0.5 bouillon de légumes (cube)"],"etapes":[{"titre":"Les courgettes","items":["Pressez ou hachez l'ail.","Coupez les courgettes en morceaux.","Émincez l'oignon.","Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, la moitié de l'ail, les courgettes et l'origan 5 min pour les dorer.","Ajoutez l'eau et le bouillon de légumes. Salez, poivrez.","Couvrez et laissez cuire 15 min environ.","Pendant ce temps, préparez les croûtons."]},{"titre":"Les croûtons à l'ail","items":["Faites chauffer une poêle sans matière grasse.","Faites revenir les noisettes 5 min environ pour les torréfier.","Coupez la baguette en dés.","Dans la même sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif. Faites revenir la baguette et le reste d'ail 5 min environ jusqu'à ce que les croûtons soient dorés. Salez, poivrez."]},{"titre":"La soupe de courgettes","items":["Une fois les courgettes cuites, égouttez-les en gardant l'eau de cuisson.","Dans le bol d'un mixeur, déposez les courgettes et la féta (gardez-en un peu pour la présentation).","Ajoutez de l'eau de cuisson au fur et à mesure et mixez jusqu'à obtenir un mélange homogène. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Réservez la soupe au réfrigérateur.","Parsemez votre soupe du reste de féta, des croûtons à l'ail et des noisettes ! Arrosez-la d'huile de noisettes."]}]},{"id":"15363","nom":"Spaghettis à la crème de cresson et saumon fumé","image":"images/15363.webp","ingredients":[["cresson","100 g"],["crème épaisse","80 g"],["citron jaune","0.5"],["saumon fumé","100 g"],["spaghetti blancs","200 g"],["cébette (16g)","1x"]],"cuisine":["sel","poivre"],"etapes":[{"titre":"Les spaghettis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les spaghettis selon les indications du paquet.","Une fois cuits, égouttez-les et réservez-les dans la casserole.","En parallèle, préparez la crème de cresson."]},{"titre":"La crème de cresson","items":["Portez à ébullition une seconde casserole d'eau salée.","Faites cuire le cresson 5 min.","Au bout des 5 min, égouttez-le et déposez-le dans le bol d'un mixeur.","Ajoutez la crème. Salez, poivrez.","Mixez jusqu'à l'obtention d'une texture homogène.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"A table !","items":["Coupez le saumon fumé en morceaux.","Retirez la base de la cébette et émincez-la.","Coupez le citron en quartiers.","Ajoutez la crème de cresson à la casserole de spaghettis. Faites chauffer le tout 1 à 2 min en mélangeant bien."]},{"titre":"","items":["Dégustez sans attendre vos spaghettis à la crème de cresson parsemés de saumon fumé et de cébette ! Arrosez le tout d'un filet de jus de citron."]}]},{"id":"17188","nom":"Spaghettis au pesto de basilic et épinard maison, tomates cerises rôties","image":"images/17188.webp","ingredients":[["gousse d'ail","0.5"],["basilic","0.5"],["citron jaune","0.5"],["pousses d'épinards","50 g"],["noix de cajou","25 g"],["parmigiano reggiano râpé","20 g"],["spaghettis blancs","200 g"],["tomate cerise","300 g"]],"cuisine":["sel","poivre","2 huile d'olive (càs)","1 eau (càs)"],"etapes":[{"titre":"Les spaghettis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Astuce : Réservez un peu d'eau de cuisson pour réaliser le pesto.","Pendant ce temps, faites cuire les tomates cerises."]},{"titre":"Les tomates cerises","items":["Coupez les tomates en 2.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les tomates 7 à 10 min jusqu'à ce qu'elles soient cuites mais pas réduites en purée. Salez, poivrez.","En parallèle, préparez le pesto."]},{"titre":"Le pesto","items":["Dans le bol d'un mixeur, déposez les ingrédients suivants :","Pelez l'ail.","Effeuillez le basilic.","Ajoutez les pousses d'épinards, la moitié du parmesan, les noix de cajou, l’huile d’olive et l’eau.","Mixez jusqu'à obtenir un pesto lisse et homogène.","Astuce : Ajoutez un peu d’eau de cuisson des pâtes pour lier la sauce et la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Lorsque les pâtes sont cuites, ajoutez-les à la sauteuse des tomates avec le pesto. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez le citron en quartiers.","Au moment de servir, arrosez votre assiette d'un filet de jus de citron et parsemez le reste de parmesan."]}]},{"id":"18674","nom":"Spaghettis au saumon fumé et crème d'épinards","image":"images/18674.webp","ingredients":[["crème","80 g"],["citron jaune","0.5"],["saumon fumé","100 g"],["spaghetti blancs","200 g"],["cébette (16g)","1x"],["pousses d'épinards","100 g"]],"cuisine":["sel","poivre"],"etapes":[{"titre":"La crème d'épinards","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pousses d'épinards 5 min.","Au bout des 5 min, égouttez-les et déposez-les dans le bol d'un mixeur.","Ajoutez la crème. Salez, poivrez.","Mixez jusqu'à obtenir une texture homogène.","Astuce : ajouter un filet d’huile d’olive pour lisser la sauce.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les spaghettis","items":["Portez à ébullition une seconde casserole d'eau salée.","Faites cuire les spaghettis selon les indications du paquet.","Astuce : gardez de côté un bol d'eau de cuisson des pâtes pour la sauce.","Une fois cuits, égouttez-les et réservez-les dans la casserole."]},{"titre":"A table !","items":["Retirez la base de la cébette et émincez-la.","Coupez le citron en quartiers.","Ajoutez la crème d’épinards aux spaghettis et mélangez bien. Faites chauffer le tout 1 min.","Ajoutez un peu d'eau de cuisson si nécessaire.","Astuce : ajoutez un peu d’eau de cuisson des pâtes permet de lier la sauce et de la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Coupez le saumon fumé en morceaux et incorporez-le hors du feu. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez votre assiette de cébette et arrosez d'un filet de jus de citron."]}]},{"id":"15447","nom":"Spaghettis au saumon fumé, poireau et crème de ciboulette","image":"images/15447.webp","ingredients":[["ciboulette rondelle (sachet)","0.25"],["citron jaune","0.5"],["crème","100 g"],["gousse d'ail","0.5"],["saumon fumé","100 g"],["spaghetti blancs","200 g"],["poireau (300g)","1x"],["oignon jaune","0.5"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Le poireau, l'oignon et le saumon fumé","items":["Émincez l'oignon.","Coupez et retirez la base abîmée du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Emincez-le.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et le poireau 15 min environ. Poivrez.","Suggestion : ne salez pas, le saumon fumé apporte déjà du sel.","Pendant ce temps, coupez le saumon fumé en morceaux.","Au bout des 15 min, ajoutez le saumon fumé et un fond d'eau. Couvrez et prolongez la cuisson 5 min.","En parallèle,"]},{"titre":"Les spaghettis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les spaghettis selon les indications du paquet.","Pendant ce temps, préparez la crème à la ciboulette."]},{"titre":"La crème à la ciboulette","items":["Pressez ou hachez l'ail.","Pressez le citron.","Dans une petite casserole, faites chauffer la crème, l'ail, un filet de jus de citron et la ciboulette 2 à 3 min. Salez et poivrez.","Une fois le tout cuit, versez les spaghettis et la crème à la ciboulette dans la sauteuse des légumes.","Mélangez bien et faites chauffer à feu doux 1 min en remuant régulièrement pour tout enrober.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"","items":["Servez sans attendre les spaghettis au saumon fumé et crème de ciboulette !"]}]},{"id":"10045","nom":"Spaghettis aux chipolatas et sauce tomate au poivron","image":"images/10045.webp","ingredients":[["persil plat","qq brins"],["gousse d'ail","0.5"],["poivron rouge (250g)","2x"],["oignon jaune (110g)","1x"],["purée de tomates","200 g"],["spaghettis blancs","200 g"],["chipolatas oignon herbes (240g) Bleu Blanc Coeur","4x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La sauce tomate au poivron","items":["Pressez ou hachez l'ail.","Émincez les poivrons et l'oignon.","Dans une casserole, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les poivrons, l’oignon et l’ail 5 min.","Ajoutez la purée de tomates et laissez mijoter 7 à 8 min jusqu’à ce que les légumes soient tendres. Salez, poivrez. Remuez régulièrement.","Astuce : pour une sauce lisse et nappante, mixez le tout au mixeur avant de l’ajouter aux pâtes.","En parallèle, faites cuire les pâtes."]},{"titre":"Les spaghettis","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les pâtes selon les indications du paquet.","Une fois cuites, égouttez-les et réservez un peu d'eau de cuisson.","Pendant la cuisson des pâtes, faites cuire les chipolatas."]},{"titre":"Les chipolatas","items":["Coupez les chipolatas en 3 ou 4.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les chipolatas 10 min environ jusqu'à ce qu'elles soient cuites à coeur (la chair n'est plus rose). Salez, poivrez.","En parallèle, effeuillez et ciselez le persil.","Une fois le tout cuit, mélangez les spaghettis, la sauce tomate au poivron et les chipolatas.","Astuce : ajoutez un peu d'eau de cuisson des pâtes pour lier la sauce et la rendre plus onctueuse grâce à l'amidon qu'elle contient.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez le tout de persil."]}]},{"id":"8616","nom":"Spaghettis aux crevettes au beurre persillé et courgette","image":"images/8616.webp","ingredients":[["crevettes cuites nature","125 g"],["échalote (25g)","1x"],["citron jaune","0.5"],["gousse d'ail (6g)","1x"],["persil plat","qq brins"],["spaghetti demi-complets","200 g"],["courgette (200g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les crevettes","items":["Pressez ou hachez l'ail.","Ciselez (dés) l'échalote.","Pressez le jus de citron.","Effeuillez et ciselez le persil.","Dans une sauteuse, faites chauffer un filet d'huile d'olive et une noix de beurre à feu moyen.","Faites revenir les crevettes avec l'ail et l'échalote 3 à 5 min pour bien les dorer. Salez, poivrez.","Déglacez (versez) avec le jus de citron.","Hors du feu, ajoutez le persil.","Mélangez bien et réservez les crevettes sur une assiette.","Pendant ce temps, préparez les légumes."]},{"titre":"Les légumes","items":["Coupez la courgette en demi-rondelles.","Une fois les crevettes cuites, faites à nouveau chauffer un filet d'huile d'olive dans la sauteuse.","Faites revenir les légumes 10 min environ. Salez et poivrez.","Ne remuez pas la courgette immédiatement après les avoir déposés dans la poêle, laissez-les caraméliser quelques minutes pour obtenir une belle couleur dorée.","En parallèle, faite cuire les pâtes."]},{"titre":"Les spaghettis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les pâtes selon les indications du paquet. Réservez 1 louche d'eau de cuisson par personne.","Une fois les pâtes cuites, ajoutez-les à la sauteuse de la courgette avec les crevettes au persil et l'eau de cuisson.","Poursuivez la cuisson sur feu doux 2 min pour réchauffer le tout.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"18542","nom":"Spaghettis cacio e pepe au portobello et poivre noir fumé au bois de hêtre","image":"images/18542.webp","ingredients":[["champignon portobello","180 g"],["gousse d'ail","0.5"],["oignon jaune (110g)","1x"],["spaghetti blanc","200 g"],["poivre noir fumé au bois de hêtre (baie) (0.4g)","2x"],["parmigiano reggiano râpé","40 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Le portobello","items":["Portez à ébullition une casserole d'eau salée pour cuire les pâtes.","Émincez l'oignon.","Pressez ou hachez l'ail.","Coupez les champignons portobello en tranches.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les champignons, l'oignon et l'ail 10 à 15 min. Salez, poivrez. A mi-cuisson, baissez le feu puis couvrez pour accélérer la cuisson. Remuez régulièrement.","En parallèle, faites cuire les spaghettis."]},{"titre":"Les spaghettis","items":["Faites cuire les spaghetti selon les indications du paquet.","Une fois cuites, égouttez-les et réservez l''eau de cuisson."]},{"titre":"La sauce cacio e pepe","items":["Hachez grossièrement les baies de poivre fumé.","Dans la casserole des pâtes, déposez le parmesan, le poivre noir fumé et 2 càs d'eau de cuisson par personne. Salez légèrement.","Faites chauffer le tout 1 min en mélangeant sans arrêt.","Ajoutez la poêlée de champignons et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Servez immédiatement pour que la sauce garde la bonne texture."]}]},{"id":"21781","nom":"Spaghettis façon carbonara à la poitrine fumée, parmesan & pignons de pin","image":"images/21781.webp","ingredients":[["poitrine fumée (90g)","90 g"],["oignon jaune (110g)","1x"],["pousses d'épinards (50g)","50 g"],["pignon de pin (15g)","15 g"],["parmigiano reggiano râpé (20g)","20 g"],["spaghettis blancs (200g)","200 g"],["crème (100g)","100 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix"],"etapes":[{"titre":"Les spaghettis","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les spaghettis selon les indications du paquet.","Avant de les égoutter, conservez un petit verre d'eau de cuisson.","En parallèle, préparez la poitrine fumée."]},{"titre":"La poitrine fumée","items":["Dans une sauteuse, faites torréfier (dorer) les pignons de pin à sec 1 à 2 min à feu moyen, en remuant régulièrement, jusqu'à ce qu'ils soient dorés. Réservez-les et gardez la sauteuse.","Émincez l'oignon.","Coupez la poitrine fumée en morceaux.","Dans la même sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et la poitrine fumée 10 min environ jusqu'à ce que l'oignon soit tendre et la poitrine dorée. Salez légèrement, poivrez.","Au bout des 10 min, ajoutez la crème, le parmesan et un peu d'eau de cuisson. Mélangez bien jusqu'à obtenir une sauce homogène.","Ajustez la quantité d'eau de cuisson selon votre goût.","Astuce : ajoutez un peu d’eau de cuisson des pâtes permet de lier la sauce et de la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Ajoutez les spaghettis égouttés et mélangez bien.","Assaisonnez les pousses d'épinards d'un filet d'huile d'olive et de vinaigre.","Au moment de servir, parsemez les pignons de pin sur les spaghettis."]}]},{"id":"16037","nom":"Spaghettis frais à la poitrine fumée et pesto de noix","image":"images/16037.webp","ingredients":[["parmigiano reggiano râpé","30 g"],["spaghetti frais","250 g"],["poitrine fumée","90 g"],["champignons de Paris blancs","250 g"],["oignon jaune (110g)","1x"],["ciboulette","qq brins"],["noix sèche","40 g"]],"cuisine":["sel","poivre","4 càs huile d'olive","2 càs eau de cuisson"],"etapes":[{"titre":"La garniture","items":["Émincez l'oignon.","Coupez la poitrine fumée en morceaux.","Coupez les champignons de Paris en tranches.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon, la poitrine fumée et les champignons 10 à 15 min jusqu'à ce que le tout soit cuit et doré. Salez, poivrez.","En parallèle, faites cuire les spaghettis."]},{"titre":"Les spaghettis frais","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les spaghettis selon les indications du paquet.","Réservez la quantité d'eau de cuisson des pâtes pour le pesto.","Pendant ce temps, préparez le pesto de noix."]},{"titre":"Le pesto de noix","items":["Ouvrez les noix.","Dans le bol d'un mixeur, déposez les noix, le parmesan, l'huile d'olive et l'eau de cuisson des pâtes. Salez, poivrez.","Mixez jusqu'à obtenir une texture homogène.","Astuce : ajoutez de l'eau de cuisson des pâtes pour un pesto moins épais.","Lorsque tout est cuit, ajoutez les spaghettis et le pesto à la sauteuse du mélange champignons/poitrine et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Ciselez la ciboulette et parsemez-la sur les pâtes."]}]},{"id":"15993","nom":"Spätzles à la poitrine fumée, poireau et crème de parmesan AOP","image":"images/15993.webp","ingredients":[["poitrine fumée","90 g"],["parmigiano reggiano râpé","20 g"],["crème","100 g"],["spätzle frais","400 g"],["poireau (300g)","1x"],["gousse d'ail (5g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Le poireau","items":["Pressez ou hachez l'ail.","Coupez et retirez la base du poireau. Incisez-le en deux dans la longueur et rincez-le soigneusement. Émincez-les.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir le poireau et l'ail 20 min environ. À mi-cuisson, ajoutez un fond d'eau et couvrez pour accélérer la cuisson. Salez, poivrez.","Pendant la cuisson du poireau, faites cuire la poitrine fumée."]},{"titre":"La poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Faites chauffer une poêle sans matière grasse.","Faites dorer la poitrine fumée 5 min."]},{"titre":"A table !","items":["Quand la poitrine fumée est cuite, ajoutez les spätzles dans la sauteuse et poursuivez la cuisson 3 min.","Ajoutez ensuite la crème, les légumes et le parmesan.","Mélangez bien et faites cuire le tout 2 min supplémentaires.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"16198","nom":"Steak de boeuf, sauce diable relevée et frites de patate douce","image":"images/16198.webp","ingredients":[["vin blanc du Vaucluse","50 ml"],["concentré de tomates","35 g"],["piment oiseau (2g)","1x"],["patate douce (400g)","1x"],["steak de boeuf mariné (240g)","2x"],["échalote","0.5"]],"cuisine":["sel","poivre","huile de cuisson","1 càc vinaigre (blanc ou de cidre)","0.5 cube bouillon de bœuf","200 ml eau","1 càc farine","beurre"],"etapes":[{"titre":"Les frites","items":["Préchauffez votre four à 220°C en chaleur tournante !","Pendant ce temps, épluchez et coupez la patate douce en forme de frites.","Déposez-les sur une plaque allant au four. Versez un filet d'huile de cuisson. Salez, poivrez et mélangez bien pour tout enrober.","Enfournez 25 à 30 min. Remuez à mi-cuisson.","En parallèle, préparez la sauce diable."]},{"titre":"La sauce diable","items":["Dans une casserole, portez à ébullition l'eau et le bouillon de boeuf. Mélangez bien.","Dans un bol, délayez à l'aide d'un fouet la farine avec un peu de bouillon puis reversez le tout dans la casserole du bouillon. Faites chauffer 1 min puis retirez du feu pour obtenir un bouillon lié.","Ciselez (dés) l'échalote. Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Dans une seconde casserole, déposez le vinaigre, le vin blanc et l'échalote.","Faites cuire 1 à 2 min pour faire réduire de moitié.","Ajoutez le bouillon lié, le piment et le concentré de tomate. Faites mijoter à petit bouillon 10 min environ jusqu'à ce que la sauce soit nappante.","Pendant ce temps, faites cuire la viande."]},{"titre":"Les steaks de boeuf","items":["Dans une poêle, faites fondre une noix de beurre à feu moyen à vif.","Faites cuire les steaks de boeuf 2 à 3 min de chaque côté selon la cuisson souhaitée. Salez, poivrez."]}]},{"id":"21812","nom":"Steak de hampe façon tigre qui pleure pimenté","image":"images/21812.webp","ingredients":[["sauce soja salée (23g)","20 ml"],["steak de hampe (250g)","2x"],["riz rond blanc (150g)","150 g"],["nuoc mam (sauce poisson) (10g)","10 ml"],["citron vert (45g)","0.5"],["piment oiseau (2g)","1x"],["cébette (16g)","1x"],["coriandre (5g)","qq brins"],["échalote (25g)","1x"]],"cuisine":["sel","poivre","huile de cuisson","1 càc sucre"],"etapes":[{"titre":"La marinade et le riz","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Dans un saladier, mélangez les steaks de hampe avec la moitié de la sauce soja.","Laissez mariner 15 min environ au frais.","Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet.","Pendant la cuisson du riz, préparez la sauce."]},{"titre":"La sauce au piment","items":["Ciselez (dés) l'échalote.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Ciselez la coriandre (en entier, les tiges se consomment).","Pressez le citron.","Dans un bol, mélangez le reste de sauce soja, le sucre, la sauce nuoc mam et un filet de jus de citron. Ajoutez l'échalote, le piment, la coriandre et mélangez bien.","Retirez la base de la cébette et émincez-la."]},{"titre":"Le bœuf","items":["Épongez la marinade du boeuf à l'aide d'un essuie-tout (cela permet de mieux le griller).","Dans une poêle, faites chauffer un filet d'huile de cuisson à feu vif.","Saisissez les steaks 30 sec de chaque côté pour bien les dorer.","Poursuivez la cuisson 1 à 2 min à feu moyen de chaque côté selon la cuisson souhaitée. Réservez dans un papier d'aluminium 5 min. Au moment de servir, tranchez le bœuf en fines lanières.","Nappez-le de la moitié de la sauce et servez le reste à côté. Parsemez de cébette et accompagnez du riz."]}]},{"id":"21866","nom":"Steak de hampe, beurre maître d'hôtel & frites","image":"images/21866.webp","ingredients":[["persil plat (5g)","qq brins"],["gousse d'ail (3g)","0.5"],["steak de hampe (250g)","2x"],["pomme de terre (440g)","2x"],["citron jaune (55g)","0.5"],["échalote (12.5g)","0.5"],["salade (50g)","50 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","25 g beurre"],"etapes":[{"titre":"Les frites","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Préchauffez le four à 220°C en chaleur tournante !","Pendant ce temps, épluchez et coupez les pommes de terre en forme de frites.","Déposez-les sur une plaque allant au four. Versez un filet d'huile d'olive. Salez, poivrez et mélangez bien pour tout enrober.","Enfournez 25 à 30 min jusqu'à ce qu'elles soient fondantes à l’intérieur et bien dorées à l'extérieur.","Retournez-les à mi-cuisson pour qu’elles dorent uniformément.","Pendant ce temps, préparez le beurre maître d'hôtel."]},{"titre":"Le beurre maître d'hôtel","items":["Effeuillez le persil.","Pelez l'échalote et l'ail.","Dans le bol d'un mixeur, déposez le persil, l'ail et l'échalote.","Mixez jusqu'à obtenir une texture bien hachée et homogène.","En parallèle, passez le beurre 5 à 10 secondes au micro-ondes pour le ramollir (il ne doit pas être fondu) et mélangez-le avec la persillade. Salez, poivrez.","Pressez le citron et ajoutez un filet de jus de citron (plus ou moins selon votre goût).","Façonnez le beurre en boudin en le déposant sur du film alimentaire, puis roulez-le en serrant et en torsadant les extrémités avant de le mettre au frais."]},{"titre":"Le boeuf","items":["Épongez la viande à l'aide d'un essuie-tout. Salez, poivrez.","Dans une poêle, faites chauffer un filet d’huile d'olive et une noix de beurre à feu vif.","Saisissez les steaks 30 sec de chaque côté pour bien les dorer.","Astuce : pour bien saisir ne la bougez pas immédiatement dans la poêle pour une texture parfaite.","Poursuivez la cuisson 1 à 2 min de chaque côté selon la cuisson souhaitée.","Assaisonnez la salade d'un filet d'huile d'olive, de vinaigre et du reste de jus de citron.","Au moment de servir, déposez le beurre maître d'hôtel sur le steak chaud."]}]},{"id":"19155","nom":"Steak de hampe, crème à la truffe et champignons de Paris","image":"images/19155.webp","ingredients":[["champignons de Paris blancs","250 g"],["crème à la truffe","60 g"],["spaghetti blancs","200 g"],["steak de hampe (250g)","2x"]],"cuisine":["sel","poivre","beurre","huile d'olive"],"etapes":[{"titre":"Les spaghettis","items":["Sortez la viande de l’emballage pour l’aérer : elle cuira plus uniformément et restera plus tendre.","Portez à ébullition une casserole d'eau salée.","Faites cuire les spaghettis selon les indications du paquet.","Une fois cuites, égouttez-les et ajoutez un filet d'huile d'olive pour éviter qu'elles collent."]},{"titre":"La viande","items":["Coupez les champignons en tranches.","Épongez la viande à l'aide d'un essuie-tout. Salez, poivrez.","Dans une sauteuse, faites fondre une noix de beurre à feu vif.","Saisissez les steaks 1 min de chaque côté pour les colorer, puis baissez le feu et poursuivez la cuisson 2 à 3 min de chaque côté selon la cuisson désirée.","Déposez-les sur une assiette, recouvrez de papier aluminium pour les garder chauds et gardez la sauteuse.","Astuce : le repos de la viande permet une texture plus tendre et juteuse."]},{"titre":"Les champignons","items":["Dans la même sauteuse, ajoutez un filet d’huile d’olive.","Faites revenir les champignons 10 min à feu vif en remuant jusqu’à ce qu’ils soient dorés. Salez, poivrez.","Ajoutez la crème à la truffe et laissez réduire 2 à 3 min. Goûtez, rectifiez l’assaisonnement si besoin.","Servez les steaks nappés de la sauce bien chaude."]}]},{"id":"19822","nom":"Suprême végétal, quinoa fondant aux petits pois et sauce citronnée","image":"images/19822.webp","ingredients":[["gousse d'ail (6g)","1x"],["suprême végétal (220g)","2x"],["quinoa blanc (150g)","150 g"],["petits pois (avec cosses) (300g)","300 g"],["coriandre (5g)","qq brins"],["oignon jaune (110g)","1x"],["concentré de tomates (35g)","35 g"],["citron jaune (125g)","1x"]],"cuisine":["1 càs huile d'olive","sel","poivre","0.5 bouillon de légumes (cube)","300 ml eau"],"etapes":[{"titre":"Le quinoa aux petits pois","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Écossez les petits pois.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez l'ail, le concentré de tomates, les petits pois et poursuivez la cuisson 3 min environ. Remuez régulièrement.","Ajoutez ensuite le quinoa, l'eau et le bouillon de légumes émietté. Salez, poivrez.","Poursuivez la cuisson à couvert à feu doux 15 à 20 min. Remuez régulièrement.","Astuce : ajoutez un peu d'eau si le quinoa n'est pas assez cuit.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Pendant ce temps, préparez les suprêmes."]},{"titre":"Les suprêmes végétaux","items":["Salez et poivrez les suprêmes végétaux.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir les suprêmes 6 à 7 min jusqu'à ce qu'ils soient dorés. Retournez-les régulièrement.","En parallèle, préparez la sauce."]},{"titre":"La sauce citronnée","items":["A l’aide d’une râpe, prélevez des zestes de citron (uniquement l’écorce de couleur) et pressez-le.","Dans le bol d'un mixeur, déposez la coriandre, le jus du citron et l'huile d'olive, mixez jusqu'à obtenir une texture homogène.","Astuce : ajustez la quantité de citron selon votre sensibilité à l'acidité.","Ajoutez les zestes de citron. Salez, poivrez et mélangez.","Goûtez et rectifiez l’assaisonnement si nécessaire.","Dégustez les suprêmes nappés de sauce."]}]},{"id":"17147","nom":"Taboulé au melon, menthe et poitrine fumée","image":"images/17147.webp","ingredients":[["poitrine fumée","90 g"],["graines de couscous","150 g"],["melon charentais","0.3"],["menthe","qq brins"],["concombre noa (250g)","1x"],["citron jaune","0.5"]],"cuisine":["sel","poivre","3 cs huile d'olive","200 mL eau","2 cs vinaigre de votre choix"],"etapes":[{"titre":"Les graines de couscous","items":["Portez à ébullition l'eau et dans un récipient, déposez les graines de couscous.","Versez l'eau sur les graines de couscous. Couvrez et laissez gonfler 5 min.","Ajoutez-y un filet d'huile d'olive. Salez, poivrez et à l'aide d'une fourchette, égrainez-les (séparez les grains).","Pendant ce temps, faites cuire la poitrine fumée."]},{"titre":"La poitrine fumée","items":["Coupez la poitrine fumée en morceaux.","Faites chauffer une sauteuse sans matière grasse à feu moyen à vif.","Faites dorer la poitrine fumée 5 min environ.","En parallèle, réalisez le taboulé."]},{"titre":"Le taboulé","items":["Dans un saladier, déposez les ingrédients suivants :","Pressez le citron.","Versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Epluchez et coupez le concombre en dés.","Coupez le melon en morceaux.","Effeuillez et ciselez la menthe.","Une fois cuites, ajoutez les graines de couscous et la poitrine fumée. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17090","nom":"Taboulé aux tomates, fraises et mozzarella","image":"images/17090.webp","ingredients":[["mozzarella di bufala","125 g"],["graines de couscous","150 g"],["oignon rouge","0.25"],["concombre noa (250g)","1x"],["menthe (botte)","0.5"],["fraise","150 g"],["tomate (210g)","2x"]],"cuisine":["sel","poivre","4 cs huile d'olive","2 cs vinaigre balsamique","200 ml eau"],"etapes":[{"titre":"Le couscous","items":["Portez à ébullition l'eau. Dans un récipient déposez les graines de couscous.","Versez l'eau sur les graines de couscous. Couvrez et laissez gonfler 5 min. Ajoutez-y un filet d'huile d'olive.","Salez, poivrez et à l'aide d'une fourchette, égrainez-les (séparez les grains) et laissez-les refroidir à température ambiante.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"Le taboulé","items":["Dans un saladier, déposez les ingrédients suivants :","Ciselez (dés) l'oignon. Versez l'huile d'olive et le vinaigre. Salez, poivrez et mélangez bien pour obtenir une vinaigrette.","Épluchez le concombre.","Coupez le concombre, les tomates, les fraises et la mozzarella en petits dés.","Effeuillez et ciselez la menthe.","Ajoutez les graines de couscous refroidies et mélangez bien."]}]},{"id":"15864","nom":"Taboulé chypriote au manouri grillé et au radis bleu","image":"images/15864.webp","ingredients":[["boulgour","150 g"],["manouri grec","120 g"],["carotte orange (200g)","2x"],["graines de courge","15 g"],["radis bleu","0.5"],["persil-menthe (botte)","0.5"],["échalote","0.5"],["citron jaune (110g)","1x"]],"cuisine":["sel","poivre","20 g farine","3 càs huile d'olive","huile d'olive"],"etapes":[{"titre":"Le boulgour","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire le boulgour selon les indications du paquet.","Une fois cuit, égouttez-le et passez-le sous l'eau froide. Salez, poivrez et versez un filet d'huile d'olive."]},{"titre":"Le taboulé","items":["Dans un saladier, déposez les ingrédients suivants :","Pressez le citron jaune.","Ciselez (dés) l'échalote.","Épluchez et râpez la carotte.","Épluchez et coupez le radis en dés (1 cm environ).","Effeuillez et ciselez la menthe et le persil.","Une fois le boulgour cuit et refroidit, ajoutez-le au saladier et mélangez bien.","Ajoutez l'huile d'olive. Salez, poivrez."]},{"titre":"Le manouri","items":["Dans une poêle, faites chauffer un filet d’huile d'olive à feu moyen à vif.","Versez la farine dans une assiette. Déposez-y le manouri et enrobez-le.","Déposez-le ensuite dans la poêle. Faites-le dorer 2 à 3 min de chaque côté.","Une fois prêt, taillez-le en gros morceaux et ajoutez-le au taboulé.","Parsemez le taboulé de graines de courge."]}]},{"id":"15393","nom":"Tagliatelles à la carbonara","image":"images/15393.webp","ingredients":[["crème","100 g"],["lardons fumés","150 g"],["tagliatelles fraîches","250 g"],["oignon jaune","0.5"],["pomme (105g)","1x"],["multifeuille","50 g"],["herbes de Provence (sachet)","0.5"]],"cuisine":["sel","poivre","2 càs huile d'olive","1 càs vinaigre de votre choix"],"etapes":[{"titre":"Les tagliatelles","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les tagliatelles selon les indications du paquet.","Une fois cuites, égouttez-les et versez un filet d'huile de cuisson pour éviter qu'elles collent.","Pendant ce temps, préparez la sauce."]},{"titre":"La sauce","items":["Émincez l’oignon.","Dans une sauteuse sans matière grasse, faites revenir l'oignon et les lardons 5 à 7 min environ, jusqu'à ce qu'ils soient dorés. Ajoutez les herbes de Provence, salez et poivrez.","Ajoutez la crème et faites chauffer 1 à 2 min supplémentaires.","Ajoutez les tagliatelles et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, préparez la salade."]},{"titre":"La salade","items":["Dans un saladier, déposez les ingrédients suivants :","Versez l'huile d'olive et le vinaigre. Salez, poivrez. Mélangez bien pour obtenir une vinaigrette.","Coupez la pomme en fins bâtonnets.","Ajoutez la salade.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"","items":["Dégustez sans attendre vos tagliatelles à la carbonara accompagnées de la salade !"]}]},{"id":"19438","nom":"Tagliatelles à la chair à saucisse et crème pimentée à la tomate","image":"images/19438.webp","ingredients":[["tagliatelle fraîche","250 g"],["épices calabraises (sachet)","0.5"],["gousse d'ail (4g)","1x"],["chair à saucisse Bleu Blanc Coeur","240 g"],["crème","100 g"],["concentré de tomates","35 g"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La sauce","items":["Portez à ébullition une casserole d’eau salée pour les tagliatelles.","Ciselez (dés) l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir l'oignon 5 min.","Au bout des 5 min, ajoutez la chair à saucisse et prolongez 5 min.","Ensuite, ajoutez le concentré de tomates, les épices calabraises, l'ail et la crème. Les épices sont fortes, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût.","Faites cuire 5 à 10 min à feu moyen jusqu'à ce que la viande soit cuite à coeur (la chair n'est plus rose). Salez et poivrez."]},{"titre":"Les tagliatelles","items":["Faites cuire les tagliatelles selon les indications du paquet.","Réservez un peu d'eau de cuisson.","Une fois cuites, ajoutez les tagliatelles à la sauteuse et ajustez la texture de la sauce en ajoutant plus ou moins d'eau de cuisson.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"16202","nom":"Tagliatelles aux lardons fumés et sauce tomate à l'origan","image":"images/16202.webp","ingredients":[["tagliatelle","250 g"],["lardons fumés","150 g"],["origan (sachet)","0.25"],["gousse d'ail","0.5"],["Purée de tomates","200 g"],["oignon jaune (130g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"La sauce tomate à l'origan","items":["Émincez l'oignon.","Dans une casserole, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 5 min environ. Salez, poivrez.","Pressez ou hachez l'ail.","Au bout des 5 min, ajoutez la purée de tomates, l'ail et l'origan. Laissez mijoter 10 à 15 min à feu doux.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Astuce : Pour réduire l'acidité de votre sauce tomate, ajoutez une cuillère à café de sucre. Pour une sauce plus liquide, ajoutez un peu d'eau de cuisson des pâtes.","En parallèle, faites cuire les lardons."]},{"titre":"Les lardons fumés","items":["Faites chauffer une poêle sans matière grasse à feu moyen à vif.","Faites revenir les lardons fumés 10 min environ. Poivrez.","Pendant ce temps, faites cuire les tagliatelles."]},{"titre":"Les tagliatelles","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les tagliatelles selon les indications du paquet.","Une fois le tout cuit, ajoutez les tagliatelles et les lardons dans la casserole de la sauce tomate. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17603","nom":"Tagliatelles aux pleurotes et à la crème aux cèpes","image":"images/17603.webp","ingredients":[["tagliatelles fraîches","250 g"],["pleurotes","250 g"],["crème aux cèpes","60 g"],["gousse d'ail (6g)","1x"],["persil plat","qq brins"],["oignon jaune (110g)","1x"]],"cuisine":["huile d'olive","sel","poivre"],"etapes":[{"titre":"Les pleurotes","items":["Émincez l'oignon.","Déchirez les pleurotes.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'oignon 5 min.","Ajoutez les pleurotes et l'ail et poursuivez la cuisson 5 min environ. Salez, poivrez.","En parallèle, faites cuire les tagliatelles."]},{"titre":"Les tagliatelles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les tagliatelles selon les indications du paquet.","Astuce : gardez un peu d'eau de cuisson des pâtes pour réaliser la sauce."]},{"titre":"A table !","items":["Effeuillez et ciselez le persil.","Une fois le tout cuit, ajoutez les tagliatelles, la crème aux cèpes, un peu d'eau de cuisson et le persil dans la sauteuse des pleurotes.","Astuce : l'eau de cuisson des pâtes permet de lier la sauce et de la rendre plus onctueuse grâce à l'amidon qu'elle contient.","Mélangez bien et poursuivez la cuisson 1 min pour réchauffer le tout.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"17814","nom":"Tagliatelles fraîches à la burrata, parmesan et basilic","image":"images/17814.webp","ingredients":[["burrata (100g)","1x"],["tagliatelle","250 g"],["gousse d'ail","0.5"],["parmigiano reggiano râpé","30 g"],["basilic séché","0.25"],["pulpe de tomates","300 g"],["oignon jaune (125g)","1x"]],"cuisine":["sel","poivre","huile d'olive","2 càs eau"],"etapes":[{"titre":"La sauce","items":["Émincez l'oignon.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon 5 min.","Au bout des 5 min de cuisson, ajoutez la pulpe de tomates, l'ail, le basilic séché et l'eau. Poursuivez la cuisson de 7 min environ. Salez, poivrez.","Astuce : ajoutez une cuillère à café de sucre pour réduire l'acidité de la sauce.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les tagliatelles."]},{"titre":"Les tagliatelles et la burrata","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les tagliatelles selon les indications du paquet.","Une fois cuites, égouttez-les et ajoutez-les à la sauteuse de la sauce. Mélangez bien.","Astuce : ajoutez un peu d’eau de cuisson des pâtes pour lier la sauce et la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez la burrata en morceaux.","Au moment de servir, ajoutez les morceaux de burrata sur les tagliatelles et parsemez de parmesan."]}]},{"id":"16562","nom":"Tagliatelles fraîches à la courgette, féta et herbes fraîches","image":"images/16562.webp","ingredients":[["tagliatelles fraîches","250 g"],["gousse d'ail (6g)","1x"],["amandes goût fumé","25 g"],["féta","80 g"],["oignon jaune","0.5"],["crème","80 g"],["courgette (200g)","1x"],["cerfeuil-persil (botte)","0.5"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les légumes","items":["Émincez l'oignon.","Coupez la courgette en fines demi-rondelles.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et la courgette 10 min.","Astuce : N’ayez pas peur de saisir vos aliments à feu vif ! Une belle coloration dorée signifie que les sucs se développent et que la caramélisation apporte des saveurs intenses et gourmandes. Laissez-les quelques instants avant de les retourner pour un résultat optimal.","Pendant ce temps, pressez ou hachez l'ail.","Effeuillez et ciselez le mélange persil-cerfeuil.","Au bout des 10 min, ajoutez la crème, l'ail et le mélange persil-cerfeuil.","Poursuivez la cuisson 5 min environ. Salez, poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","En parallèle, faites cuire les tagliatelles."]},{"titre":"Les tagliatelles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les tagliatelles selon les indications du paquet.","Une fois le tout cuit, ajoutez les tagliatelles à la sauteuse des légumes et mélangez bien.","Coupez la féta en morceaux.","Hachez les amandes fumées.","Au moment de servir, parsemez votre recette de féta et d'amandes."]}]},{"id":"22051","nom":"Tagliatelles fraîches au pesto pomodoro, burrata et amandes","image":"images/22051.webp","ingredients":[["tagliatelles (250g)","250 g"],["pesto pomodoro (90g)","90 g"],["burrata (100g)","1x"],["amandes effilées (15g)","15 g"]],"cuisine":["sel","poivre"],"etapes":[{"titre":"Les tagliatelles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les tagliatelles selon les indications du paquet.","Astuce : réservez un peu d'eau de cuisson des pâtes pour la sauce.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"A table !","items":["Faites chauffer une petite sauteuse sans matière grasse à feu moyen.","Faites torréfier (dorer) les amandes effilées 2 à 3 min en remuant régulièrement.","Une fois les tagliatelles cuites, égouttez-les et remettez-les dans la casserole avec le pesto pomodoro et un peu d'eau de cuisson. Salez légèrement, poivrez et mélangez bien.","Astuce : ajoutez un peu d’eau de cuisson des pâtes permet de lier la sauce et de la rendre plus onctueuse grâce à l’amidon qu’elle contient.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez la burrata en morceaux.","Au moment de servir, parsemez la burrata et les amandes torréfiées sur les tagliatelles."]}]},{"id":"18548","nom":"Tagliatelles gorgonzola, poire et noix","image":"images/18548.webp","ingredients":[["tagliatelles fraîches","250 g"],["champignons de Paris blancs","250 g"],["gorgonzola","90 g"],["noix sèche","40 g"],["gousse d'ail","0.5"],["poire (140g)","1x"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"Les champignons et la poire","items":["Émincez l'oignon.","Coupez les champignons en tranches.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu vif.","Faites revenir les champignons et l'oignon 5 min environ jusqu'à ce qu'ils soient dorés. Salez, poivrez.","En parallèle, coupez la poire en dés.","Pressez ou hachez l'ail.","Au bout des 5 min, ajoutez l'ail et la poire. Poursuivez la cuisson 5 min à feu moyen.","Pendant ce temps, faites cuire les tagliatelles."]},{"titre":"Les tagliatelles","items":["Portez à ébullition une casserole d’eau salée.","Faites cuire les tagliatelles selon les indications du paquet.","Une fois cuites, égouttez-les et ajoutez un filet d'huile d'olive pour éviter qu'elles collent. Réservez un peu d'eau de cuisson des pâtes."]},{"titre":"A table !","items":["Coupez le gorgonzola en dés.","Une fois les légumes cuits, ajoutez le gorgonzola dans la sauteuse avec un peu d'eau de cuisson des pâtes.","Laissez cuire 2 à 3 min jusqu'à ce que le gorgonzola soit fondu.","Ajoutez les tagliatelles et mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Ouvrez et hachez les noix grossièrement.","Au moment de passer à table, parsemez le plat de noix."]}]},{"id":"17906","nom":"Tarte fine aux champignons et mozzarella","image":"images/17906.webp","ingredients":[["pâte brisée (230g)","1x"],["fromage blanc","100 g"],["champignons de Paris blancs","250 g"],["roquette","50 g"],["oignon jaune (125g)","1x"],["mozzarella de vache (125g)","1x"],["sel à la truffe","2 pincées"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix"],"etapes":[{"titre":"Les champignons et la mozzarella","items":["Préchauffez votre four à 200°C en chaleur tournante !","Pendant ce temps, émincez l'oignon.","Coupez les champignons de Paris en tranches.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir les champignons, l'oignon et le sel à la truffe 5 à 10 min pour les dorer et faire évaporer un maximum d'eau. Salez légèrement, poivrez.","En parallèle, coupez la mozzarella en petits morceaux."]},{"titre":"La tarte","items":["Déroulez la pâte brisée sur une plaque allant au four.","Étalez le fromage blanc sur la pâte brisée. Salez, poivrez.","Répartissez le mélange oignon/champignons et la mozzarella par-dessus.","Enfournez 10 à 15 min jusqu'à ce que la pâte soit dorée et cuite (soulevez-la délicatement pour vérifier).","En sortie de four, parsemez un peu de roquette sur la tarte et arrosez d'un filet d'huile d'olive.","Assaisonnez le reste de roquette d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"17252","nom":"Tartines de saumon fumé à l'aneth et à la pomme","image":"images/17252.webp","ingredients":[["fromage blanc","100 g"],["pain de campagne (tranche) (100g)","4x"],["saumon fumé","100 g"],["citron jaune","0.5"],["aneth","qq brins"],["échalote","0.5"],["sucrine (200g)","1x"],["pomme","0.5"]],"cuisine":["huile d'olive","vinaigre de votre choix","sel","poivre"],"etapes":[{"titre":"La sauce","items":["Dans un bol, déposez les ingrédients suivants :","Effeuillez et ciselez l'aneth.","A l’aide d’une râpe, prélevez des zestes de citron jaune (uniquement l’écorce de couleur) et pressez-le.","Ajoutez le fromage blanc et un filet d'huile d'olive. Salez, poivrez. Mélangez bien.","Goûtez et rectifiez l'assaisonnement si nécessaire."]},{"titre":"Les tartines et la salade","items":["Faites dorer les tranches de pain de campagne au grille-pain.","En parallèle, coupez le saumon fumé en morceaux.","Coupez la pomme en fin bâtonnets.","Ciselez (dés) l'échalote.","Sur chaque tartine, étalez la sauce au fromage blanc et répartissez par-dessus le saumon fumé, la pomme et l'échalote.","Retirez la base de la sucrine et émincez-la.","Assaisonnez-la d'un filet d'huile d'olive et de vinaigre."]}]},{"id":"17850","nom":"Tout-en-un : Coquillotto au butternut et burrata","image":"images/17850.webp","ingredients":[["crème","100 g"],["gousse d'ail","0.5"],["courge butternut","250 g"],["graines de pavot","10 g"],["coquillettes demi-complètes","200 g"],["burrata (100g)","1x"],["oignon jaune (125g)","1x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","500 ml eau","0.5 bouillon de légumes (cube)"],"etapes":[{"titre":"La préparation","items":["Emincez l'oignon.","Épluchez le butternut et retirez les graines à l'aide d'une cuillère. Coupez-le en tranches puis taillez celles-ci en dés.","Astuce : pour faciliter la découpe, passez le butternut 5 min au micro-ondes avant de l’éplucher et de le couper.","Pressez ou hachez l'ail."]},{"titre":"Le coquillotto","items":["Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et le butternut 5 min environ. Salez légèrement, poivrez.","Au bout des 5 min, ajoutez l'eau, le bouillon de légumes, l'ail et les coquillettes.","Couvrez et faites cuire 12 à 15 min jusqu’à ce que les coquillettes soient cuites et le liquide absorbé. Remuez régulièrement.","Pendant ce temps, effeuillez et ciselez le persil."]},{"titre":"A table !","items":["Une fois les coquillettes cuites, ajoutez la crème et le persil (réservez quelques feuilles pour la présentation).","Poursuivez la cuisson 1 à 2 min pour que le tout soit chaud.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez la burrata en morceaux.","Au moment de passer à table, parsemez sur votre coquillotto : le reste de persil, la burrata et les graines de pavot."]}]},{"id":"18199","nom":"Tout-en-un : Coquillotto aux champignons, persil et burrata","image":"images/18199.webp","ingredients":[["crème","100 g"],["champignons de Paris blancs","250 g"],["graines de pavot","10 g"],["gousse d'ail","0.5"],["burrata (100g)","1x"],["coquillettes demi-complètes","200 g"],["oignon jaune (110g)","1x"],["persil plat","qq brins"]],"cuisine":["sel","poivre","huile d'olive","500 ml eau","0.5 cube bouillon de légumes"],"etapes":[{"titre":"La préparation","items":["Ciselez (dés) l'oignon.","Coupez les champignons en tranches.","Pressez ou hachez l'ail."]},{"titre":"Le coquillotto","items":["Dans une cocotte, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon, l'ail et les champignons 5 min jusqu'à ce qu'ils soient légèrement dorés. Salez légèrement, poivrez.","Ajoutez l'eau, le bouillon de légumes émietté et les coquillettes.","Couvrez et faites cuire 10 à 12 min, en remuant régulièrement, jusqu’à ce que les coquillettes soient tendres et que le liquide soit presque entièrement absorbé.","Pendant ce temps, effeuillez et ciselez le persil. Réservez quelques feuilles pour le dressage."]},{"titre":"A table !","items":["Une fois les coquillettes cuites, ajoutez la crème et le persil ciselé.","Poursuivez la cuisson 2 à 3 min pour que le tout soit chaud et que la sauce soit nappante.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Coupez la burrata en morceaux.","Servez le coquillotto dans des assiettes creuses. Ajoutez la burrata, parsemez du reste de persil et des graines de pavot."]}]},{"id":"17719","nom":"Tout-en-un : Risotto aux champignons et savola à la truffe","image":"images/17719.webp","ingredients":[["vin blanc du Vaucluse","50 ml"],["savola à la truffe","60 g"],["riz rond","150 g"],["champignons de Paris blancs","250 g"],["oignon jaune (125g)","1x"]],"cuisine":["600 ml eau","sel","poivre","0.5 cube bouillon de légumes","huile d'olive"],"etapes":[{"titre":"La préparation","items":["Ciselez (dés) l'oignon.","Coupez les champignons de Paris en tranches."]},{"titre":"Le risotto","items":["Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen à vif.","Faites revenir l'oignon et les champignons 5 min. Salez, poivrez.","Ajoutez le riz et faites-le revenir 1 à 2 min pour le nacrer (l'enrober d'huile).","Déglacez (versez) avec le vin blanc.","Ajoutez l'eau et le bouillon de légumes émietté et faites cuire à petits bouillons 10 à 15 min jusqu'à ce que le riz soit cuit. Remuez régulièrement.","Astuce : Ajoutez un peu d'eau si le riz n'est pas assez cuit.","En parallèle, coupez le savola à la truffe en morceaux.","Hors du feu, incorporez le savola à la truffe en morceaux et mélangez jusqu’à ce qu’il fonde et lie le risotto.","Le risotto doit rester crémeux et légèrement coulant.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"19747","nom":"Truite fumée, petits pois et orzo citronnés","image":"images/19747.webp","ingredients":[["gousse d'ail (2.5g)","0.5"],["crème (100g)","100 g"],["pâtes orzo (200g)","200 g"],["truite fumée (100g)","100 g"],["citron jaune (75g)","0.5"],["échalote (25g)","1x"],["petits pois (avec cosses) (300g)","300 g"]],"cuisine":["sel","poivre","huile d'olive"],"etapes":[{"titre":"L'orzo","items":["Portez à ébullition une casserole d’eau salée.","Pendant ce temps, écossez les petits pois.","Faites cuire l'orzo et les petits pois selon le temps indiqué sur le paquet d'orzo.","Astuce : conservez un bol d'eau de cuisson des pâtes pour allonger la sauce en fin de recette."]},{"titre":"La crème","items":["Émincez l'échalote.","Dans une sauteuse, faites chauffer un filet d'huile d'olive à feu moyen.","Faites revenir l'échalote 5 min environ. Poivrez. Ne salez pas, le poisson fumé apporte déjà du sel.","En parallèle, coupez la truite fumée en morceaux.","Pressez le citron.","Pressez ou hachez l'ail.","Au bout des 5 min de cuisson de l'échalote, versez la crème dans la sauteuse et portez à ébullition 30 sec.","Ajoutez l'ail et le jus de citron. Poursuivez la cuisson à feu doux 2 min environ.","Hors du feu, ajoutez l'orzo égoutté, les petits pois et la truite dans la sauteuse. Mélangez bien.","Astuce : ajoutez un peu d'eau de cuisson des pâtes pour lier la sauce et la rendre plus onctueuse grâce à l'amidon qu'elle contient.","Goûtez et rectifiez l'assaisonnement si nécessaire."]}]},{"id":"15759","nom":"Wok d'aiguillettes de poulet miel-sésame","image":"images/15759.webp","ingredients":[["sauce soja salée (23g)","20 ml"],["nouilles asiatiques (120g)","120 g"],["aiguillette de poulet La Nouvelle Agriculture (250g)","250 g"],["oignon jaune (110g)","1x"],["carotte (200g)","2x"],["coriandre (5g)","qq brins"],["sésame doré (10g)","10 g"],["gingembre (20g)","1 à 3 cm"]],"cuisine":["sel","poivre","huile de cuisson (mélange 4 huiles par exemple)","1 càs miel"],"etapes":[{"titre":"Les légumes","items":["Épluchez et coupez les carottes en fins bâtonnets (julienne).","Émincez l'oignon.","Épluchez et hachez le gingembre.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen.","Faites revenir l'oignon, le gingembre et les carottes 15 min environ. Salez légèrement, poivrez.","À mi-cuisson, ajoutez un fond d'eau, couvrez et poursuivez la cuisson jusqu'à ce que les carottes soient tendres.","Pendant ce temps, faites cuire les nouilles."]},{"titre":"Les nouilles","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet.","Remuez régulièrement pour éviter qu'elles ne collent entre elles pendant la cuisson.","Une fois cuites, égouttez-les et passez-les sous l'eau froide pour stopper leur cuisson.","En parallèle, faites cuire les aiguillettes de poulet."]},{"titre":"Les aiguillettes de poulet","items":["Dans une poêle, faites chauffer un filet d'huile de cuisson à feu vif.","Faites dorer les aiguillettes de poulet 5 à 8 min en les retournant régulièrement, jusqu'à ce qu'elles soient cuites à cœur (la chair n'est plus rose). Poivrez.","A mi-cuisson, ajoutez le miel et le sésame doré et mélangez bien."]},{"titre":"A table !","items":["Une fois le tout cuit, ajoutez les nouilles et la sauce soja dans la sauteuse des légumes.","Mélangez bien et poursuivez la cuisson 1 à 2 min pour que le tout soit chaud.","Ajoutez ensuite les aiguillettes de poulet en récupérant bien la marinade miel - sésame et mélangez délicatement.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Ciselez la coriandre (en entier, les tiges se consomment).","Au moment de servir, parsemez-la sur le wok."]}]},{"id":"15286","nom":"Wok de boeuf au fenouil, sauce soja et sésame","image":"images/15286.webp","ingredients":[["sauce soja salée","40 ml"],["emincés de boeuf marinés","200 g"],["sésame doré","10 g"],["oignon jaune (110g)","1x"],["bulbe de fenouil (200g)","1x"],["gousse d'ail","0.5"],["riz concassé du Pendjab","150 g"]],"cuisine":["sel","poivre","huile de cuisson","1 vinaigre blanc (càc)","1 maïzena (càc)","1 eau tiède (càs)","1 sucre (càs)"],"etapes":[{"titre":"La marinade","items":["Dans un bol, diluez la maïzena dans l'eau tiède.","Ajoutez la sauce soja, le vinaigre, le sucre et les émincés de boeuf. Poivrez.","Ne salez pas, la sauce soja apporte déjà du sel.","Mélangez bien et laissez mariner au réfrigérateur 10 min."]},{"titre":"Les légumes","items":["Pressez ou hachez l'ail.","Émincez l'oignon.","Coupez la base et les tiges à ras du bulbe de fenouil. Retirez la partie dure au centre et émincez le reste.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir le fenouil, l'ail et l'oignon 15 min environ.","Pendant ce temps, faites cuire le riz."]},{"titre":"Le riz","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le riz selon les indications du paquet."]},{"titre":"A table !","items":["Au bout des 15 min de cuisson des légumes, ajoutez la viande avec la marinade et le sésame.","Poursuivez la cuisson 5 min.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Désgustez votre wok de boeuf parsemé de sésame accompagné du riz."]}]},{"id":"19277","nom":"Wok de nouilles pimenté au chou pak choy, champignons et purée de cacahuètes","image":"images/19277.webp","ingredients":[["nouilles asiatiques","120 g"],["purée de cacahuètes","30 g"],["gousse d'ail (4g)","1x"],["champignons de Paris blancs","250 g"],["sauce soja salée","20 ml"],["huile de sésame toasté","20 ml"],["cacahuètes grillées sans sel","25 g"],["cébette (16g)","1x"],["chou pak choy (135g)","1x"],["piment oiseau (2g)","1x"],["oignon jaune (110g)","1x"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"La garniture","items":["Coupez les champignons en tranches.","Émincez l'oignon.","Coupez la base du chou pak choy et émincez-le.","Pressez ou hachez l'ail.","Hachez le piment (plus ou moins selon votre sensibilité). Lavez-vous bien les mains après l'avoir manipulé, il peut irriter la peau.","Portez à ébullition une casserole d'eau salée pour la cuisson des nouilles.","Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu vif.","Faites revenir les légumes et le piment 5 min, puis baissez à feu moyen et poursuivez la cuisson 5 min environ. Salez et poivrez légèrement. Remuez régulièrement.","Astuce : le piment est fort, n'en mettez qu'une petite quantité pour commencer et ajustez selon votre goût.","En parallèle, faites cuire les nouilles selon les indications du paquet."]},{"titre":"Les nouilles","items":["Pendant que les nouilles cuisent, dans un bol versez la sauce soja, la purée de cacahuètes et l'huile de sésame.","Ajoutez une demi louche d'eau de cuisson des nouilles par personne et mélangez bien jusqu'à l'obtention d'une sauce lisse et homogène."]},{"titre":"Le wok","items":["Retirez la base de la cébette et émincez-la.","Concassez les cacahuètes.","Une fois le tout cuit, ajoutez les nouilles et la sauce à la sauteuse des légumes. Mélangez bien pendant 2 à 3 min pour tout enrober.","Astuce : ajustez la quantité d'eau de cuisson nécessaire pour une sauce onctueuse.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Parsemez le tout de cébette et de cacahuètes."]}]},{"id":"16877","nom":"Wok de poulet, cacahuètes et chou pak choy","image":"images/16877.webp","ingredients":[["sauce soja salée","40 ml"],["nouilles asiatiques","120 g"],["carotte (120g)","1x"],["oignon jaune","0.5"],["gingembre","1 à 3 cm"],["gousse d'ail","0.5"],["cacahuètes grillées sans sel","25 g"],["filet de poulet La Nouvelle Agriculture (300g)","2x"],["chou pak choy (135g)","1x"]],"cuisine":["sel","poivre","huile de cuisson"],"etapes":[{"titre":"Les nouilles asiatiques","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire les nouilles selon les indications du paquet.","Une fois cuites, égouttez-les et passez-les sous l'eau froide pour stopper la cuisson.","En parallèle, préparez le reste des ingrédients."]},{"titre":"La préparation","items":["Émincez l'oignon","Coupez la base et émincez le chou pak choy.","Épluchez et râpez la carotte.","Pelez et hachez l'ail et le gingembre.","Coupez le poulet en morceaux."]},{"titre":"La cuisson","items":["Dans une sauteuse, faites chauffer un filet d'huile de cuisson à feu moyen à vif.","Faites revenir l'oignon, le poulet, le chou pak choy, l'ail et le gingembre 5 min.","Au bout des 5 min, ajoutez les nouilles, la carotte et la sauce soja et poursuivez la cuisson 3 min jusqu'à ce que le poulet soit cuit à coeur (la chair n'est plus rose).","Salez légèrement et poivrez.","Goûtez et rectifiez l'assaisonnement si nécessaire.","Au moment de servir, parsemez de cacahuètes."]}]},{"id":"18668","nom":"Wrap hack aux épinards, champignons, cheddar et oeufs brouillés à la ciboulette","image":"images/18668.webp","ingredients":[["tortillas (200g)","4x"],["champignons de Paris blancs","250 g"],["gousse d'ail (6g)","1x"],["cheddar râpé","60 g"],["ciboulette","qq brins"],["pousses d'épinards","100 g"]],"cuisine":["sel","poivre","huile d'olive","vinaigre de votre choix","2 oeuf","beurre"],"etapes":[{"titre":"Les champignons","items":["Coupez les champignons de Paris en tranches.","Pressez ou hachez l'ail.","Dans une sauteuse, faites chauffer un filet d'huile d'olive et une noix de beurre à feu moyen.","Faites cuire les champignons et l'ail 10 min environ jusqu'à ce qu'ils soient dorés. Salez, poivrez.","Astuce : les champignons sont prêts quand ils ont rendu leur eau et commencent à accrocher légèrement, avec une belle couleur brun-noisette.","Lorsque les champignons sont cuits, débarrassez-les et gardez la sauteuse pour la fin de la recette.","Pendant ce temps, préparez le reste des ingrédients."]},{"titre":"Les œufs brouillés","items":["Ciselez la ciboulette.","Dans un saladier, battez les œufs en omelette. Ajoutez la ciboulette, salez, poivrez. Mélangez bien.","Dans une poêle, faites chauffer un filet d'huile d'olive à feu moyen.","Versez les oeufs et remuez-les constamment pendant 3 à 5 min jusqu'à ce qu'ils soient brouillés et cuits."]},{"titre":"Les wrap hack","items":["Fendez un coté de chaque tortilla en partant du centre vers le bord (un rayon).","Déposez sur le premier quart de la tortilla des champignons, sur le deuxième quart des œufs brouillés et du cheddar puis sur le troisième quart des pousses d'épinards.","Repliez chaque quart sur le suivant, jusqu’à obtenir une enveloppe triangulaire.","Répétez l'opération jusqu'à épuisement des ingrédients.","Faites chauffer la sauteuse des champignons à feu vif et faites dorer les wraps 2 min de chaque côté.","Assaisonnez le reste des pousses d'épinards d'huile d'olive et de vinaigre."]}]},{"id":"20089","nom":"Wraps avocat, quinoa et menthe","image":"images/20089.webp","ingredients":[["fromage blanc (100g)","100 g"],["tortillas (200g)","4x"],["avocat (180g)","1x"],["quinoa blanc (100g)","100 g"],["menthe (5g)","qq brins"],["oignon rouge (110g)","1x"],["poivron rouge (160g)","1x"],["roquette (50g)","50 g"],["gousse d'ail (3g)","0.5"]],"cuisine":["2 càs huile d'olive","50 ml vinaigre (blanc ou de cidre)","50 ml eau","sel","poivre","vinaigre de votre choix"],"etapes":[{"titre":"Les pickles","items":["Emincez l'oignon.","Dans une petite casserole, portez à ébullition l'eau et le vinaigre. Mélangez bien.","Hors du feu, ajoutez l'oignon et laissez reposer le temps de la recette."]},{"titre":"Le quinoa","items":["Portez à ébullition une casserole d'eau salée.","Faites cuire le quinoa selon les indications du paquet.","Une fois cuit, égouttez le quinoa et laissez-le tiédir quelques minutes.","Astuce : le quinoa se gorge d'eau à la cuisson, égouttez-le donc bien avant de l'utiliser dans les wraps.","Pendant la cuisson du quinoa, préparez la sauce et les crudités."]},{"titre":"La sauce","items":["Effeuillez la menthe.","Pelez l'ail.","Dans le bol d'un mixeur, ajoutez l'ail, la menthe, le fromage blanc et l'huile d'olive. Salez, poivrez.","Mixez jusqu'à obtenir une sauce homogène."]},{"titre":"Les crudités","items":["Emincez finement le poivron.","Épluchez et coupez l'avocat en petits dés juste avant de garnir les wraps pour éviter qu'il ne noircisse."]},{"titre":"Les wraps","items":["Passez les wraps quelques secondes au micro-ondes pour les tiédir.","Répartissez dessus un peu de sauce au fromage blanc.","Égouttez les pickles, puis déposez un peu de quinoa, d'avocat, de poivron, de pickles et quelques feuilles de roquette par-dessus.","Roulez les wraps bien serrés.","Assaisonnez le reste de roquette d'un filet d'huile d'olive et de vinaigre.","Servez les wraps accompagnés de la roquette."]}]}];
